INSERT INTO decisions (id,scene_id, decision_order, character_id, dialogue)
VALUES
--TUTORIAL
(1,1, 1, 2, '¡Hola!,Yo soy Ángela, la creadora de este juego, y estoy aquí para enseñarte cómo funciona.'),
(2,1, 2, 2, 'Este juego consiste en explorar historias que giran en torno a la violencia machista.'),
(3,1, 3, 2, 'Queremos ayudarte a entender mejor este tema a través de diferentes situaciones y decisiones.'),
(4,1, 4, 2, 'Cuando pulses en las opciones que tienes abajo, la historia irá avanzando. '),
(5,1, 5, 2, 'A lo largo de la historia, habrá momentos en los que tendrás que tomar decisiones importantes... ¡Como ahora!'),
(6,1, 6, 2, '¿Ves esas barritas que acaban de cambiar ? Son la representación del estado psicologico de la protagonista y el estado de su relación '),
(7,1, 7, 2, 'Shh , no te voy a decir cuál es cuál, para que no hagas trampas'),
(8,1, 8, 2, 'Estas decisiones afectan al futuro de la historia.'),
(9,1, 9, 2, 'Cada opción que elijas llevará a resultados distintos, así que piensa bien antes de decidir.'),
(10,1, 10, 2, 'También vamos a movernos entre diferentes escenarios ¿Vamos?'),
(11,2, 1, 2, 'Bualá, estamos en el parque, es la magia de la programación'),
(12,2, 2, 2, 'Y te voy a ahorrar todos los trayectos'),
(13,3, 1, 2, '¡Como ahora!, ¿Chulo no?'),
(14,3, 2, 2, 'Quedate con esta habitación, que creo que va a ser importante'),
(15,3, 3, 2, '¡Vamonos de vuelta a mi cuarto!'),
(16,4, 1, 2, 'Pues nada, creo que eso es todo por mi parte'),
(17,4, 2, 2, 'Y recuerda, no hay respuestas perfectas. Lo importante es que reflexiones y aprendas del proceso.'),
(18,4, 3, 2, 'Pues, ¡A jugar!'),

--INTRO H1
(19,5, 1, 2, '¡Bienvenido a Bella’s Heart, una experiencia narrativa inmersiva que te invita a explorar las complejidades de una relación y las decisiones que afectan profundamente la dinámica entre dos personas!'),
(20,5, 2, 2, 'En esta historia, encarnarás a Bella, una joven que ha decidido dar un gran paso al mudarse con su pareja, David'),
(21,5, 3, 2, ' Tu misión será tomar decisiones en momentos clave de la vida de Bella'),
(22,5, 4, 2, 'Cada decisión tendrá consecuencias, algunas inmediatas y otras a largo plazo'),
(23,5, 5, 2, 'Eres la voz interna de Bella, su guía y conciencia. A medida que avanzas por los capítulos, serás quien la ayude a interpretar sus emociones, analizar los comportamientos de David y decidir el mejor camino para ella. '),
(24,5, 6, 2, 'Esta no es solo una historia de amor; es una exploración de los límites, la confianza y la búsqueda del bienestar personal. Toma decisiones con sabiduría, y recuerda: cada elección cuenta.'),
(25,5, 7, 2, '¿Empezamos?'),
 --CAP 1
(26,6, 1, 1, 'Bueno, aquí estamos, en nuestro primer hogar juntos. ¿Qué te parece? ¿Te imaginas todas las cosas increíbles que vamos a vivir aquí?'),
(27,6, 2, 1, 'Claro que sí. Todo es nuevo, pero estoy seguro de que juntos podemos con esto. Este lugar será nuestro refugio, ¿no te parece?'),
(28,6, 3, 1, 'Sabía que lo verías así. Estar aquí contigo hace que todo sea más fácil y emocionante'),
(29,6, 4, 1, 'Lo entiendo, Bella. Este paso es grande para ambos. Pero estoy aquí para que lo enfrentemos juntos. Confío en que todo saldrá bien.'),
(30,6, 5, 1, 'No puedo dejar de pensar en lo afortunado que soy. Tenerte aquí conmigo... significa todo para mí. Te quiero, Bella.'),
(31,6, 6, 1, '(David y Bella están en la sala del apartamento. Una mesa de centro nueva, de vidrio y metal, está colocada en el centro. Bella, quien había imaginado un diseño diferente, se detiene frente a ella, sorprendida.)'),
(32,6, 7, 1, 'Sí, me pareció perfecta para el espacio. Sabía que teníamos que decidirlo juntos, pero la vi en oferta y no pude resistirme. ¿A que se ve increíble?' ),
(33,6, 8, 1, '(Con una sonrisa tranquilizadora.)—Entiendo lo que dices, Bella, pero pensé que sería más fácil si me adelantaba con esto. Además, estoy seguro de que te acostumbrarás a ella. Solo quiero que todo esté perfecto para los dos.'),
(34,6, 9, 1, 'Sé que no es lo que imaginabas, pero créeme, una mesa rústica no habría quedado bien aquí. Además, no quería que te estresaras con más decisiones.'),
(35,6, 10,1, ' Y las tomaremos , no te preocupes , solo pensaba que podia quitar estres si esto nos lo quitabamos de encima rapido'),
(36,6, 11,1, 'Bella, entiendo que querías algo diferente, pero ¿no crees que es mejor centrarnos en disfrutar de nuestro espacio en lugar de preocuparnos por detalles? Quiero que esto sea un hogar para los dos, no que se convierta en una fuente de estrés.'),
(37,6, 12,1, '¿Vale?'),
(38,6, 13,1, 'Sabes, Bella, lo último que quiero es que te sientas mal por esto. Tal vez no siempre lo haga perfecto, pero quiero que sepas que siempre pienso en lo mejor para los dos.'),
(39,6, 14,NULL, '(La mañana pasa entre quehaceres y otras cosas)'),
(40,6, 15,NULL, '(Un rato más tarde, abres la puerta de casa. Un delicioso aroma flota en el aire, envolviendo el ambiente con una calidez inesperada.)'),
(41,7, 1, 1, '(David aparece en la cocina, con una sonrisa tímida.)— ¡Sorpresa!'),
(42,7, 2, 1, '(Acercándose despacio) — Quería hacerte una pequeña sorpresa… para compensar el pequeño rifirrafe de esta mañana. No podía dejarlo así.'),
(43,7, 3, 1, 'Sabía que te gustaría. Quiero que sepas cuánto valoro que estés aquí conmigo. No quiero que nada nos afecte, ni siquiera esas pequeñas diferencias.'),
(44,7, 4, 1, 'Eso es todo lo que quiero, Bella. Que te sientas feliz y segura aquí conmigo. Sé que no siempre acierto, pero lo importante es que estamos juntos, ¿verdad?' ),
(45,7, 5, 1, '(Con una ligera sonrisa tensa.)Entiendo lo que dices, Bella. No quiero que pienses que no valoro tus opiniones. Es solo que a veces siento que tiendes a preocuparte demasiado por cosas pequeñas. Quiero que confíes en que siempre buscaré lo mejor para nosotros.'),
(46,7, 6, 1, 'Por supuesto que ambos tenemos voz, Bella. No quiero que sientas lo contrario. Solo fue una tonteria. Vamos a dejar esto atrás, ¿sí?'),
(47,7, 7, 1, '(Sonríe con alivio, relajando la tensión en su expresión.) —Exactamente, Bella. No quiero que te preocupes por cosas que yo puedo manejar. Confía en mí, todo lo que hago es pensando en nosotros.'),
(48,7, 8, 1, 'Entiendo que es importante para ti, Bella. Quizás soy yo quien necesita relajarse un poco. Estoy acostumbrado a tomar decisiones rápidas, pero puedo intentar ser más considerado contigo. Asi que olvidemoslo '),
(49,8, 1, NULL, '(El día sigue avanzando '),
(50,8, 2, NULL, '(Y Bella acaba de volver de comprar unas cosas )'),
(51,8, 2, 1, '(Bella entra al apartamento con una sonrisa, cargando la revista. David levanta la vista al verla y sonríe, pero sus ojos reflejan una mezcla de sorpresa y ligera molestia.)' ),
(52,8 ,2, 1, '¡Vaya, mira quién ha llegado! ¿Dónde te habías metido? Pensé que todavía estabas por aquí.'),
(53,8 ,3, 1, 'Sí, lo sé, pero... ¿qué pasa si algo te ocurre? Es una ciudad nueva para nosotros, y no siempre es seguro andar sola. Tal vez deberías avisarme cada vez que vayas a salir. Así no estaré aquí pensando en si estás bien o no.'),
(54,8, 4, 1, '(En tono de broma)Lo sé, lo sé. Pero imagínate si pasa algo y no sé dónde estás... Tal vez deberías avisarme cada vez que salgas, ¿no crees? Así me evitas preocupaciones.'),
(55,8, 5, 1, 'No es para tanto. Solo quiero asegurarme de que estés bien. Sabes que no podría soportar que algo le pasara a esa cara bonita.'),
(56,8, 6, 1, 'Lo sé, Bella, pero no cuesta nada enviar un mensaje rápido. No es que quiera controlarte, es solo que me preocupo por ti. ¿No te gustaría saber dónde estoy si fuera al revés?'),
(57,8, 7, 1, 'Exacto. No quiero que esto se sienta como una obligación, pero si me envías un mensaje rápido, me sentiré más tranquilo.'),
(58,8, 8, 1, 'Entiendo. No quiero que sientas que es una obligación, pero me hace sentir más tranquilo saber que estás bien. No es tanto pedir, ¿verdad?'),
(59,8, 9, 1, 'Bueno, ahora que estás aquí, ¿por qué no me enseñas esa revista? Seguro que encontramos algo interesante para decorar.'),
(60,8, 10,NULL,'¡Enhorabuena!'),
--CAP 2
(61,9, 1 , NULL, '(Bella sale de la habitación vestida con jeans ajustados y una camiseta escotada. David, sentado en el sofá, levanta la vista hacia ella, sonriendo con calma.)'),
(62,9,2,1, 'Vaya, te ves muy bien, guapa. Aunque… me acordé de esa blusa que te regalé hace poco. La azul, ¿te acuerdas? Creo que te queda espectacular.'),
(63,9,3,1, '(Se levanta del sofá y se acerca a ella con un tono cariñoso.)Lo sé, lo sé, pero esa blusa que te di te hace ver aún más increíble. Tiene ese toque elegante que siempre me encanta. ¿No te gustaría ponértela?'),
(64,9,4,1,'(Ríe suavemente y la abraza por la cintura.)—Claro que me gusta. Siempre te ves hermosa, pero es que la otra blusa tiene algo especial. No sé, siento que te hace resaltar más, como la reina que eres.'),
(65,9,5,1, '(Sonríe con satisfacción.)—Sabía que me entenderías. Ya verás, vas a deslumbrar a todos.'),
(66,9,6,1, '—¡No es eso, para nada! Me encanta cómo te ves siempre. Solo que a veces pienso que ciertas prendas resaltan aún más tu belleza. Quiero verte brillar.'),
(67,9,7,1, '— No quiero que lo tomes a mal. Es solo que pensé que te gustaba mucho… pero si prefieres ponerte otra cosa, está bien.'),
(68,9,8,1, '(Asiente con una sonrisa, intentando parecer comprensivo.)—Lo sé. No quiero que sientas presión. Es solo una sugerencia. Tú decides lo que quieras.'),
(69,9,9,NULL,'(Bella vuelve con la blusa que David le regaló. Él sonríe con satisfacción, observándola con admiración.)'),
(70,9,10,1, 'Ahora sí. Te ves espectacular, como siempre.'),
(71, 9, 11, 1, '(Con tono animado, buscando cerrar la tensión.)—Venga, que vamos a llegar tarde a la fiesta. Y ya verás, vas a ser la más guapa de todas.'),
(72, 10,1,NULL, '(David y Bella han acudido a una fiesta de varios amigos , La música suena de fondo, y el ambiente está lleno de risas y charlas.)'),
(73, 10,2,NULL, '(Bella se encuentra conversando con Alex, un viejo amigo que no había visto en mucho tiempo.)'),
(74, 10,3,3,'¡Bella! ¡Cuánto tiempo sin verte! Ni me acordaba de la última vez que coincidimos. Creo que fue en aquella reunión en casa de Julia, ¿verdad?' ),
(75, 10,4,3, 'No me puedo quejar. Trabajo, proyectos... ya sabes, lo típico. Pero y tú, ¿qué tal? Escuché que te mudaste con tu pareja. ¿Cómo va eso?'),
(76,10,5,3, 'Eso suena emocionante, pero también agotador. Mudarse siempre es un caos. Espero que te esté yendo bien con todo. ¿Y David? ¿Está por aquí?'),
(77,10,6,3, 'No te preocupes. Seguro que en algún momento nos cruzamos. Me alegra verte tan bien, Bella. Siempre me pareciste una persona llena de energía.'),
(78,11,1,NULL, '(Más tarde llegais a casa, David cierra la puerta detrás de ellos y se quita la chaqueta. Bella, todavía animada por la fiesta, se dirige a la cocina por un vaso de agua.)'),
(79,11,2,1,'(Con una sonrisa algo tensa.)—Sí, estuvo bien... aunque hubo algunas cosas que me hicieron sentir un poco incómodo.'),
(80,11,3,1, 'Bueno... No es nada serio, pero noté que hablaste mucho con ese chico, Alex, ¿no? Parecían bastante cercanos.'),
(81,11,4,1,'Lo sé, Bella, pero… ya sabes cómo son algunas personas. No siempre tienen buenas intenciones,y no me gustaría que nadie malinterpretara las cosas.'),
(82,11,5,1,'No es que tú lo hayas hecho. Pero hay hombres que, cuando ven a una chica simpática, pueden confundirse. Solo quiero evitar que te metas en situaciones incómodas.'),
(83,11,6,1,'Lo sé, Bella, pero es diferente ahora. Estamos juntos, y la gente puede percibir las cosas de forma distinta. Me preocupo porque eres importante para mí. No es para controlarte, es solo un consejo.'),
(84,11,7,1,'Gracias, Bella. Eso es todo lo que quiero. No es para controlarte, es solo para que evitemos situaciones incómodas. Sé que a veces soy demasiado protector.'),
(85,11,8,1,'No es para tanto, Bella. Es solo un consejo. Yo confío en ti, pero también quiero evitar situaciones que puedan ser incómodas para los dos.'),
(86,11,9,1,'(Se acerca, la toma de la mano y le da un beso en la frente.) —Sabía que me entenderías. Todo lo que hago es porque me importas.'),
(87,11,10,1,'Claro, no te estoy pidiendo que cambies, Bella. Solo que seas un poco más consciente de estas situaciones. No es para limitarte, es solo para evitar incomodidades innecesarias.'),
(88,11,11,1,'(Sonríe aliviado y la toma suavemente de la mano.) —Eso es todo lo que quiero, Bella. Confío en ti. Gracias por entenderme.'),
(89,11,12,1,'Bueno, dejando eso de lado, ¿qué tal si nos relajamos un poco? ¿Vemos algo en la televisión antes de dormir?'),
(90,11,13,1,'(Ríe ligeramente.)—¿Esa? Sí, claro. Lo que tú quieras, guapa. Esta noche es tuya.'),
(91,11,14,1, 'Y, oye, me alegra que podamos hablar de estas cosas. Lo importante es que siempre estemos bien.'),
(92,11,15,NULL,'¡Enhorabuena!'),
--CAP3
(93,12,1,NULL,'(Bella se está arreglando para ir al trabajo)'),
(94,12,2,1,'David entra en la habitación con una pequeña caja envuelta en papel de regalo.'),
(95,12,3,1,'La observa mientras se ajusta la blusa frente al espejo, sonriendo con un aire de complicidad.'),
(96,12,4,1, '(Acercándose con una sonrisa y sosteniendo la caja.)—Antes de que te vayas… tengo algo para ti.'),
(97,12,5,1, 'No hace falta una ocasión para recordarte cuánto te quiero.'),
(98,12,6,1, '(La mira expentante)'),
(99,12,7,1, '(Le aparta el cabello con suavidad.)—Quiero que lo uses siempre. Me gusta la idea de que tengas algo mío contigo.'),
(100,12,8,1,'(David le ayuda a ponerse el collar y la observa con satisfacción.)—Te queda perfecto. Déjame hacerte una foto.'),
(101,12,9,1,'(David saca el teléfono de Bella de la mesa de noche y lo enciende, pero al intentar desbloquearlo, se encuentra con la pantalla de la contraseña.)'),
(102,12,10,1, 'Dámela, así la desbloqueo rápido.'),
(103,12,11,1, '(Frunce el ceño levemente.)—Bella, es más fácil si me la dices. No es como si fuera un secreto, ¿no?'),
(104,12,12,1, '(Su tono se vuelve más serio.)—Bella… ¿Por qué haces esto tan complicado? ¿Es que no confías en mí?'),
(105,12,13,1, '(David introduce la contraseña y sonríe con satisfacción mientras abre la cámara y toma la foto.)-Ponte guapa' ),
(106,12,14,1, '(Cruza los brazos, con una ligera expresión de molestia.)—Bella, somos pareja. No debería haber nada que esconder entre nosotros.'),
(107,12,15,1, '(Mostrándole la pantalla.)—Mira, te ves preciosa.'),
(108,12,16,1, '(Suspira y desvía la mirada.)—No pensé que esto fuera un problema para ti. Solo quería hacerte una foto, no es como si estuviera revisando tus mensajes.'),
(109,12,17,1, '(Le entrega el teléfono con una sonrisa ligera.)—No sé cómo lo haces, pero cada día te ves más hermosa.'),
(110,12,18,1,'—Bueno… No pasa nada, me voy a duchar(Le deja el móvil en la mesa sin tomar la foto y se gira para salir de la habitación.)'),
(111,12,19,1,'-Me voy a duchar, guapa'),
(112,12,20,1, '(Más tarde David sale del baño, ya con una camiseta puesta, secándose el cabello. Bella revisa su bolso cerca de la puerta, lista para salir. '),
(113,12,21,1, '(Mientras Bella está terminando de arreglarse, David sale de la ducha secándose el cabello con la toalla. )'),
(114,12,22,1, 'No pasa nada, Bella, tú sabrás lo que haces con tu espacio personal.'),
(115,12,23,1, '(Con una sonrisa y tono despreocupado)—Oye… ¿por qué no te quedas hoy?'),
(116,12,23,1,'(Deteniéndose cerca de ella, tono aparentemente casual.) —¿Por qué no te quedas hoy?'),
(117,12,25,1, 'No tengo nada que hacer hoy. Podrías llamar y decir que estás enferma. Nos quedamos aquí, tranquilos, tú y yo.'),
(118,12,24,1,'—No tienes que ir, ¿no? Llama y di que estás enferma.Quédate conmigo.'),
(119,12,25,1,'(Encogiéndose de hombros, sin perder la sonrisa.)—No es tan importante. No creo que te echen de menos por un día.'),
(120,12,26,1, '(Frunce el ceño, sorprendido.)—¿Qué comentario?'),
(121,12,27,1, 'Un día, solo uno. ¿Qué puede pasar? Además, últimamente estás muy estresada. Te vendría bien descansar.'),
(122,12,28,1, '(Frunce el ceño. La sonrisa desaparece por completo.)—Bella… ¿De verdad te vas a poner así por una tontería?'),
(123,12,29,1, 'Seguro que puedes moverla. Llegar un poco más tarde, no pasa nada.'),
(124,12,30,1, 'Bueno, si prefieres molestarte por una cosa tan mínima, adelante, cada uno con sus prioridades.'),
(125,12,31,1, 'Solo que hoy no tengo nada y pensaba que podríamos pasar el día juntos…'),
(126,12,32,1, '(Sin mirarla directamente, se da la vuelta y empieza a caminar hacia el salón.)—Haz lo que tengas que hacer.'),
(127,12,33,1, 'Solo quería pasar un rato contigo.Pero si no puede ser, no pasa nada.(Se gira y sale de la habitación)'),
(128,12,1,NUll, '(Se escucha el sonido de el sentandose en el sofá)'),
(129,13,2,1, '( David está sentado en el sofá, mirando el móvil)'),
(130,13,3,1, '(Silencio. No levanta la mirada. Ni siquiera un gesto.)'),
(131,14,1,null, '(Bella está sentada en una sala de reuniones, rodeada de compañeros y directivos. Tiene el móvil en modo vibración sobre la mesa, boca abajo.)'),
(132,14,2,null, '(En mitad de una intervención clave, el teléfono vibra. Bella echa un vistazo rápido. Es David.)'),
(133,14,3,null, '(Lo pone en silencio sin contestar. Segundos después, vuelve a vibrar. Vuelve a ser David.)'),
(134,14,4,null, '(Bella aprieta la mandíbula discretamente, pone el móvil en modo avión y lo guarda en el bolso.)'),
(135,14,5,4, '¿Pasa algo Bella?'),
(136,14,6,null, '(Cuando termina la reunión.Bella sale de la sala. Saca el móvil y llama a David)'),
(137,14,7,5,'Vaya… al final has decidido llamarme'),
(138,14,8,5,'Ya. Me imaginé. Supongo que no soy tan prioritario como todo lo demás.'),
(139,14,9,5, 'Vale. Pero podrías haberme avisado antes de entrar. Un simple mensaje.'),
(140,14,10,5,'Ya… Solo quería hablar contigo sobre lo de esta mañana.Pero bueno, está claro que no era tan importante.'),
(141,14,11,5,'Supongo que no. Solo quería hablar contigo sobre lo de esta mañana. Pero ya está.'),
(142,14,12,5,'No da igual , solo queria decirte que no me gusta estar así, con esta sensación. Pero bueno… si no se puede, ya está. Nos vemos esta noche.'),
(143,14,13,5,'¿Sí? No sabía si estabas bien, si seguías enfadada…Y tú ni un mensaje. Ni un "te llamo luego".'),
(144,14,14,5,'A veces me pregunto si lo harías si fuera al revés.Si yo no contestara durante horas, seguro que no lo tomarías tan bien.'),
(145,14,15,5, 'No te preocupes. Ya me acostumbraré.'),
(146,14,16,null, ' (Cuelga)'),
(147,14,17,5, 'Nos vemos esta noche.Si te queda tiempo, claro. (Cuelga)'),
(148,14,18,null, '(No voy a pedir perdón por trabajar. Aunque...)'),
(149,14,19,null, '(Podría haberle mandando un mensaje.)'),
(150,14,20,null, '(Aunque fuera uno corto.¿De verdad era tan difícil?)'),
(151,14,21,null, '(No sé. Podría haberlo intentado. Quizás habría evitado esto.)'),
(152,14,22,null,'(¿Pero por qué tengo que estar pendiente de avisarle siempre?) '),
(153,14,23,null,'(Pero ahora está molesto. Y otra vez me voy con esta sensación.) '),
(154,14,24,null,' (No quiero estar así con él.No me gusta cuando se siente mal por mi culpa.)'),
(155,14,25,null,'(Aunque no fuera culpa mía…¿Y si realmente lo hice sentir que no me importa?)'),
(156,14,26,null, '(Es mi pareja. Me quiere.Solo quería hablar conmigo. ¿Es tan grave?)'),
(157,14,27,null, '(El día sigue pasando y ya es la hora de volver a casa'),
(158,15,1,null, '(Bella entra al piso, con las llaves aún en la mano.)'),
(159,15,2,1, '(Se espera silencio o mal humor, pero encuentra a David en el sofá, tranquilo, con el móvil en la mano.) '),
(160,15,3,1, 'Hola… te estaba esperando.'),
(161,15,4,1, '(Se encoge de hombros con una pequeña sonrisa.) —No quiero tener problemas contigo.De verdad, Bella. Ya está. No hace falta darle más vueltas.'),
(162,15,5,1, '¿Para qué? Solo vamos a terminar diciendo cosas que nos hagan daño. No tiene sentido remover todo otra vez.'),
(163,15,6,1, '(Pausa breve. David se levanta del sofá, camina hacia ella con una actitud más ligera.)'),
(164,15,7,1, '¿Y si salimos a cenar? Tu sitio favorito, ¿te apetece?'),
(165,15,8,1, '(Se detiene. Su sonrisa se borra un poco.)—Otra vez aquí, encerrados. A veces siento que ya no te apetece hacer cosas conmigo.'),
(166,15,9,1,'Claro…Como quieras.'),
(167,15,10,1,'(Sonríe de inmediato, más aliviado que alegre.)—Sabía que dirías que sí.Te va a venir bien, ya verás. Nos despejamos, reímos un poco, como antes.'),
(168,15,11,1, '(Su expresión cambia. Frunce el ceño) —Ya… vale.'),
(169,15,12,1, 'No tardes, que voy haciendo la reserva.'),
(170,15,13,1, 'Está claro que últimamente eso es lo que más necesitas: parar. Incluso cuando estoy intentando hacer algo por los dos.'),
(171,15,14,1, 'Me alegra que quieras. Últimamente siento que estamos un poco distantes… y no quiero que se pierda lo que tenemos.'),
(172,15,15,1, 'Claro…No pasa nada.'),
(173,15,16,1,'Entonces vamos. Lo merecemos. Píntate un poco, ponte guapa. Te ves preciosa cuando te arreglas.'),
(174,15,17,1,'(Mirándola unos segundos, sin responder de inmediato.)—Vale.Tú cámbiate, yo voy mirando qué pedimos.'),
(175,15,18,1, '(Bella sale del dormitorio con un vestido sencillo, el pelo recogido con poco esfuerzo. David ya está listo, esperándola junto a la puerta con las llaves en la mano.)'),
(176,15,19,1, '(Sonriendo)—Estás preciosa.'),
(177,16,1,1, '(Llegan al restaurante )'),
(178,16,2,1, '(Sonríe, con tono ligero.)—Esto está tan bueno como siempre. ¿Te acuerdas de la primera vez que vinimos?'),
(179,16,3,1, 'Y no te gustó nada.'),
(180,16,4,1, '(Su tono baja, más suave.)-¿Estás bien?'),
(181,16,5,1, 'No lo sé… te noto distante.Como si estuvieras aquí, pero con la cabeza en otro sitio.'),
(182,16,6,1, '(Pone el tenedor sobre el plato y la mira más de frente.)Últimamente estás siempre cansada.'),
(183,16,7,1, 'Ya... Es solo que… no sé. Me esfuerzo por tener momentos así contigo, y a veces siento que no los disfrutas. Que estás en otra parte.'),
(184,16,8,1, 'A veces pienso que estás tan centrada en todo lo demás…El trabajo, las reuniones, las mil cosas de tu cabeza…Y yo, simplemente, quedo al margen.'),
(185,16,9,1, 'Siento que haces espacio para todo menos para mí. Y no quiero convertirme en alguien que solo comparte cenas silenciosas contigo.'),
(186,16,10,1, 'No lo parece. Y no te lo digo para reprocharte nada, solo que… echo de menos cómo eran las cosas antes. Cuando no tenía que luchar tanto por un rato contigo.'),
(187,16,11,1, 'Por eso mismo. Tal vez deberías relajarte un poco más. Desconectar. Pensar menos en lo que tienes que hacer y más en lo que estamos perdiendo.'),
(188,16,12,1,'No te estoy pidiendo que dejes tu vida por mí. Solo que no te olvides de nosotros.'),
(189,16,13,1,'(Pausa. Se encoge de hombros, algo tenso.)—Lo respeto. Solo que a veces me gustaría no sentirme en segundo plano.'),
(190,16,14,1,'(Le toma la mano con suavidad, satisfecho.) —Eso es todo lo que quiero. Que lo tengamos en cuenta.No por mí, por los dos.'),
(191,16,15,1,'(Baja un poco la mirada.)—Lo sé. Solo que… a veces siento que compito con eso.'),
(192,16,16,1,'Me alegra escucharlo.No quiero pelear. Solo quiero estar bien contigo.'),
(193,16,17,1,'(Su tono es contenido.)—Está bien. Lo entiendo. No voy a decir nada más.'),
(194,16,18,1,'No estoy molesto.(Le da un trago al vino, sin mirarla.)'),
(195,16,19,1,'(Pone los cubiertos con cuidado sobre el plato.)Bella, de verdad… dejémoslo. No quiero hablar más del tema. Ya está.'),
(196,16,20,NULL, '¡Oh no! Te has perdido la escena extra'),
(197,16,20,null, '¡Enhorabuena!'),
--CAP4
(198,17,1,NULL,'(Se escucha la puerta del piso abrirse. David entra con las llaves en la mano.)'),
(199,17,2,NULL, '(Deja las cosas en la entrada y avanza hacia el dormitorio.)'),
(200,17,3,1,'(Ve a Bella frente al espejo, maquillándose.)'),
(201,17,4,1,'¿Y eso? ¿Dónde vas tan guapa?'),
(202,17,5,1,'(Camina lentamente hacia ella.)—¿Hoy? No me habías dicho nada.'),
(203,17,6,1,'(Se apoya en el marco de la puerta.)—¿Y quién va?'),
(204,17,7,1,'(Suelta una risa breve, seca.) —Eva… esa es la que siempre te mete ideas raras, ¿no?'),
(205,17,8,1,'(Su tono sigue suave, pero baja la mirada un segundo antes de hablar.) —Claro. ¿Y hasta qué hora pensáis quedaros?'),
(206,17,9,1,'Bueno… solo ten cuidado. Ya sabes cómo son esas cenas: copas, risas, hablar más de la cuenta…'),
(207,17,10,1,'Nada, solo que a veces, con unas copas, una termina diciendo cosas que luego sacan de contexto. Y no todo el mundo es de fiar. Tú hablas desde la confianza, pero hay gente que escucha con otra intención.'),
(208,17,11,1,'(Se relaja visiblemente. Asiente con una sonrisa leve.)—Gracias. No te lo digo porque desconfíe de ti, Bella, tú sabes que confío…'),
(209,17,12,1,'No te estoy controlando, Bella. No lo hagas sonar así. Solo te estaba comentando. Es una cena, no una cuestión de Estado.'),
(210,17,13,1,'Y si ves que la cosa se alarga mucho o hay alcohol de más, no pasa nada si decides no quedarte.No todo el mundo está en la misma sintonía que tú.'),
(211,17,14,1,'(Su sonrisa se desvanece un poco.)—Solo te digo que tengas cuidado.'),
(212,17,15,1,'Ya sabes que me rayo a veces, pero si me avisas y me dices que llegarás temprano, me quedo tranquilo.'),
(213,17,16,1,'Yo solo… ya sabes. Me preocupo. Y a veces me cuesta no decir lo que pienso.'),
(214,17,17,1,'(Asiente lentamente.)—Está bien.No vuelvas muy tarde, ¿sí?'),
(215,17,18,1,'Estás guapísima, por cierto.Que lo pases bien.'),
(216,18,1,null,'(El bar tiene una atmósfera animada pero acogedora. Bella llega y encuentra a sus compañeras en una mesa redonda.)'),
(217,18,2,null, '(Se saludan con entusiasmo. Risas, besos en la mejilla, pedidos de vino)'),
(218,18,3,null,'(Pasan los primeros minutos hablando del trabajo y de chismes inofensivos.)'),
(219,18,4,null,'(En un momento más tranquilo, Laura, que está sentada junto a Bella, la mira con complicidad.)'),
(220,18,5,6, 'Oye, Bella… hace tiempo que no te pregunto. ¿Y tú con David qué tal vais?'),
(221,18,6,6,'(Le lanza una mirada de complicidad.) —¿“Normal” es bueno?'),
(222,18,7,7, 'Supongo que la rutina acaba atrapando un poco, ¿no?'),
(223,18,8,6,'¿Y tú cómo te sientes con eso?'),
(224,18,9,7,'Es que a veces no nos damos cuenta, pero nos vamos adaptando a cosas que no siempre nos sientan bien. Solo por no discutirlas. O por no romper el equilibrio.'),
(225,18,10,7,'Eso suena agotador, Bella.'),
(226,18,11,6,'Claro, pero… ¿eso no te deja a ti con el peso de sostener esa historia?'),
(227,18,12,7,'¿Y eso pasa a menudo?'),
(228,18,13,7,'¿Y siempre tienes que ser tú la que evita?¿No puede él trabajar sus inseguridades sin que tú tengas que ajustar todo?'),
(229,18,14,6,'¿Y él nota que lo haces?'),
(230,18,15,7,'Nadie dijo eso, Bella.'),
(231,18,16,6,'¿Y tú cómo estás con eso? ¿Te sientes bien?'),
(232,18,17,6,'Solo… da la sensación de que tú te adaptas mucho. Y no sé si él hace lo mismo.'),
(233,18,18,7,'A veces las cosas que no parecen grandes… son las que más pesan.'),
(234,18,19,6,'Está bien. No queremos incomodarte.'),
(235,18,20,6,'Solo asegúrate de que tú no te estés rompiendo por dentro mientras todo parece estar “bien” fuera.'),
(236,18,21,null,'(El grupo sigue charlando. Las risas han vuelto después del momento más íntimo. Bella se ha relajado un poco, o al menos lo intenta.)'),
(237,18,22,null, '(De repente, su móvil vibra sobre la mesa.)'),
(238,18,23,5, 'Mensaje  — David:“¿Ya habéis pedido algo?”'),
(239,18,24,null,'(Vuelve a sonar el movil)'),
(240,18,25,5,'Mensaje  — David:“¿Con quién estás al final? ¿Estás bien?”'),
(241,18,26,null, '(Vuelve a sonar el movil)'),
(242,18,27,5,'Mensaje  — David:“No me has dicho quién está. ¿Está Eva?”'),
(243,18,28,5,'David:“Solo quiero saber que estás bien, no me ignores.”'),
(244,18,29,null, '(Durante unos segundos mantiene el móvil en la mano,dudando. Luego lo pone en silencio y lo guarda en el bolso)'),
(245,18,30,5,'¿Hola?'),
(246,18,31,null,'(Se gira hacia sus amigas, sonríe y vuelve a la conversación)'),
(247,18,32,5, 'Mensaje — David:“¿Ya habéis terminado de cenar?” “No te olvides de avisarme si vais a otro sitio.”'),
(248,18,33,5, '(Más tarde, al sacar el teléfono, ve 6 mensajes de David en la pantalla)'),
(249,18,34,5,'David:“¿Y estáis en plan copas o qué? Porque si es eso, no te quedes mucho.”'),
(250,18,35,5,'Mensaje — David:“Bella, no me gusta que no contestes.”'),
(251,18,36,5,'David:“Vale. Es que me conozco cómo acaban esas cenas. No me gusta imaginarte por ahí de madrugada, con gente que no sé cómo es.”'),
(252,18,37,5,'Mensaje — David:“Solo quiero saber cómo estás.”'),
(253,18,38,6,'Bella deja el móvil un momento sobre la mesa.Laura la mira un segundo desde su sitio, como notando algo, pero no pregunta.El movil vuelve a sonar '),
(254,18,39,5,'Mensaje — David:“Me dejas con una sensación horrible cuando haces esto.”'),
(255,18,40,5,'David:“Avísame cuando pidas el taxi, ¿vale?”'),
(256,18,41,5,'Mensaje — David:“No te estoy controlando, solo me preocupo.”'),
(257,18,42,5,'Mensaje — David:“¿Vas a decirme algo antes de que llegues a casa o qué?”'),
(258,18,43,5,'(Llamada entrante: David)'),
(259,18,44,5,'¿En serio, Bella? ¿Por qué no contestas?'),
(260,18,45,5,'Yo solo me preocupo por ti. No quiero que esto sea un problema. Pero me siento ignorado.'),
(261,18,46,5,'Bueno…Pues nada pasalo bien'),
(262,18,47,6,'(Se estira un poco en la silla.)—Creo que oficialmente no puedo más. Que alguien me lleve.'),
(263,18,48,7, '(Le toca el brazo con suavidad.) —¿Estás bien?'),
(264,18,49,7,'Para lo que quieras bonita '),
(265,18,50,6,'¿Y si vamos a otro sitio? Hay un bar a dos calles, con música.'),
(266,18,51,7, '¡Sí! Solo una copa más y nos vamos a casa.'),
(267,18,52,6,'Venga, que mañana no madrugamos.'),
(268,18,53,7,'¿Qué dices? ¿Te animas?'),
(269,18,54,6,'(Con tono suave.)—¿Segura?'),
(270,18,55,6, 'Bueno, como quieras.Nosotras vamos un rato.'),
(271,18,56,null, '(Camino a casa. En el taxi. Mira el móvil.)'),
(272,18,57,5,'David: "¿Vienes ya no?"'),
(273,19,1,1,'(Bella abre la puerta. David está en el sofá. El televisor encendido, volumen bajo.)'),
(274,19,2,1,'¿Ya estás?'),
(275,19,3,1,'(La observa con gesto neutro.)—¿Te lo pasaste bien?'),
(276,19,4,1,'(Pone una sonrisa sutil. Se cruza de brazos.)—¿Y por qué querían que te quedaras más? ¿Les molestó que no fueras?'),
(277,19,5,1,'¿Y cómo reaccionaron?'),
(278,19,6,1,'Claro. Es que a veces me da la sensación de que no te entienden tanto. Que esperan que seas como ellas, que sigas el ritmo. Y si no lo haces, te miran raro. No sé si eso es amistad de verdad.'),
(279,19,7,1,'(Se queda callado)'),
(280,19,8,1,'(Frunce el ceño levemente.)—¿Con qué?'),
(281,19,9,1,'Exacto. Eso no es estar con gente que te acepta. Es estar en alerta. Midiéndote. Y tú no necesitas más presión en tu vida.'),
(282,19,10,1,'Y te fuiste antes. ¿Por qué? ¿Te apetecía de verdad? ¿O sentiste que tenías que volver?'),
(283,19,11,1,'Te quieren como compañía. No como persona. Tú necesitas rodearte de gente que te deje ser tú. Sin culpas, sin explicaciones.'),
(284,19,12,1,'Tú sabrás. Pero a veces me da la sensación de que te esfuerzas demasiado por estar bien con todos… Y al final, te quedas vacía'),
(285,19,13,1,'(Le acaricia la espalda con suavidad.)—Ya no eres la misma. Has crecido. Has cambiado tus prioridades.'),
(286,19,14,1,'Tú no te das cuenta. Pero ellas no son tan buena compañía como crees. Te arrastran a un tipo de dinámica que no te cuida. '),
(287,19,15,1,'(Le acaricia el hombro.)—Ven. Relájate. Te preparo algo caliente. Aquí puedes ser tú sin justificarte.'),
(288,19,16,1,'Bueno… si tú estás tranquila, entonces me callo. Tú sabrás. Después no me vengas llorando '),
(289,19,16,null, '¡Enhorabuena!'),
--CAP5
(290,20,1,null, '(Bella está en la cocina preparando la comida. Corta verduras mientras el agua hierve en una olla.)'),
(291,20,2,null, '"Ring"Se escucha el sonido de una notificación en el salón.La reconoce. Su móvil que lo había dejado cargando sobre la mesa.'),
(292,21,1,1, '(Entra al salón y ve a David de pie, con el teléfono en la mano.)'),
(293,21,2,1, '(Sin alterarse. Apenas gira la cabeza hacia ella.)—Te llegó un mensaje. Era del trabajo. Lo abrí por si era urgente.'),
(294,21,3,1, 'Para ti, supongo. Era de Marco. Te habla de un viaje. ¿Porqué no me habías dicho nada?'),
(295,21,4,1, '(Encogiéndose de hombros, como si no viera el problema.)—Porque estaba allí, vibrando sin parar. Y vi que era del trabajo. Pensé que te haría un favor.'),
(296,21,5,1, '(Frunce el ceño.) —¿De verdad te estás poniendo así por eso?'),
(297,21,6,1, '(Se cruza de brazos, su tono más relajado.)—No te pongas rara. Solo lo abrí porque vibraba sin parar.'),
(298,21,7,1, '¿No puedo mirar ni un mensaje del trabajo?'),
(299,21,8,1,'Y el mensaje era de Marco, ¿no? ¿Ese es el que organiza los viajes en tu oficina?'),
(300,21,9,1,'¿Estás hablando en serio? Era del trabajo, Bella. No te estoy revisando nada personal.'),
(301,21,10,1,'¿Y por qué no me habías dicho nada?'),
(302,21,11,1, 'Vaya... entonces ahora soy un controlador por mirar un mensaje en tu pantalla.'),
(303,21,12,1,'Ajá. Bueno. Ya me lo contarás.'),
(304,21,13,1,'A veces parece que estoy caminando sobre vidrio contigo.'),
(305,21,14,1,'(Le da una palmadita suave en el brazo, como restándole importancia. Se va hacia el sofá.)'),
(306,21,15,1,'(Seco. Sin mirarla.)—Pues genial. La próxima vez te dejo el móvil sonando todo el día y no toco nada.'),
(307,21,16,1,'(Suelta el aire por la nariz. Gira sobre sus talones.)—Vale. Haz lo que quieras.'),
(308,21,17,null, '(Se escucha la habitación cerrarse de un portazo)'),
(309,21,18,null, '(El día continúa sin muchas palabras.)'),
(310,22,1,null, '(Ya es de noche. Bella sale de la ducha con el en pijama, pensando en ir directa a dormir.)'),
(311,22,2,null, '(Desde la cocina, Bella percibe movimiento.El olor a comida empieza a llenar el pasillo.)'),
(312,22,3,1, '(La mesa está puesta. Dos platos servidos. Luces tenues. David frente a la mesa, sin decir nada, colocando algo más en una fuente.)'),
(313,22,4,1, '(Sin volverse.)—Solo… pensé que podríamos cenar tranquilos. Hice tus cosas favoritas.'),
(314,22,5,1, '(Se gira y la mira, más suave.)—Ya lo sé. Pero me apetecía.'),
(315,22,6,1, '(Unos minutos en silencio mientras comen. Nada tenso. Nada suelto. Hasta que él rompe el silencio.'),
(316,22,7,1, 'No quiero que estemos mal. Sé que a veces actúo como un imbécil. Y sé que lo del teléfono fue una cagada.'),
(317,22,8,1, 'No es por falta de confianza en ti. Es miedo. A perderte. A que un día alguien llegue y te quite de mi vida.'),
(318,22,9,1,'Yo no soy bueno hablando de estas cosas. Pero cuando te noto distante… me entra una inseguridad horrible. Y me sale mal. Me sale todo mal.'),
(319,22,10,1, 'Y solo pensar en perderte...'),
(320,22,11,1, 'Es que a veces siento que soy demasiado para ti.Que te canso. Que no sé hacerlo bien.'),
(321,22,12,1, 'Ya… pero a veces siento que todo lo que hago te molesta.'),
(322,22,13,1,'No quiero que un día te despiertes y pienses que no te compensa estar conmigo.'),
(323,22,14,1, '(Asiente, sin interrumpirla. La escucha.)'),
(324,22,15,1, 'A veces pienso que, si estuvieras con alguien más sencillo, más seguro… estarías más tranquila.'),
(325,22,16,1, 'Lo intento. Pero a veces me gana la cabeza…'),
(326,22,17,1, 'Gracias. Perdona por ser así.'),
(327,22,18,1, '(Silencio breve. Luego asiente.)—Lo sé.Estoy tratando de hacerlo distinto.'),
(328,22,19,1,'(Su voz es más suave.) —Vamos a estar bien, ¿sí?'),
(329,22,19,1, '(La cena sigue sin muchas palabras)'),
(330,22,20,null, '(Pasa la noche y amanece un nuevo día)'),
(331,23,1,1, '(Están sentados en el sofá. La televisión está encendida, pero nadie la mira. David juega con su taza vacía. Bella revisa algo en el móvil.)'),
(332,23,2,1, '¿Y qué pasó al final con lo del viaje?'),
(333,23,3,1, 'El del mensaje que te llegó esta mañana.¿Es seguro ya?'),
(334,23,4,1, '(Silencio breve. Se pasa la mano por la nuca.)¿Y tienes que ir tú?'),
(335,23,5,1, '¿Y no pueden mandar a otra persona?'),
(336,23,6,1,'¿Y con quién vas? ¿Marco también va?'),
(337,23,7,1,'(Asiente despacio. Luego deja la taza en la mesa con más fuerza de la necesaria.)—Ya.'),
(338,23,8,1,'Es que no me gusta la idea. No por ti. Lo sabes. Pero tú allí, lejos, con ese ambiente… No sé. Me deja mal cuerpo.'),
(339,23,9,1,'Dime que no te pasa nada por no ir.Que no puedes decir que estás enferma o que surgió algo.'),
(340,23,10,1,'¿Entonces qué? ¿Te da igual cómo me siento?'),
(341,23,11,1,'(La mira, en silencio. No responde de inmediato.)'),
(342,23,12,1,'(La mira, en silencio. No responde de inmediato.)'),
(343,23,13,1,'¿Ni siquiera te lo puedes pensar?Solo estoy diciendo que me incomoda, no te estoy prohibiendo nada…'),
(344,23,14,1,'(La mira. Alivia su gesto.)—No quiero obligarte, ¿eh?'),
(345,23,15,1, 'No es por hacerte sentir mal, Bella… Solo… no me gusta cómo me siento con eso. Es como si te alejaras, aunque sea por trabajo.'),
(346,23,16,1,'Pensé que  habíamos arreglado las cosas. Que estábamos en otro punto.'),
(347,23,17,1, 'Te lo agradezco, de verdad. A veces siento que no encajo en tu mundo, y eso me hace perder el control.'),
(348,23,18,1, 'Gracias por entenderlo. Lo necesitaba.'),
(349,23,19,1, 'Me hace sentir que no te importó nada de lo que te dije. Que da igual cómo me afecte.'),
(350,23,20,1, 'Qué suerte tienes de poder separar así las cosas.Yo no puedo. Yo sí siento.'),
(351,23,21,1,'(David se reclina hacia atrás, como cerrándose. Se cruza de brazos, callado.)'),
(352,23,22,null, '(Bella se queda, sentada, mirando a la nada) '),
(353,23,23,null, '¡Enhorabuena!'),
--CAP6.1
---E.1
(354,24,1,NULL, '(Bella entra en la habitación del hotel, exhausta. Deja su maleta, se quita los zapatos y se deja caer sobre la cama. Suspira.)'),
(355,24,2,NULL, '(Mira al techo por unos segundos. El móvil vibra en la mesita.)'),
(356,24,3,5,'Mensaje-David:"¿Llegaste bien?"'),
(357,24,4,null, '(Otra vibración )'),
(358,24,5,5, 'Mensaje-David: "¿Con quién estás?"'),
(359,24,6,5, 'Mensaje-David: "¿Qué tal el hotel? ¿Está lejos del centro?"'),
(360,24,7,5, 'Mensaje-David: "Avísame si sales, ¿vale?"'),
(361,24,8,null, '(Lo vuelve a dejar, esta vez boca abajo.)'),
(362,24,9,null, '(Deja el móvil en la mesilla, boca abajo. Suspira. Se levanta lentamente y abre la maleta.)'),
(363,24,10,null,'(Deja el móvil en la mesilla solo un segundo. Se incorpora para abrir la maleta, pero el móvil vibra otra vez antes de que pueda sacar siquiera una prenda.)'),
(364,24,11,5,'(Nada más enviar el último mensaje, el móvil vibra otra vez. Esta vez, una llamada entrante.)'),
(365,24,12,null, '(Toma el vestido de la maleta y se acerca al armario a colgarlo. Se mira al espejo unos segundos.)'),
(366,24,13,null, '(Mientras cierra la puerta del armario, escucha el móvil sonar. Es una llamada.)'),
(367,24,14,null, '(Lo ve iluminado sobre la mesilla: David. Suspira antes de contestar.)'),
(368,24,15,5, '¿Por qué tardaste tanto? Pensé que te habías quedado dormida.'),
(369,24,16,5, 'Es que no sabía si estabas sola. No respondías.'),
(370,24,17,5, 'Ya, perdona… es que sabes cómo me pongo. No puedo evitar preocuparme.'),
(371,24,18,5,'¿Me llamas después de cenar?'),
(372,24,19,5, 'Te quiero mucho.'),
(373,24,20,null, '(Y así se queda dormida)'),
(374,24,21,null, '(Empieza a sacar la ropa. Mientras coloca las prendas en el armario, escucha el sonido breve de una notificación. Luego otra.)'),
(375,24,22,null,'(Se detiene unos segundos, mirando la ropa en sus manos. Decide no volverse aún.)'),
(376,24,23,null,'(Va al baño, coloca el neceser sobre el lavabo, abre el grifo y se enjuaga la cara con agua fresca.)'),
(377,24,24,null,'(Al levantar la vista, ve su reflejo en el espejo: los ojos le brillan de cansancio.)'),
(378,24,25,null, '(Se acerca. Ve varias notificaciones de mensajes nuevos y una llamada perdida de David.)'),
(379,24,26,5, 'Llamada Perdida'),
(380,24,27,null, '(Se sienta en la cama, agotada. La habitación vibra suavemente con el sonido del aire acondicionado.)'),
(381,24,28,5, 'Mensaje-David:"¿Has cenado ya?"'),
(382,24,29,null, '(Mientras responde, saca una blusa y la coloca en el armario apresuradamente.El móvil vibra otra vez en la mesilla.)'),
(383,24,30,5, 'Mensaje-David:"¿Qué vas a cenar? ¿Dónde?"'),
(384,24,31,5, 'David:"Mejor. No me gusta que andes sola de noche en sitios que no conoces."'),
(385,24,32,null, '(Dobla mal una camiseta. Vuelve a mirar el móvil aunque no haya sonado.)'),
(386,24,33,null,'(Deja el móvil en la mesita, pero no puede evitar volver a mirarlo cada pocos minutos mientras termina de colocar sus cosas.)'),
(387,24,34,null, '(Se acerca a la mesilla, vuelve a mirar el móvil. Un nuevo mensaje acaba de llegar.) '),
(388,24,35,5, 'Mensaje-David:"No tardes mucho en escribirme después de cenar, ¿vale? No quiero quedarme intranquilo toda la noche."'),
(389,24,36,null, '(Deja el telefono boca abajo en la mesilla)'),
(390,24,37,5, '(Con tono suave, pero cargado de intención.)—Tardaste en contestar. Me preocupé.'),
(391,24,38,5, 'No pasa nada. Solo... me cuesta cuando no respondes. Me da vueltas la cabeza.'),
(392,24,39,5,'(Se incorpora un poco en la cama, con el teléfono pegado a la oreja. La maleta sigue cerrada a sus pies.)'),
(393,24,40,5,'¿Estás segura de que estás sola?'),
(394,24,41,5,'Ya... Es solo que... no me gusta que estés tan lejos. Me hace sentir... no sé... fuera de lugar.'),
(395,24,42,5,'(Silencio breve. Luego, con voz baja.)—¿Puedes decirme el número de habitación?'),
(396,24,43,5,'Gracias. Solo por si pasa algo, ¿vale?'),
(397,24,44,5,'(Pasa media hora en llamada. La maleta sigue cerrada. Ella está sentada en la cama, en la misma postura.)'),
(398,24,45,5,'¿Estás muy cansada?'),
(399,24,46,5,'¿Y no prefieres quedarte conmigo en llamada un rato más? Me gusta escucharte'),
(400,24,47,5,'(Sonríe débilmente. Mira de reojo la maleta, aún cerrada. Piensa en el tiempo que le queda para instalarse, en los correos que no ha revisado.)'),
(401,24,48,5,'(Pero no se mueve. Se queda con el teléfono en la oreja, hablando)'),
---E.2
(402,24,49,null, '(Al día siguiente por la mañana...)'),
(403,24,50,null, '(El despertador suena temprano. Bella abre los ojos con dificultad.)'),
(404,24,51,null, '(Siente el peso del cansancio acumulado en el cuerpo. Se levanta, se arregla rápido y baja al hall del hotel para reunirse con su equipo.)'),
(405,25,1,8, '(Sonriendo, con café en la mano.)—Buenos días, Bella.'),
(406,25,2,7, 'Vamos primero a la sala de conferencias del hotel. La reunión con el cliente es allí.'),
(407,26,3,null,'(Mientras se sientan en la sala de conferencias y hablan de detalles logísticos, el móvil de Bella, guardado en su bolso, empieza a vibrar discretamente.)'),
(408,26,4,8, 'Bueno , pues empecemos la reunión...'),
(409,26,5,null, '(A lo largo de la reunón llega una vibración. Luego otra. Y otra.)'),
(410,26,6,null, '(Intenta mantener la atención en la conversación. Uno de sus compañeros comenta sobre la agenda del día: temas técnicos, presentaciones, visitas de supervisión.)'),
(411,26,7,null, '(Intenta mantener la atención en la conversación. Uno de sus compañeros comenta sobre la agenda del día: temas técnicos, presentaciones, visitas de supervisión.)'),
(412,26,8,null, '(Una nueva vibración corta interrumpe su concentración. El bolso, colocado junto a su silla, vibra discretamente sobre la moqueta.)'),
(413,26,9,null,'(Baja ligeramente la mirada hacia el bolso, pero no lo abre. Inspira despacio por la nariz.)'),
(414,26,10,null,'(La reunión avanza. Bella siente la vibración sorda del móvil en su bolso, pero esta vez no lo mira.)'),
(415,26,11,null,'(La vibración del móvil es persistente, como un zumbido dentro del bolso.)'),
(416,26,12,null,'(Sin pensarlo demasiado, Bella mete la mano, lo saca y lo mira por debajo de la mesa.)'),
(417,26,13,null,'(La reunión sigue celebrandose)'),
(418,26,14,null,'(El móvil vibra de nuevo.)'),
(419,26,15,null,'(Asiente cuando alguien señala algo en la pantalla. Hace una pregunta corta. Se mantiene en la conversación.)'),
(420,26,16,null,'(Al cabo de un rato ,la reunión finalmente termina. El murmullo de las sillas moviéndose y de papeles recogidos llena la sala.)'),
(421,26,17,null,'(Nada más cruzar la puerta, saca el móvil del bolso. La pantalla muestra varias notificaciones de David.)'),
(422,26,18,5,'David:"Buenos dias"  "¿Qué tal has dormido?"   "¿Dónde estás?"   "No has dicho nada."   "¿Todo bien?"  "¿Por qué no contestas?"'),
(423,26,19,5,'  "Contestame"'),
(424,26,20,null,'(Envía el mensaje. Suspira. Guarda el móvil de nuevo en el bolso, pero la sensación de incomodidad no se va.)'),
(425,26,21,null,'(Se apoya brevemente contra la pared, cierra los ojos un segundo antes de volver con su grupo.)'),
(426,26,22,null,'(Se obliga a levantar la vista hacia la pantalla de la presentación.)'),
(427,26,23,null,'(Aunque la vibración ha cesado, una parte de su mente sigue pensando en los mensajes que estarán acumulándose.)'),
(428,26,24,8,'¿Bella tu tenías los informes no ?'),
(429,26,25,null,'(Participa en la reunión con naturalidad.)'),
(430,26,25,null,'(La reunión termina. El sonido de las sillas arrastrándose llena la sala mientras todos comienzan a levantarse.)'),
(431,26,25,null,'(Sale de la sala junto a sus compañeros, sonriendo brevemente a un par de ellos cuando le comentan algo sobre el cliente.)'),
(432,26,25,null,'(Desbloquea la pantalla y, con un gesto casi mecánico, desactiva el modo "No molestar".)'),
(433,26,25,5,'David:"Buenos dias"  "¿Qué tal has dormido?"   "¿Dónde estás?"   "No has dicho nada."   "¿Todo bien?"  "¿Por qué no contestas?"'),
(434,26,25,5,'"Contestame'),
(435,26,25,null,'(Envía el mensaje. Se guarda el móvil de nuevo en el bolso. Se une a su grupo que ya camina hacia el restaurante del hotel para el almuerzo.)'),
(436,26,25,5,'David:"Buenos dias"  "¿Qué tal has dormido?"   "¿Dónde estás?"   "No has dicho nada."   "¿Todo bien?"  "¿Por qué no contestas?"'),
(437,26,25,null,'(No contesta. Vuelve a guardar el móvil rápidamente, pero su atención ya no está en la reunión.)'),
(438,26,25,null,'(Mira la pantalla de la presentación sin verla realmente. Asiente cuando uno de ellos comenta algo, aunque no ha terminado de entenderlo.) '),
(439,26,25,null,'(La sensación de culpa le late en la cabeza: “Debería contestarle…”, “Quizás piensa que estoy ignorándolo…”)'),
(440,26,25,null,'(La reunión termina. Alguien dice algo, se escucha un “perfecto, pues eso sería todo por hoy” y el sonido de carpetas cerrándose llena la sala.)'),
(441,26,25,null,'(Se incorpora lentamente, siguiendo el movimiento del grupo. Finge normalidad, asiente con una sonrisa breve cuando uno de sus compañeros le comenta algo.)'),
(442,26,25,null,'(Mientras todos se dirigen hacia la salida, Bella saca el móvil. Hay más notificaciones.)'),
(443,26,25,5,'David: "Sigues sin decirme nada.""Solo quiero saber si estás bien.""Empiezo a pensar que me estás evitando."'),
(444,26,25,5,'David:"Solo me ha extrañado que no puedas sacar ni un minuto para mí."'),
(445,26,25,null,'(Desde la puerta de la cafetería, uno de sus compañeros la llama con un gesto.)'),
(446,26,25,8, '¿Vienes?'),
(447,26,25,null, '(Guarda el móvil en el bolso.)'),
(448,26,25,null, 'David:"Buenos dias"  "¿Qué tal has dormido?"   "¿Dónde estás?"   "No has dicho nada."   "¿Todo bien?"  "¿Por qué no contestas?"'),
(449,26,25,8, '¿Y tú qué opinas sobre lo de ajustar la entrega al viernes en lugar del lunes?'),
(450,26,25,8, '(Espera su respuesta)'),
(451,26,25,null, '(Él asiente)'),
(452,26,25,null, '(La mira, fijamente)'),
(453,26,25,null, '(El compañero asiente, aunque con una ceja ligeramente levantada.)'),
(454,26,25,null, '(La reunión termina. El sonido de papeles recogiéndose, sillas arrastradas y un par de bromas sueltas llenan la sala.)'),
(455,26,25,null, '(Sale casi la última. En el pasillo, saca el móvil del bolso. La pantalla está llena de notificaciones suyas. Mensajes.)'),
(456,26,25,5, 'David:"¿Por fin puedes hablar?"'),
(457,26,25,5, 'David:—"Te escribí un montón. No sabía si habías salido ya, si estabas bien… nada."'),
(458,26,25,5, '(Silencio)'),
(459,26,25,5, 'David:-¿Y ahora qué haces?"'),
(460,26,25,5, 'David: "A partir de ahora quiero que estes más pendiente al movil, ¿vale?"'),
(461,26,25,null, '(Se queda unos segundos en silencio, mirando la pantalla negra. Luego guarda el móvil y vuelve a caminar hacia el grupo'),
(462,26,25,null, '(Solo quiero que el día pase rápido.)'),
---E3
(463,26,25,null, '(El día pasa , entre reuniones y conversaciones)'),
(464,27,1,null, '(Ya es de noche. Al llegar, abre la puerta con la tarjeta y entra. Cierra detrás de sí con un suspiro.)'),
(465,27,2,null, '(Deja la tarjeta en la mesa, la chaqueta en la silla y se quita los zapatos de inmediato.)'),
(466,27,3,null, '(Apenas se pone en pie para ir al baño, el teléfono vibra. Una vez. Luego otra.)'),
(467,27,4,5, 'David:"¿Qué planes tienes esta noche? ¿Estás sola en la habitación?"'),
(468,27,5,5, '¿Bella?'),
(469,27,6,null, '(Envía. Deja el móvil sobre la cama, sin soltarlo del todo.)'),
(470,27,7,null, '(Envía el mensaje. Baja el volumen del teléfono, lo pone en modo silencio y lo deja en la mesita, boca abajo.)'),
(471,27,8,null, '(Mira la pantalla. No hay respuesta. Refresca la conversación. Nada.)'),
(472,27,9,5, 'David: "¿Con quién hablaste más? ¿Eva estaba?"'),
(473,27,10,null, '(A los pocos segundos, vibra de nuevo.)'),
(474,27,11,5, 'David:"¿Estás sola?"'),
(475,27,12,5, 'David: "No te cuesta nada llamarme un momento."'),
(476,27,13,5, 'Bella'),
(477,27,14,null, '(Deja el móvil boca abajo en la mesita. Se levanta, va al baño y se lava el rostro. Cuando regresa, el móvil ha vibrado de nuevo, pero no lo mira.)'),
(478,27,15,null, '(Se pone el pijama, apaga la luz principal y se mete en la cama. Cierra los ojos con la mente agitada, pero el cuerpo agotado.)'),
(479,27,16,null, '(Se cambia de ropa, se recoge el pelo con una goma. Se mira en el espejo un momento: ojos cansados)'),
(480,27,17,null, '(Luego enciende la tetera eléctrica, prepara una infusión y se sienta junto a la ventana.)'),
(481,27,18,null, '(La ciudad murmura bajo sus pies: luces lejanas, coches, voces aisladas.)'),
(482,27,19,null, '(Por primera vez, no siente culpa por no responder más.)'),
(483,27,20,null, '(Lo deja a un lado. Lo vuelve a mirar a los pocos segundos.) '),
(484,27,21,null, '(Cuando finalmente suena la notificación)'),
(485,27,22,5, 'David:"Pensé que me escribirías cuando terminaras."'),
(486,27,23,5, 'David: "Ha ido Eva, ¿no? Esa siempre te lía."'),
(487,27,24,5, 'David: "Ya… bueno. Intenta descansar. Espero que no haya sido una cena de esas con copas de más y gente hablando tonterías."'),
(488,27,25,null, '(Envía el mensaje y deja el móvil en la mesita. Apaga la luz principal y se recuesta)'),
(489,27,26,5,'David:"¿Marco otra vez? Qué casualidad, ¿no? Últimamente siempre está cerca."' ),
(490,27,27,5,'(La conversación sigue. David no grita, pero cuestiona, insiste, compara.)' ),
(491,27,28,5,'(Es más de media noche)' ),
(492,27,29,5,'David:"Solo digo que te fijes en los detalles. Hay cosas que tú no ves, Bella."' ),
(493,27,30,5, 'Vale... si tú lo dices. Mañana háblame temprano, ¿sí? Aunque sea un audio. Me ayuda escucharte.'),
(494,27,31,null,'(Cierra la app, pero no deja el móvil lejos. Lo mantiene en la mano un rato más. La pantalla se apaga, pero ella sigue despierta, mirando al techo.)' ),
(495,27,32,null, '(Solo queda un día más.Mañana por la tarde vuelvo a casa.Y ya está.)'),
(496,27,33,null, '¡Enhorabuena!'),
--CAP6.2
(497,28,1,null,'(Bella entra al vestíbulo del hotel arrastrando la maleta. Hay algo de bullicio. Se acerca al mostrador para hacer el check-in.)'),
(498,28,2,null, '(Justo entonces, el móvil vibra. Llamada: David.)'),
(499,28,3,5, 'Ey… ¿ya llegaste? ¿Todo bien?'),
(500,28,4,5,'—¿Y qué tal el hotel? ¿Seguro? ¿Te dieron una habitación sola?'),
(501,28,5,5,' —¿Y ya viste a alguien del equipo?'),
(502,28,6,5,' —Bueno… ya sabes. Cuídate. Y no desaparezcas por andar todo el día con ellos.'),
(503,28,5,5,'(En ese momento, el recepcionista la llama con un gesto de cabeza.)'),
(504,28,5,5,'¿Bella?'),
(505,28,5,5,'¿Tan ocupada estás que no puedes contarme al menos si está todo bien?'),
(506,28,5,5,'Vale… solo, no cuelgues aún. Quédate conmigo mientras haces todo eso.'),
(507,28,5,5,'¿Bella?'),
(508,28,5,5,'(Pausa.)—Espera ¿Y el hotel qué tal? ¿Te parece bien? ¿No es de esos que te ponen en medio de la nada?'),
(509,28,5,5,'(Pone el modo viodellamada)'),
(510,28,5,5,'(Espera)'),
(511,28,5,5,'—Bueno… solo quiero saber que estás cómoda. Ya sabes cómo son esos sitios...'),
(512,28,5,5,'(Silencio)'),
(513,28,5,5,'—Vale… tú sabrás.'),
(514,28,5,5,'(Cuelga sin respuesta)'),
(515,28,5,5,'—Ya... solo que me suena raro que no puedas hablar ni un minuto.'),
(516,28,5,5,'(Tono más bajo, pero con una ligera carga.)—Vale, vale. No te molesto más entonces.'),
(517,28,5,5,'(Se queda en silencio unos segundos.)—Vale. Espero entonces.'),
(518,28,5,null,'(Cuelga. Suspira. Se guarda el móvil en el bolso sin pensarlo demasiado.) '),
(519,28,5,null,'(Camina hacia el mostrador mientras nota esa tensión pequeña que siempre queda)'),
(520,28,5,null,'(Tras hablar con la recepcionista que le da la tarjeta de la habietación , sube a la misma)'),
(521,28,5,5,'David:—Sí, solo quiero estar contigo un rato. Si total, vas a estar sola ahí arriba. Me gusta escucharte.'),
(522,28,5,9,'(Con el móvil aún en la oreja, se acerca al mostrador. El recepcionista le sonríe.) '),
(523,28,5,9,'Buenas tardes. ¿Tiene reserva?'),
(524,28,5,5,'(David permanece en línea. No habla, pero se escucha su respiración. Ella lo nota.)'),
(525,28,5,5,'¿Todo bien? Dile que quieres una individual'),
(526,28,5,9,'(Recibe la tarjeta de la habitación, agradece al recepcionista y recoge la maleta con una sola mano mientras equilibra el móvil con la otra.) '),
(527,28,5,5,'(Esperando)'),
(528,28,5,5,'David:—Vale… Oye, por cierto… me tengo que ir ahora un momento, ¿vale?'),
(529,28,5,5,'David:—Era solo para saber que estabas bien. Luego hablamos. Escríbeme cuando termines todo.'),
(530,28,5,5, 'Venga, hablamos luego. Un beso.'),
(531,28,5,null, '(Me pidió que no colgara aunque yo tuviera cosas que hacer… y ahora que él tiene algo, cuelga sin más.)'),
(532,28,5,5, 'No cuelgues, quédate conmigo mientras haces todo. Solo quiero asegurarme de que todo esté bien.'),
(533,28,5,5, '¿Estás segura de que ese hotel está bien? Es que… ya sabes, a veces por las fotos no parece lo mismo.'),
(534,28,5,5, '(Pone el movil en videollamada y vuelve el móvil para enseñarle parte del vestíbulo sin que él lo pida.)'),
(535,28,5,5, '(Observando)'),
(536,28,5,5, '(Con el móvil entre el hombro y la oreja,  se acerca al mostrador. El recepcionista la recibe con una sonrisa educada.) '),
(537,28,5,9, 'Buenas tardes. ¿Nombre, por favor?'),
(538,28,5,5, '(Se escucha su voz baja por el teléfono.)—¿Y ya te confirman la habitación?'),
(539,28,5,9, '(El recepcionista teclea. Bella entrega su DNI, mientras David sigue en silencio, escuchando.)'),
(540,28,5,9, 'Aquí está. Habitación 308, tercer piso. El ascensor está a la izquierda.'),
(541,28,5,5, '¿Sola, no?'),
(542,28,5,5, 'Perfecto. Entonces ahora cuando llegues arriba me grabas un video yme enseñas todo con calma. Que tengo que irme'),
(543,28,5,null, '(Me pidió que no colgara aunque yo tuviera cosas que hacer… y ahora que él tiene algo, cuelga sin más.)'),
(544,29,5,null, '(Entra finalmente a la habitación. Cierra la puerta con cuidado y deja la maleta a un lado. Todo está en silencio)'),
(545,29,5,null, '(Deja el bolso sobre el escritorio. El móvil, aún encendido, vibra una última vez con una notificación más.)'),
(546,29,5,null, ' (Ojalá pudiera estar completamente sola al menos un rato.)'),
---E.2
(547,29,1,null, '(La luz del día entra por la rendija de la cortina.) '),
(548,29,2,null, ' (Cierra el portátil. Se pone los zapatos y baja a reunirse con su equipo.)'),
(549,30,1,null, '(Después de varias horas de trabajo, charlas técnicas, por fin hay un rato libre. Se han ido a tomar un café)'),
(550,30,2,null, '(Piden dos cafés en la barra y se sientan en una mesa cercana a la ventana.)'),
(551,30,2,7, '(Sacando su móvil para revisar algo.)—¿Cómo vas tú con el proyecto? ¿Te han cargado mucho esta vez?'),
(552,30,2,5, '(Mientras están hablando su móvil vibra sobre la mesa. Es una videollamada entrante. Nombre en pantalla: David.)'),
(553,30,2,7, '(Eva levanta la mirada, pero no dice nada.)'),
(554,30,2,5, '(Poniendo el dedo sobre aceptar, contesta. David aparece en pantalla.) '),
(555,30,2,5, 'Hola'),
(556,30,2,5, '¿Dónde estás? ¿Puedes girar la cámara un poco?'),
(557,30,2,5, '(Gira la cámara apenas unos segundos, mostrando brevemente las mesas y la barra. No enfoca a Eva directamente.) '),
(558,30,2,5, '(No gira la cámara. Se queda encuadrada solo ella, sin mostrar el entorno.) '),
(559,30,2,5, ' ¿Dónde es eso? ¿Hay mucha gente?'),
(560,30,2,5, '(Se aleja de la mesa con el móvil en la mano. Se coloca cerca de una pared, donde hay menos ruido.)'),
(561,30,2,5, 'Vale… Es que no me has dicho nada'),
(562,30,2,5, '(Se queda en silencio)'),
(563,30,2,5, 'Vale, solo quería saber dónde estabas.'),
(564,30,2,5, '(Pausa breve.) —Pero yo quería hablar un rato contigo...'),
(565,30,2,5, '(Cuelga, sin dar tiempo a que él añada nada más.)'),
(566,30,2,5, 'Suspira por lo bajo mientras bloquea la pantalla'),
(567,30,2,5, '(Coloca el móvil boca abajo sobre la mesa) '),
(568,30,2,7, '(La observa con curiosidad, pero sin juicio.) —¿Todo bien?'),
(569,30,2,5, '¿Con quién estás? ¿Eva?'),
(570,30,2,5, '(Se queda en silencio)'),
(571,30,2,5, '(Pausa breve.) —Pero yo quería hablar un rato contigo...'),
(572,30,2,5, '(Parece no del todo conforme.)—Bueno… vale.'),
(573,30,2,null, '(Cuelga sin darle lugar a seguir. Suspira apenas y deja el teléfono dentro del bolso, con determinación.)'),
(574,30,2,7, '¿Todo bien?'),
(575,30,2,5, '(Observando)'),
(576,30,2,5, '(Evita enfocar directamente a Eva, pero la menciona igual.)'),
(577,30,2,5, '(Asiente, mirando la pantalla.) —Ajá… ¿y solo estáis vosotras?'),
(578,30,2,5, '(Sonríe apenas, con tono ambiguo.)—Ajá. Bueno, mientras estes bien… me quedo más tranquilo.'),
(579,30,2,5, '(Pausa. Mira algo fuera de pantalla.) —Vale, bueno… tengo que hacer una cosa ahora. Solo queria saber donde estabas'),
(580,30,2,5, '(Cuelga antes de que pueda decir nada más.)'),
(581,30,2,7, '¿Todo bien?'),
(582,30,2,5, '(Mirandola)'),
(583,30,2,5, '¿Estáis solas? ¿Hay más gente del grupo?'),
(584,30,2,5, 'Bueno, vale… solo quería saber eso. Luego me cuentas, ¿vale?'),
(585,30,2,5, 'No hace falta. Estoy con algo ahora. Luego vemos. (Cuelga sin más)'),
(586,30,2,null, '(Regresa a la mesa.) '),
(587,30,2,7, '(Eva la mira)'),
(588,30,2,7, 'Si en algún momento quieres hablar de algo… aquí estoy, ¿vale?'),
(589,30,2,7, '(Eva se queda en silencio)'),
(590,30,2,7, '(Asiente lentamente. Acepta el cambio de tema sin insistir.) —Sí, pero solo lo han enviado a algunos. Luego te lo reenvío.'),
---E.3
(591,31,1,null, '(Después de terminar el café con Eva, Bella vuelve a su habitación con rapidez.)'),
(592,31,1,null, '( Tiene solo unos minutos para revisar correos antes de la siguiente reunión. )'),
(593,31,1,null, '(Se aplica un poco de corrector bajo los ojos y baja con su grupo al salón de conferencias del hotel.)'),
(594,31,1,null, '(Las horas siguientes se llenan de informes, presentaciones y conversaciones técnicas. )'),
(595,31,1,null, '(Bella intenta concentrarse, pero la fatiga empieza a pasar factura. Mira la hora con disimulo: por fin termina la última sesión del día.)'),
(596,32,1, null, '(Ya es de noche cuando sube de nuevo a su habitación. Se despide con una sonrisa del equipo en el ascensor, entra a su cuarto, se quita los zapatos y deja el bolso en la silla. '),
(597,32,1,null, '(Apenas enciende la luz… el móvil vibra.) '),
(598,32,1,5,'Videollamada entrante: David. '),
(599,32,1,5,'¿Ya te cambiaste?¿Estás sola?¿Qué vas a hacer ahora?'),
(600,32,1,5,'¿Mañana? ¿Te cuesta tanto hablar conmigo unos minutos? Solo quiero saber cómo estás…'),
(601,32,1,5,'(Frunce el ceño ligeramente.)—¿Tan mal te ha dejado el día como para no querer hablar conmigo ni cinco minutos?'),
(602,32,1,5,'¿Apagada? Parece que te aburro'),
(603,32,1,5,'¿Ya te cambiaste? ¿Te vas a dormir?'),
(604,32,1,5,'Pensé que me ibas a llamar tú. '),
(605,32,1,5,'(Se queda en silencio)'),
(606,32,1,5,'Bueno… si necesitas espacio incluso para una llamada, ya me dirás.'),
(607,32,1,5,'Está bien. Buenas noches, entonces.'),
(608,32,1,null,'(Cuelga. Deja el móvil sobre la mesilla en silencio. Se cambia de ropa sin apuro, se mete en la cama.) '),
(609,32,1,null,'(Mira el techo un momento.) '),
(610,32,1,5,'¿Ni cinco minutos puedes hablar conmigo?'),
(611,32,1,5,'Vale. Descansa.'),
(612,32,1,null,'(Cuelga. Deja el móvil en la mesilla, en modo no molestar. Se queda sentada unos segundos en silencio.)'),
(613,32,1,5,'Bueno, solo quería saber que todo estaba bien. A veces siento que te pierdes allí y no piensas en mí.'),
(614,32,1,5,'(Silencio incómodo. No sabe bien qué más decir. Mira el móvil. Él también se queda callado unos segundos.)'),
(615,32,1,5,'Está bien. Descansa.'),
(616,32,1,null,'(David cuelga.)'),
(617,32,1,5,'(Levanta la camiseta de pijama que tiene doblada sobre la cama.)'),
(618,32,1,5,'¿Y comiste con todos? ¿O estuviste sola?'),
(619,32,1,5,'Ajá…'),
(620,32,1,5,'Ya, ya. Está bien…'),
(621,32,1,5,'Te creo.'),
(622,32,1,5,'Buenas noches.'),
(623,32,1,5,'Ajá. ¿Con Eva, eh?'),
(624,32,1,5,'(Mira hacia otro lado.) —¿Y ahora qué vas a hacer?'),
(625,32,1,5,'(Se queda en silencio)'),
(626,32,1,5,'Ya.'),
(627,32,1,5,'Está bien. No pasa nada, Bella.'),
(628,32,1,5,'Descansa. Hablamos mañana. '),
(629,32,1,null,'(Cuelga antes de que ella diga algo más.)'),
(630,32,1,null,'(Solo quedan unas horas… y ya estaré de vuelta. Con él.)'),
(631,32,1,null,'(Cierra los ojos, como quien apaga una lámpara sabiendo que no habrá descanso real. Pero lo intenta. Porque no queda otra.)'),
(632,32,1,null, '¡Enhorabuena!'),
--CAP6.3
(633,33,1,NULL, '(Bella entra al vestíbulo del hotel arrastrando la maleta. Hay algo de bullicio. Se acerca al mostrador para hacer el check-in.)'),
(634,33,1,5, '(Se coloca en la fila del check-in y saca el móvil de su bolso. Una videollamada entrante: David.)'),
(635,33,1,5, 'Ey… por fin. ¿Todo bien? ¿Dónde estás ahora?'),
(636,33,1,5, '(Mira a través de la cámara.) —¿Y qué tal? ¿Se ve seguro? ¿Estás sola?'),
(637,33,1,5, '¿Qué tipo de hotel es? ¿No te mandaron a uno de esos de carretera, verdad?'),
(638,33,1,5, '(Observa la imagen unos segundos. Frunce el ceño apenas.)—Vale... parece normal. '),
(639,33,1,5, '¿Tan ocupada estás que no puedes contarme al menos si está todo bien?'),
(640,33,1,5, 'Vale… solo, no cuelgues aún. Quédate conmigo mientras haces el check-in.'),
(641,33,1,5, ' (Le hace una señal al recepcionista con una sonrisa forzada.) '),

(642,33,1,5, 'Bueno… solo quiero saber que estás cómoda. Ya sabes cómo son esos sitios...'),
(643,33,1,5, '(Guarda silencio)'),
(644,33,1,5, '(Guarda silencio)'),
(645,33,1,5, 'Vale... llámame luego, entonces.'),
(646,33,1,null, '(Cuelga antes de que él diga algo más. Suspira. Se pasa una mano por el cuello. Luego avanza hacia el mostrador.)'),
(647,33,1,null, '(Mientras espera a que le asignen la habitación, mete el móvil al bolso, cerrándolo con gesto firme)'),

(648,33,1,5, 'Ya... solo que me suena raro que no puedas hablar ni un minuto.'),
(649,33,1,5, '(Tono más bajo, pero con una ligera carga.)—Vale, vale. No te molesto más entonces.'),
(650,33,1,5, '(Se queda en silencio unos segundos.)—Vale. Espero entonces.'),
(651,33,1,null, '(Cuelga. Suspira. Se guarda el móvil en el bolso sin pensarlo demasiado.) '),
(652,33,1,null, '(Camina hacia el mostrador mientras nota esa tensión pequeña que siempre queda)'),
(653,33,1,null, '(Tras hablar con la recepcionista que le da la tarjeta de la habietación , sube a la misma)'),

(654,33,1,5, 'Sí, solo quiero estar contigo un rato. Si total, vas a estar sola ahí arriba. Me gusta escucharte.'),
(655,33,1,5, '(Con el móvil aún en la oreja, se acerca al mostrador.La recepcionista le sonríe.) '),
(656,33,1,9, 'Buenas tardes. ¿Tiene reserva?'),
(657,33,1,5, '(David permanece en línea. No habla, pero se escucha su respiración. Ella lo nota.)'),
(658,33,1,5, '¿Todo bien? Dile que quieres una individual'),
(659,33,1,9, '(Recibe la tarjeta de la habitación, agradece al recepcionista y recoge la maleta con una sola mano mientras equilibra el móvil con la otra.)'),
(660,33,1,5, '(Espera en silencio)'),
(661,33,1,5, 'Vale… Oye, por cierto… me tengo que ir ahora un momento, ¿vale?'),
(662,33,1,5, 'Era solo para saber que estabas bien. Luego hablamos. Escríbeme cuando termines todo.'),
(663,33,1,5, 'Venga, hablamos luego. Un beso.'),
(664,33,1,null,'(Me pidió que no colgara aunque yo tuviera cosas que hacer… y ahora que él tiene algo, cuelga sin más.)'),

(665,33,1,5,'No cuelgues, quédate conmigo mientras haces todo. Solo quiero asegurarme de que todo esté bien.'),
(666,33,1,5,'(Con el móvil entre el hombro y la oreja,  se acerca al mostrador. La recepcionista la recibe con una sonrisa educada.)'),
(667,33,1,9,'Buenas tardes. ¿Nombre, por favor?'),
(668,33,1,5,'(Se escucha su voz baja por el teléfono.)—¿Y ya te confirman la habitación?'),
(669,33,1,9,'(La recepcionista teclea. Bella entrega su DNI, mientras David sigue en silencio, escuchando.)'),
(670,33,1,9,'Aquí está. Habitación 308, tercer piso. El ascensor está a la izquierda.'),
(671,33,1,5,'¿Sola, no?'),
(672,33,1,5,'Perfecto. Entonces ahora cuando llegues arriba me grabas un video y me enseñas todo con calma. Que tengo que irme'),

(673,34,1,null,'(Entra finalmente a la habitación. Cierra la puerta con cuidado y deja la maleta a un lado. Todo está en silencio)'),
(674,34,1,null,'(Deja el bolso sobre el escritorio. El móvil, aún encendido, vibra una última vez con una notificación más.)'),
(675,34,1,null,'(Ojalá pudiera estar completamente sola al menos un rato.)'),
---E.2
(676,35,1,null, '(El día pasa) '),
(677,35,1,null,'( Regresan al hotel tras una larga jornada con el equipo. Bajan del coche frente al edificio.)'),
(678,35,1,null,'(Solo quiero subir, darme una ducha y desconectar.) '),
(679,35,1,null,'(Al levantar la vista hacia la puerta del hotel, se detiene en seco.)'),
(680,35,1,1,'(Justo delante, con una pequeña maleta a su lado, está David. Sonríe.)' ),
(681,35,1,1,'Sorpresa.'),
(682,35,1,1,'Te dije que te echaba de menos. Quería darte una sorpresa. Estaba libre estos días, y pensé… ¿por qué no? Así pasamos algo de tiempo juntos.'),
(683,35,1,1,'(La mira con una sonrisa)'),
(684,35,1,1,'(David se encoge de hombros, intentando restarle importancia, y avanza hacia ella con intención de abrazarla.)'),
(685,35,1,1,'(Se queda en silencio)'),
(686,35,1,1,'Te dije que te echaba de menos. Y no podía más. Necesitaba verte.'),
(687,35,1,1,'Te dije que te echaba de menos. No podía más sin verte.'),
(688,35,1,1,'No sabes lo que significa para mí estar aquí. Me sentía tan mal estos días. Necesitaba esto.'),
(689,35,1,1,'Pero he venido , solo para estar contigo...'),
(690,35,1,1,'Bueno , pues perdona , solo queria pasar timepo con mi novia'),
(691,35,1,1,'Si te parece mal, me voy, no pasa nada...'),
(692,35,1,1,'Claro. Lo que tú quieras.'),
(693,35,1,1,'Solo quería hacer algo bonito por nosotros. Me pareció una buena idea… Pero bueno, ya veo que no te hace ilusión.'),
(694,35,1,1,'(Silencio breve. La mira fijamente.)—¿Presión? ¿Yo te estoy presionando por aparecer aquí sin avisar?'),
(695,35,1,1,'Vale… pues nada. Haré lo que tú digas.'),
(696,35,1,1,'(Él recoge su maleta sin decir más, y entran juntos al vestíbulo en silencio.)'),
(697,35,1,1,'¿No te hace ilusión? No pasa nada si no te alegra. A lo mejor yo tenía más ganas que tú.'),
(698,35,1,1,'(La mira)'),
(699,35,1,1,'Entonces vamos a descansar juntos. Ya está, no tienes que decir nada. Estoy aquí ahora.'),
(700,35,1,1,'Vamos a tomar algo, ¿sí?'),
(701,35,1,null,'(Siente cómo la mirada de algunos compañeros se desvía hacia ellos.)'),
(702,35,1,null,'(Si ha venido, es porque necesitaba verme. No puedo echarle en cara que haya venido hasta aquí por mí.)'),
(703,35,1,1,'Pensé que te alegrarías más. Pero bueno… quizás estabas muy ocupada.'),
(704,35,1,1,'Bueno, ya estoy aquí. . Así podemos vernos sin depender del teléfono.'),
(705,35,1,1,'¿Vamos a tomar algo? Como tú prefieras.'),
(706,35,1,1,'(Los dos entran al hotel. David lleva su maleta, caminando cerca de ella.)'),
(707,35,1,1,'¿Tienes planes esta tarde? ¿O puedo quedarme contigo?'),
(708,35,1,1,'Perfecto. Te voy a cuidar. Prometido.'),
(709,35,1,1,'(Asiente otra vez, sin decir palabra. Camina junto a él, con una leve rigidez en los hombros.)'),
(710,35,1,1,'(Ha venido sin avisar. Tenía reuniones, correos por responder, pendientes de la jornada…)'),
---E.3
(711,36,1,NULL,'(Después de pasar el día acompañando a David entre cafés, paseos  y momentos en los que apenas pudo revisar sus correos)'),
(712,36,1,NULL,'Tiene el horario ajustado. Tiene varias reuniones y actividades laborales.)'),
(713,36,1,null, '(Después de una de ellas, el equipo baja a desayunar en el restaurante del hotel.) '),
(714,36,1,null, '(Ella se sienta con Eva y dos compañeros más. Ríen brevemente mientras hablan del cliente y revisan unas notas en la tablet.)'),
(715,36,1,null,' (Cuando de pronto entra.)'),
(716,36,1,1,'(David aparece en el comedor del hotel. La ve y camina directamente hacia ella)'),
(717,36,1,1,'¡Buenos días! ¿Me haces un sitio?'),
(718,36,1,1,'(Su compañero de la izquierda se mueve un poco, incómodo. David se sienta.)'),
(719,36,1,1,'Tenía ganas de compartir el desayuno contigo… y ver con quién trabajas.'),
(720,36,1,1,'(Sus ojos recorren la mesa. Mira de reojo al compañero que estaba hablando con Bella minutos antes.)'),
(721,36,1,1,'(Salen juntos del salón, cruzando el vestíbulo hasta un rincón más privado del hotel.)'),
(722,36,1,1,'(Bella se pone de pie, con calma, y le indica a David que la acompañe. Caminan hasta un pasillo lateral del restaurante, lejos del grupo.)'),
(723,36,1,1,'(David mira a todos)'),
(724,36,1,1,'(Se levanta de la silla antes de que David responda. Mira a sus compañeros, con una sonrisa rápida.)'),
(725,36,1,1,'(David asiente sin decir nada y la sigue.)'),
(726,36,1,1,'Solo quería pasar un rato contigo, ¿eso está mal también? Estás todo el tiempo ocupada, Bella.'),
(727,36,1,1,'Vale... Lo entiendo. No volverá a pasar, tranquila. Aunque… no estaría mal que me incluyeras un poco más. Me haces sentir fuera.'),
(728,36,1,1,'Está bien. Solo recuerda que yo estoy aquí, haciendo un esfuerzo por estar cerca. Para ti.'),
(729,36,1,1,'Tranquila, no te molesto más.'),
(730,36,1,1,'Lo que tu digas'),
(731,36,1,1,'(David se acomoda junto a ella. Mientras los demás reanudan la conversación)'),
(732,36,1,1,'(David asiente, pero su mirada no está en la conversación, sino en con quién Bella habla, a quién sonríe, cuánto tiempo tarda en responder.)'),
(733,36,1,1,'(Pasan los minutos. El ambiente se vuelve más frío. Los compañeros comienzan a hablar entre ellos en voz baja.)'),
(734,36,1,1,'(Tendría que haber dicho algo. Pero ya está aquí… no quiero que se moleste.)'),
(735,36,1,8,'Bueno, nosotros vamos recogiendo. Nos vemos más tarde, Bella.'),
(736,36,1,1,'¿Ves? Al final no fue para tanto. Solo quería estar un rato contigo.'),
(737,36,1,1,'(Mira a todos)'),
(738,36,1,8,'(Con cierta sorpresa, pero sin decir mucho.)-Vale… sí, luego hablamos.'),
(739,36,1,1,'(David se levanta también. No agradece ni se despide del grupo.)'),
(740,36,1,1,'(Caminan por el vestíbulo del hotel en silencio)'),
(741,36,1,1,'(Susurrando, casi satisfecho.)—Gracias por entenderme.'),
(742,36,1,1,'(Salen del comedor juntos. Al cruzar el vestíbulo, David le toma la mano y se la aprieta con fuerza.)'),
(743,36,1,1,'Gracias. No quería arruinarte nada, solo quería estar contigo.'),
(744,36,1,1,'(Quizá no era el momento, pero… ¿y si lo necesitaba? Tal vez hice bien.)'),
(745,36,1,NULL,'¡Enhorabuena!'),
--CAP6.4
(746,37,1,NULL,'(La habitación está en silencio.)'),
(747,37,1,NULL,'(La maleta abierta aún no está del todo llena.)'),
(748,37,1,1,'(David está en el umbral de la puerta, apoyado con los brazos cruzados.)'),
(749,37,1,1,'(La observa sin hablar durante varios segundos.)'),
(750,37,1,1,'No sé. Me siento raro. Llevo todo el día así.'),
(751,37,1,1,'No lo sé… es como si algo me dijera que no deberías ir. No quiero sonar paranoico. Solo… siento que no es buena idea.'),
(752,37,1,1,'No te estoy diciendo que no vayas, ¿eh? Solo… me siento mal. Muy mal.'),
(753,37,1,1,'(La mira)'),
(754,37,1,1,'(Se queda en silencio )'),
(755,37,1,1,'Lo sé… pero ¿y si pasa algo? ¿Y si tú no estás y yo me hundo?'),
(756,37,1,1,'Me siento como si algo se fuera a romper.'),
(757,37,1,1,'No es culpa tuya. Solo… no puedo soportar imaginarte lejos. No en este momento.'),
(758,37,1,1,'No sabes cuánto necesitaba escucharte decir eso.'),
(759,37,1,1,'(Suspira. Se levanta de la cama y cierra la maleta a medias.)'),
(760,37,1,1,'(La mira)'),
(761,37,1,1,'(Se sienta de nuevo, con las manos sobre las rodillas.)'),
(762,37,1,1,'(Sonrie)'),
(763,37,1,1,'Gracias. Te juro que no quería que lo hicieras por mí, pero esto me da paz.'),
(764,37,1,1,'(Se queda en silencio)'),
(765,37,1,1,'(Finalmente la cierra del todo y se sienta de nuevo.)'),
(766,37,1,1,'(La mira)'),
(767,37,1,1,'(Sonrie)'),
(768,37,1,1,'Solo quería estar contigo. Gracias por entenderlo'),
(769,37,1,1,' (Se queda en silencio)'),
(770,37,1,1,'Gracias. No sabes cuánto significa eso para mí'),
(771,37,1,1,'(Se separa un poco, confusa.)'),
(772,37,1,1,'(Sonríe)'),
(773,37,1,1,'Sabía que me entenderías. Solo tú sabes cómo calmarme.'),
(774,37,1,1,'(Se queda en silencio)'),
(775,37,1,1,'(Mira la maleta abierta y empieza a sacar la ropa sin decir nada más.)'),
(776,37,1,null,'(Ahora tengo que escribirles a los del trabajo. ¿Qué les digo? ¿Que me puse enferma? ¿Que ha surgido algo personal?) '),
(777,37,1,null,'(Todo esto… por no hacerle daño. Pero, ¿y yo?) '),
---E.2
(778,38,1,null,'(Después de la conversación con David, el ambiente en la casa se vuelve más tranquilo.)'),
(779,38,1,1,'(Él se muestra aliviado. Se mueve por la cocina silbando suavemente mientras prepara la cena) '),
(780,38,1,null,'(Entra al salón con el portátil en brazos y lo deja sobre la mesa. Se sienta frente a él.)'),
(781,38,1,null,'(El ruido de las teclas es lo único que suena. Ya es de noche. El reloj marca las 23:48.)'),
(782,38,1,null,'(La pestaña del correo está abierta. Aún no hay nada escrito)'),
(783,38,1,null,'(Mira el portatil abierto)'),
(784,38,1,null,'(Escribe sin mirar mucho: “Hola. Lamento avisar tan tarde. Me encuentro mal esta noche, no podré viajar mañana. Lo siento.”)'),
(785,38,1,null,'(Se queda unos segundos en silencio antes de escribir.)'),
(786,38,1,null,'(Empieza a escribir: “Hola, me temo que estoy con fiebre y no podré asistir al viaje…”)'),
(787,38,1,null,'(Escribe el correo con rapidez. Apenas lo relee.)'),
(788,38,1,null,'(Escribe el correo despacio. A medida que las palabras aparecen en pantalla, sus ojos se llenan de lágrimas.)'),
(789,38,1,null,'(Lo lee solo una vez. Lo envía. )'),
(790,38,1,null,' (Luego cierra el portátil y se recuesta en el sofá, con la cabeza hacia atrás y los ojos cerrados.)'),
(791,38,1,1,'(Aparece con dos platos. Le da uno y se sienta junto a ella.)—Ahora sí. Podemos estar tranquilos.'),
(792,38,1,null,'(No siente paz. Solo inercia.)'),
(793,38,1,null,'(Escribe :“Hola equipo. Me sabe mal avisar así. Esta noche no me encuentro bien y no podré viajar mañana. Gracias por la comprensión.”)'),
(794,38,1,null,'(Lo relee una vez. Suspira. Envía.)'),
(795,38,1,1,'(Desde la cocina.)—¿Todo hecho?'),
(796,38,1,null,'(Se queda mirando el portátil cerrado, con una expresión ambigua: ni alivio, ni rabia. Solo un peso que no se va.)'),
(797,38,1,null,'(Luego borra “fiebre” y escribe “malestar”.)'),
(798,38,1,null,'(Lee el mensaje varias veces. Cambia el asunto del correo dos veces.)'),
(799,38,1,null,'(Finalmente, lo envía.Se queda mirando la pantalla)'),
(800,38,1,1,'(Se acerca y le acaricia el hombro.) —¿Ya está? Ahora puedes relajarte, ¿ves?'),
(801,38,1,null,'(Enseguida abre otro mensaje)'),
(802,38,1,null,'(Escribe a su equipo: “Siento mucho avisar a esta hora.)'),
(803,38,1,null,'("De verdad, lo siento. Espero que todo vaya bien.”) '),
(804,38,1,null,'(Le da a enviar. Luego se queda inmóvil, con las manos en el teclado.)'),
(805,38,1,1,'(Aparece con dos platos. Deja uno frente a ella.)—Me hace feliz que lo hayas hecho. Ahora podremos descansar.'),
(806,38,1,null,'(No llora con fuerza, pero una gota silenciosa cae sobre la tecla espaciadora.) '),
(807,38,1,null,'(La limpia rápido con la manga del pijama, sin hacer ruido.)'),
(808,38,1,null,'(Lee el mensaje en voz baja, apenas un susurro. No termina de procesar el contenido.)'),
(809,38,1,null,'(Hace clic en “Enviar”. Suspira, sin levantar la cabeza.)'),
(810,38,1,1,'¿Ya está hecho? Bien. Esto nos va a venir bien a los dos. Te lo prometo.'),
(811,38,1,1,'(La cena transcurre en silencio.)'),
---E.3
(812,38,1,1,'( David come tranquilo, sin preocuparse demasiado por llenar el vacío de palabras.)'),
(813,38,1,1,'(Al terminar, recogen en calma.)'),
(814,38,1,1,'(David le dice que se adelante a la cama, que ahora va. )'),
(815,39,1,1,'(Cuando él entra al cuarto, la encuentra ya acostada.)'),
(816,39,1,null,'(Se mete bajo las sábanas, la abraza desde atrás y se queda dormido en pocos minutos.)'),
(817,39,1,null,'(Mirando el techo)'),
(818,39,1,null,'(Se da la vuelta lentamente, sin despertar a David.)'),
(819,39,1,null,'(Se desliza con cuidado fuera de la cama. Busca su cuaderno en el escritorio)'),
(820,39,1,null,'(Acaricia la sábana con los dedos. Mira a David. Luego al techo.)'),
(821,39,1,null,'(Sus ojos están abiertos, pero no parpadea. )'),
(822,39,1,null,'(Se encoge sobre sí misma.)'),
(823,39,1,null,'(Mira el móvil en la mesilla. No lo toca.)'),
(824,39,1,null,'(Cierra los ojos con fuerza, intentando no pensar.Pero su cuerpo no se relaja.) '),
(825,39,1,null,'(Más tarde, se levanta en silencio, saca un cuaderno escondido bajo la ropa en un cajón y escribe) '),
(826,39,1,null,'(Luego lo vuelve a ocultar.)'),
(827,39,1,null,'(Lo abre con manos temblorosas y escribe sin pensar demasiado.)'),
(828,39,1,null,'(Frases cortas. Palabras sueltas. No busca sentido, solo dejar registro.)'),
(829,39,1,null,'(Luego lo esconde en el fondo de una mochila que guarda bajo la cama.)'),
(830,39,1,null,'(Siente una punzada en el estómago que no logra nombrar.)'),
(831,39,1,null,'(Piensa que solo fue un viaje. Que ya se pasará.) '),
(832,39,1,null,'(Antes de dormirse, se incorpora un segundo y anota en una libreta doblada dentro del cajón)'),
(833,39,1,null,'(Tiene el cuerpo tenso, la mente acelerada.)'),
(834,39,1,null,'(Casi sin darse cuenta, saca el cuaderno de su bolso y escribe) '),
(835,39,1,null,'(Luego lo guarda debajo del colchón.)'),
(836,39,1,null,'(Siente que la respiración no le alcanza. )'),
(837,39,1,null,'(Aprieta la mandíbula para no llorar.)'),
(838,39,1,null,'(Más tarde, busca en silencio el cuaderno escondido tras la cómoda.)'),
(839,39,1,null,'(Luego se mete en la cama, sin hacer ruido.)'),
(840,39,1,null,'(David sigue dormido.)'),
(841,39,1,null,'¡Enhorabuena!'),
--CAP7.1
(842,40,1,1,'(Es por la mañana. David se despierta antes y se mueve por la cocina en silencio. )'),
(843,40,1,1,'(Prepara café, pone la tostadora. )'),
(844,40,1,1,'(David la observa.)'),
(845,40,1,1,'Buenos días, dormilona. Hoy te traigo desayuno como en los viejos tiempos. ¿Ves cómo todo mejora?'),
(846,40,1,1,'(Él se acerca por detrás y la abraza, apoyando el mentón sobre su hombro.) '),
(847,40,1,1,'No sabes lo feliz que me hace verte así… aquí, tranquila. Es lo único que quería. Solo eso.'),
(848,40,1,1,'(La abraza)'),
(849,40,1,NULL,'(Bella se levanta con calma. Toma un sorbo del café, lo deja sobre la mesa.)'),
(850,40,1,1,'(Frunce levemente el ceño.)—¿Pasó algo?'),
(851,40,1,1,'(David le acaricia la espalda.)'),
(852,40,1,1,'(Le da un beso corto en la mejilla, con una sonrisa rápida.)'),
(853,40,1,1,'(Bella se gira hacia él. Lo abraza fuerte)'),
(854,40,1,1,'¿Te pasa algo? ¿No vas a decirme a dónde vas?'),
(855,40,1,NULL,'(Poco después, Bella sale ya vestida. Toma el bolso. No explica a dónde va. Solo necesita salir de ahí.)'),
(856,40,1,1,'Vale… está bien.'),
(857,40,1,NULL,'(Necesita salir a despejarse un rato)'),
(858,40,1,NULL,'(Comprueba que tiene su diario)'),
(859,40,1,NULL,'(Y sale)'),
(860,40,1,1,'(Asiente con reticencia, su tono apenas disimula la incomodidad.)—Vale. Pero no tardes mucho, ¿sí?'),
(861,40,1,NULL,'(Come algo aunque no tiene hambre.)'),
(862,40,1,NULL,'(Siente un nudo que no logra desatar.)'),
(863,40,1,NULL,'(No dice nada, pero por dentro algo le pesa.)'),
(864,40,1,NULL,'(David sale de la cocina con el desayuno)'),
(865,40,1,NULL,'(Mira al frente, sin moverse. Solo quiere estar sola.) '),
(866,40,1,NULL,'(Se queda ahí largo rato, respirando)'),
(867,40,1,NULL,'(Cuando escucha a David moverse de nuevo por la casa, se seca los ojos)'),
(868,40,1,NULL,'(Se pasa un poco de agua en la cara para disimular la hinchazón.)'),
(869,40,1,NULL,'(Sale como si nada)'),
(870,40,1,1,'(Sonríe satisfecho.)—Y tú a mí. Ya verás como todo se equilibra. Solo necesitábamos esto.'),
(871,40,1,1,'(David habla, ríe, le acaricia la mano.)'),
(872,40,1,NULL,'(Él se levanta para llevar los platos al salón)'),
(873,40,1,NULL,'(Se seca una lágrima rápida y va al salón como si nada hubiera pasado.)'),
(874,41,1,NULL,'(Mas tarde , ese mismo dia) '),
---E.2
(875,41,1,NULL,'(Mientras dobla ropa en el dormitorio)'),
(876,41,1,NULL,'(Ring : Notificación)'),
(877,41,1,NULL,'(Una amiga de la universidad con la que hace tiempo no habla.)'),
(878,41,1,NULL,'Maria (mensaje):Estoy por tu zona esta tarde. ¿Te apetece un café y ponernos al día? Hace mil que no te veo.'),
(879,41,1,NULL,'(Siente una chispa de entusiasmo… pero también una oleada de duda.)'),
(880,41,1,NULL,'(No sabe que hacer)'),
(881,41,1,NULL,'(María contesta rápido con un café cerca.)'),
(882,41,1,NULL,'(Cuando David vuelve de hacer una llamada, ella lo menciona.)'),
(883,41,1,NULL,'(Guarda el móvil sin responder de inmediato.)'),
(884,41,1,NULL,'(María reacciona con un “Vale, ya me dices”. David, que estaba cerca, pregunta sin levantar la voz.)'),
(885,41,1,1,'¿Todo bien?'),
(886,41,1,NULL,' (Bella deja el móvil sobre la colcha.) '),
(887,41,1,1,'¿Quién era?'),
(888,41,1,1,'¿Maria? ¿No era la que vivía lejos?'),
(889,41,1,1,'¿Hoy? ¿Ahora que por fin tenemos una tarde tranquilos?'),
(890,41,1,1,'(Él no insiste demasiado, pero hace un comentario al pasar.)'),
(891,41,1,1,'Ya sabes que últimamente estás muy dispersa... pero bueno, haz lo que creas.'),
(892,41,1,1,'(Le lanza una mirada rápida.)—¿Maria? ¿No era la que vivía lejos?'),
(893,41,1,1,'¿Hoy? Pero si justo íbamos a ver esa película que te gusta. Ya me estaba organizando para eso.'),
(894,41,1,1,'(La mira serio. Silencio. Luego suspira.)'),
(895,41,1,1,'Pero claro, si prefieres verla con tu amiga... Está bien.'),
(896,41,1,NULL,'(Responde a María: “Al final se me complicó, ¿quedamos otro día?”)'),
(897,41,1,1,'(Le menciona la propuesta a David.)'),
(898,41,1,1,'¿Y qué tiene de urgente verla justo hoy? Si ni hablas con ella desde hace cuánto…'),
(899,41,1,1,'Y además justo íbamos a ver esa película que te gusta. Ya me estaba organizando para eso. '),
(900,41,1,NULL,'(Manda un mensaje a María: “Se me complicó la tarde, te aviso para la próxima”. ) '),
(901,41,1,1,'¿Quién era?'),
(902,41,1,1,'Mejor. Hoy estás cansada y te hace bien quedarte aquí.'),
(903,41,1,NULL,'(Bella se siente pequeña)'),
(904,41,1,1,'(David la mira sin decir nada. El silencio pesa más que una respuesta directa.)'),
(905,41,1,1,'Sabes que eso me hace feliz, ¿no? Siempre estás mejor aquí, tranquila.'),
(906,41,1,NULL,'(Bella deja el móvil en la mesita boca abajo. )'),
(907,41,1,NULL,'(Se mira en el espejo del tocador)'),
(908,41,1,NULL,'(Sus ojos se ven apagados.)'),
(909,41,1,NULL,'(No responde el mensaje de María.)'),
(910,42,1,NULL,'(La televisión está encendida)'),
---E.3
(911,42,1,NULL,'(Pero ninguno de los dos la está viendo con atención.)'),
(912,42,1,1,'(David la mira de reojo.)'),
(913,42,1,1,'Estás muy callada últimamente.'),
(914,42,1,1,'Antes no eras así.'),
(915,42,1,1,'Antes me contabas todo. Ahora no sé ni lo que piensas. Es como si vivieras en tu mundo.'),
(916,42,1,1,'(La mira)'),
(917,42,1,1,'(Frunce un poco el ceño.)'),
(918,42,1,1,'(Frunce un poco el ceño.)'),
(919,42,1,1,'(Frunce un poco el ceño.)'),
(920,42,1,1,'(Frunce un poco el ceño.)'),
(921,42,1,1,'(Le acaricia la mano. Su gesto es suave, casi paternal.)—Solo quiero que estés bien. No te alejes de mí, eso es todo.'),
(922,42,1,1,'(La mira)'),
(923,42,1,1,'Ah. Bueno… está bien.'),
(924,42,1,1,'(David se levanta para ir al baño)'),
(925,42,1,null,'(Abre su cuaderno, escribe durante unos minutos)'),
(926,42,1,null,'(Mas tarde lo guarda en un lugar discreto)'),
(927,42,1,1,'(La observa, desconfiado.)—Pero me estás dejando fuera'),
(928,42,1,1,'(Asiente, pero la observa detenidamente.)—Mmm. Bueno. Espero que no estés ocultando nada.'),
(929,42,1,1,'(Pero el cuerpo de bella está tenso, las manos entrelazadas en el regazo.)'),
(930,42,1,null,'(Esa noche, en el baño, anota un rato en su cuaderno)'),
(931,42,1,1,'¿Dispersa con qué? ¿Algo que no me cuentes?'),
(932,42,1,1,'(Asiente, pero la observa detenidamente.)—Mmm. Bueno. '),
(933,42,1,null,'(Esa noche, en el baño, se sienta en el suelo y saca su libreta)'),
(934,42,1,1,'(La mira)'),
(935,42,1,1,'(Asiente)—Mmm. '),
(936,42,1,null,'(Esa noche, en el baño, se sienta en el suelo y saca su libreta)'),
(937,42,1,null,'(Lo abre y escribe durante unos minutos)'),
(938,42,1,null,'¡Enhorabuena!'),
--CAP7.2
(939,43,1,1,'(Es por la mañana. David se despierta antes y se mueve por la cocina en silencio. )'),
(940,43,1,null,'(Tiene pensado salir a dar un paseo después del desayuno.)'),
(941,43,1,1,'(David la observa.)'),
(942,43,1,1,'Estás muy "relajada" con la ropa últimamente, ¿no? Antes te arreglabas más. Era bonito verte con otro estilo.'),
(943,43,1,1,'(La observa)'),
(944,43,1,1,'(La sigue mirando)'),
(945,43,1,1,'(La sigue mirando)'),
(946,43,1,1,'Sólo lo decía porque me gustaba cuando te arreglabas. Nada más.'),
(947,43,1,1,'Ya'),
(948,43,1,1,'(La sigue mirando)'),
(949,43,1,null,'(Bella camina hacia la nevera. El silencio se estira unos segundos.)'),
(950,43,1,1,'(David no insiste, pero la observa.)'),
(951,43,1,1,'Solo era un comentario'),
(952,43,1,1,'Bueno, si ya no se puede ni hablar...'),
(953,43,1,1,'(Frunce el ceño.)—Era una broma, Bella. No te lo tomes tan en serio.'),
(954,43,1,1,'Vale… ahora resulta que ya no voy a poder hablarte. Pues nada.'),
(955,43,1,null,'(Se da la vuelta, sirve su café y cambia de habitación.) '),
(956,43,1,null,' ( La sonrisa de Bella desaparece en segundos.)'),
(957,43,1,null,'(Bella mira por la ventana, perdida en sus pensamientos.)'),
(958,43,1,1,'(Levanta una ceja, aún mirándola.)—Bueno. Cada quien...'),
(959,43,1,1,'(Asiente en silencio, da un sorbo a su café sin decir nada más.)'),
(960,43,1,null,'(La conversación quedó flotando en el aire)'),
(961,43,1,null,'(Se pasa los dedos por el pelo una y otra vez.)'),
(962,43,1,null,'(No sabe si cambiarse.)'),
(963,43,1,1,'No es para que te sientas mal. Solo echo de menos cómo te veías antes. Pero me encanta que lo tengas en cuenta.'),
(964,43,1,null,'(Bella deja el café a medias y va al cuarto.)'),
(965,43,1,null,'(Abre el armario y coge una camisa con botones que le regaló david)'),
(966,43,1,null,'(Se la pone sin mirarse demasiado. Ni se pregunta si le gusta.)'),
(967,43,1,1,'(Al volver, David le dice que está más guapa así. )'),
---E.2
(968,44,1,NULL,'(Más tarde ese día, Bella tiene que hacer una llamada de trabajo)'),
(969,44,1,1,'(David está cerca, hojeando una revista en el sofá, pero atento.)'),
(970,44,1,10,'(Comienza la videollamada)'),
(971,44,1,10,'(La conversación gira en torno a un informe, una próxima entrega.)'),
(972,44,1,10,'(Sin embargo, hay algo contenido en su voz.)'),
(973,44,1,10,'(Hablanco con su compañera)'),
(974,44,1,NULL,' (Cierra la tapa del portátil. Se queda un momento en silencio) '),
(975,44,1,NULL,'(Se ríe suavemente con algo que dice su compañera.)'),
(976,44,1,NULL,'Ah, vale… ¿entonces te pillo ocupada?'),
(977,44,1,NULL,'(Con una sonrisa incómoda.) —Bueno… claro.'),
(978,44,1,NULL,'Vale , entonces...'),
(979,44,1,1,'(David la mira)'),
(980,44,1,1,'(David se levanta para ir al cuarto)'),
(981,44,1,NULL,' (Bella se pone los auriculares. Aunque no hay música, el silencio la alivia.)'),
(982,44,1,1,'(Desde el sofá, con una ceja levantada.)—¿Estás muy habladora hoy, no?'),
(983,44,1,NULL,' (Cuando termina la llamada, respira profundo y se queda mirando la pantalla) '),
(984,44,1,10,'(La compañera asiente, aunque la mención resulta un poco forzada.)'),
(985,44,1,NULL,'(Al rato la reunión termina)'),
(986,44,1,NULL,'(David se levanta y sin decir nada, le da un beso en la cabeza antes de alejarse.)'),
(987,44,1,10,'(Sin esperar respuesta, le gira el portatil.) '),
(988,44,1,10,'(La compañera al otro lado parece sorprendida, pero saluda.)'),
(989,44,1,1,'(David responde con una sonrisa medida)'),
(990,44,1,10,'Bueno , entonces...'),
(991,44,1,1,'(Desde el sofá, sin levantar mucho la voz.)—No sé por qué siempre te tienen que molestar con llamadas a estas horas.'),
(992,44,1,1,'(David se levanta, se acerca por detrás y le da un beso en la cabeza.)'),
(993,44,1,1,'(Al tiempo ,esa misma tarde, David sale de casa.)'),
---E.3
(994,44,1,NULL,'(Dice que tiene que pasar por el banco y luego verá a un amigo.)'),
(995,44,1,NULL,'(Cierra la puerta tras él y, por un instante, todo queda en silencio.)'),
(996,44,1,NULL,'(Su móvil está sobre la mesa. El sol entra por la ventana. Tiene un rato para sí misma, y lo sabe. Pero... ¿qué hace con él?)'),
(997,44,1,NULL,'(Se recuesta con un suspiro.) '),
(998,44,1,NULL,'(Busca el contacto de Laura)'),
(999,44,1,NULL,'(Camina del salón a la cocina y vuelta.)'),
(1000,44,1,NULL,'(Pliega una manta, alinea los cojines, limpia la mesa.) '),
(1001,44,1,NULL,'(Se sienta en el borde del sofá)'),
(1002,44,1,NULL,'(Enciende la televisión pero baja el volumen al mínimo.)'),
(1003,44,1,NULL,'(Las imágenes pasan frente a sus ojos sin que ella les preste atención.)'),
(1004,44,1,NULL,'(Cierra los ojos unos minutos. No piensa en nada, y eso le parece suficiente.) '),
(1005,44,1,NULL,'(En lugar de escribir, pulsa el botón de llamada.)'),
(1006,44,1,NULL,'Cuando Laura contesta, Bella sonríe.'),
(1007,44,1,NULL,'(Hablan de cosas sencillas: la vida, los días, una serie.)'),
(1008,44,1,NULL,'(Después de colgar)'),
(1009,44,1,NULL,'(Mira el reloj. Saca el móvil)'),
(1010,44,1,NULL,'(Lee conversaciones antiguas, especialmente una con Ana, pero no se atreve a reactivar el contacto.) '),
(1011,44,1,NULL,'(Vuelve a guardar el teléfono.)'),
(1012,44,1,NULL,'(Se sienta en la orilla del sofá)'),
(1013,44,1,NULL,'(Se levanta) '),
(1014,44,1,NULL,'(Abre la ventana un segundo y la vuelve a cerrar)'),
(1015,44,1,NULL,'(Mira alrededor.) '),
(1016,44,1,NULL,'(Todo está impecable.)'),
(1017,44,1,NULL,'(Sabe que David no le ha pedido nada, pero su cuerpo actúa como si lo hubiera hecho.) '),
(1018,44,1,NULL,'(No enciende la televisión, no saca el teléfono. )'),
(1019,44,1,NULL,'(Cruza las manos en el regazo) '),
(1020,44,1,NULL,'(Cada ruido en la escalera la hace girar la cabeza hacia la puerta)'),
(1021,44,1,NULL,'(Siente que no puede usar ese tiempo para ella)'),
(1022,44,1,NULL,'(Siente que está perdiendo algo, pero no sabe qué.)'),
(1023,44,1,NULL,'¡Enhorabuena!'),
--CAP7.3
(1024,45,1,NULL,'(Es final de tarde. Bella está guardando cosas)'),
(1025,45,1,1,'(Cuando David entra con el móvil en la mano. Tiene el ceño fruncido, la mandíbula apretada.)'),
(1026,45,1,1,'¿Esto qué es? (Le muestra una foto en la pantalla. Es del grupo del trabajo, en una terraza, charlando.Bella aparece al fondo, riéndose con dos compañeros.)'),
(1027,45,1,1,'¿Desde cuándo sales así sin decirme? ¿Desde cuándo te da igual si te escribo?'),
(1028,45,1,1,'(La mira fijamente)'),
(1029,45,1,1,'Siempre “nada más”. Pero cada vez me cuentas menos, ¿no? ¿Ya no necesitas hablarme?'),
(1030,45,1,1,'(Continua mirandola)'),
(1031,45,1,1,'¿Y no pensaste en avisarme?'),
(1032,45,1,1,'(Continua mirandola)'),
(1033,45,1,1,'(Continua mirandola)'),
(1034,45,1,1,'(Seco, cortante.)—Ah, claro. Ahora ya no puedo ni preguntar sin que te pongas así.'),
(1035,45,1,1,'(Se gira hacia ella con una mueca de disgusto.) —Bueno, si te molesta tanto, pues olvídalo. Haz lo que te dé la gana.'),
(1036,45,1,1,'(Continua mirandola)'),
(1037,45,1,1,'¿Y si hubiera sido al revés? ¿Qué habrías dicho tú? Seguro que no lo tomas tan a la ligera.'),
(1038,45,1,1,'(Baja la mirada, avergonzada de su propio argumento. La conversación se enfría, pero el juicio permanece en el ambiente.)'),
(1039,45,1,1,'¿Y quién decidió eso? ¿Eva? ¿Marco? ¿Otra vez con ellos?'),
(1040,45,1,1,'(Se queda en silencio)'),
(1041,45,1,1,'No es lo que hiciste. Es cómo lo hiciste. Que ni me avisas. Que ni me tienes en cuenta.'),
(1042,45,1,1,'(Seco, con un suspiro largo.)—Pues pensaste poco en mí. Pero nada, ya da igual.'),
(1043,45,1,NULL,'(No contesta. Se da la vuelta, vuelve al salón. El portazo es suave, pero igual duele.)'),
(1044,45,1,NULL,'(Se queda sola.) '),
(1045,45,1,NULL,'(No importa la forma que tomó la discusión: el resultado es el mismo) '),
--E.2
(1046,46,1,NULL,'(Horas después, el silencio aún flota en el aire.)'),
(1047,46,1,1,'(David se ha quedado en el salón, viendo televisión sin mucho interés.)'),
(1048,46,1,NULL,'(Pero ya cae la noche, y algo dentro de ella la empuja a acercarse.)'),
(1049,46,1,NULL,'(Camina hasta el sofá con pasos medidos.)'),
(1050,46,1,1,'(No la mira)'),
(1051,46,1,1,'(Asiente con un gesto breve, sin mirarla.)'),
(1052,46,1,null,'(Quizá, si puede hablarle de algo sencillo, la tensión baje.)'),
(1053,46,1,1,'(Vuelven a sentarse. David apenas come.)'),
(1054,46,1,1,'(No la mira)'),
(1055,46,1,1,'(Se ríe entre dientes)'),
(1056,46,1,1,'(La interrumpe casi de inmediato.)—¿Hablas de tí pero y yo? ¿Tú sabes cómo me siento últimamente?)'),
(1057,46,1,1,'(Bella se queda callada unos segundos. Lo mira, luego baja la vista hacia su plato.)'),
(1058,46,1,1,'(Silencio)'),
(1059,46,1,1,'(Bella se acomoda en el sofá, traga saliva.)'),
(1060,46,1,1,'(Pausa.)'),
(1061,46,1,1,'(Pausa.)'),
(1062,46,1,1,' (Recoge su plato sin terminar de comer.)'),
(1063,46,1,1,'(Se levanta sin tono de reproche. Va hacia el dormitorio.) '),
(1064,46,1,1,'(La mira con los ojos entrecerrados.)—¿Ahora soy el egoísta? Perfecto. Me lo apunto.'),
(1065,46,1,1,'(Sigue mirandola)'),
(1066,46,1,1,'(David no responde. Se queda mirando la pantalla. Pero algo en el ambiente cambia)'),
(1067,46,1,1,'(David la interrumpe antes de que termine.)'),
(1068,46,1,1,'¿Y yo? ¿Tú sabes cómo me siento últimamente?'),
(1069,46,1,1,'(Se encoge un poco sobre sí misma. Da un bocado, finge atención a la tele.) '),
(1070,46,1,1,'(Suspira como si soltara un peso.)—Nada… ya sabes. Que últimamente estás como… distante. Y me cuesta.'),
(1071,46,1,1,'(Bella se inclina hacia él. Le acaricia el brazo. )'),
(1072,46,1,1,'(Él no responde)'),
(1073,46,1,1,'(Sin mirarla.)—Claro. A veces lo único que quiero es que me mires y me escuches como antes.'),
(1074,46,1,1,'(Bella le sonríe, pero los ojos están apagados.)'),
(1075,46,1,1,'(No la mira)'),
(1076,46,1,1,'(Asiente con la cabeza sin soltar palabra.)'),
(1077,46,1,1,'(Y vuelve el silencio)'),
---E.3
(1078,47,1,NULL,'(Es la tarde del día siguiente.) '),
(1079,47,1,NULL,'(Bella a salido un momento a comprar algunas cosas que hacían falta.)'),
(1080,47,1,NULL,'(Ha caminado despacio, como si estirar el trayecto pudiera estirar también el silencio que lleva dentro desde la noche anterior.)'),
(1081,47,1,NULL,'(Al regresar, entra al piso con bolsas pequeñas, cuida de no hacer ruido al cerrar.)'),
(1082,48,1,1,'(David está en la sala.)'),
(1083,48,1,1,'(La observa dejar las bolsas sobre la encimera. Su voz irrumpe seca.)—¿Dónde estabas?'),
(1084,48,1,1,'¿Y por qué no contestaste los mensajes? ¿Por qué siempre parece que se te olvida avisarme?'),
(1085,48,1,1,'¡¿Ah, sí?! ¡Pues a mí sí me hace falta saber dónde estás! ¿O te da igual lo que yo sienta? ¡Seguro que te cruzaste con alguien y por eso te olvidaste de mí!'),
(1086,48,1,1,'(La mira con furia)'),
(1087,48,1,1,'(El enfado no desaparece de su mirada)'),
(1088,48,1,1,'(El enfado no desaparece de su mirada)'),
(1089,48,1,1,'(El enfado no desaparece de su mirada)'),
(1090,48,1,1,'(El enfado no desaparece de su mirada)'),
(1091,48,1,1,'¡Siempre lo mismo! ¡Tú vas, vienes, decides y yo aquí como un tonto! ¿Qué se supone que tengo que hacer? ¿Pedirte permiso para que me tengas en cuenta? ¿Es eso?'),
(1092,48,1,1,'(Silencio)'),
(1093,48,1,1,'¿Hablarlo con calma? Siempre lo mismo. ¡Te vas como si nada y luego me sales con que “no fue con mala intención”!'),
(1094,48,1,1,'(La mira)'),
(1095,48,1,1,'(David no responde. Se gira molesto, refunfuñando algo que Bella no escucha del todo.) '),
(1096,48,1,null,'(Ella guarda las últimas cosas)'),
(1097,48,1,NULL,'(Se escucha la puerta del baño cerrarse con un portazo. Se sienta en el borde de la sofá. Respira hondo, con las manos sobre las rodillas. Aún tiembla.)'),
(1098,48,1,1,'¡Ah, claro! Ahora resulta que el problema soy yo, ¿no?'),
(1099,48,1,1,'¡Te vas como si nada y luego me sales con que “no fue con mala intención”!'),
(1100,48,1,1,'Siempre tienes una excusa, ¿verdad? Cada vez te pareces menos a la persona con la que empecé todo esto.'),
(1101,48,1,1,'Sí, claro. Siempre "solo un rato". No te importa lo que me genera esto.'),
(1102,48,1,1,'¿Te parece normal dejarme aquí esperando sin decir nada? ¿Eso es tener respeto por alguien?'),
(1103,48,1,1,'(La mira furioso)'),
(1104,48,1,1,'¿Nada? ¿Ni una palabra?'),
(1105,48,1,null,'¡Enhorabuena!'),
--CAP7.4
(1106,49,1,NULL, '(Es media tarde)'),
(1107,49,1,NULL, '( Bella está en la cocina, preparando algo de merienda.)'),
(1108,49,1,NULL, '(La televisión suena baja en el fondo.) '),
(1109,49,1,NULL, '(David está en el salón, revisando su móvil.)'),
(1110,49,1,NULL, '(De pronto, su ceño se frunce.En su Instagram, ha aparecido una historia de Marco, compañero de trabajo de Bella.)'),
(1111,49,1,1, '(Con tono seco, entra en la cocina)—Vaya… Qué simpática tú, ¿no?'),
(1112,49,1,1, 'Nada. Solo que es curioso cómo reaccionas a las historias de Marco. Un corazón , nada menos.'),
(1113,49,1,1, '(La mira fijamente)'),
(1114,49,1,1, 'No reviso nada. Estaba viendo mi movil. Me salió tu reacción a su historia. ¿Qué quieres demostrar?'),
(1115,49,1,1, 'Siempre reaccionándole a Marco. Siempre tú con él. ¿Quieres que piense que no hay algo raro ahí?'),
(1116,49,1,1, '¿Otra vez Marco? ¿No te cansas? ¿Tan buena onda tienen que tenés que reaccionar a cada historia que sube?'),
(1117,49,1,1, '¿Tú te das cuenta? Siempre tú con Marco. ¿De verdad crees que eso no me afecta? ¿O te importa poco?'),
(1118,49,1,1, 'Ya estoy harto de esto. Siempre tú con los mismos. Siempre esa necesidad de gustarle a todos.'),
(1119,49,1,1, 'Ya… siempre “no hice nada malo”. Qué fácil.'),
(1120,49,1,1, '¿Te hace gracia todo lo que sube o solo lo haces para que note que lo miras?'),
(1121,49,1,1, 'Pues haberlo pensando antes'),
(1122,49,1,null, '(Se gira, camina hasta el dormitorio. Da un portazo)'),
(1123,49,1,NULL, '(Deja que el cuerpo se le hunda contra el suelo.)'),
(1124,49,1,1, 'Claro, claro. Siempre “nada más”. Pero cuando lo hace alguien más, te molesta. ¿No es así?'),
(1125,49,1,1, 'Entonces soy inseguro. Perfecto. ¿Ahora soy el paranoico?'),
(1126,49,1,1, '¿Cualquier otro? Porque parece que con él es especial. ¿También te ríes así en persona?'),
(1127,49,1,1, '¿Y me lo dices ahora? Qué conveniente.'),
(1128,49,1,1, 'No es solo eso. No lo sigas más. ¿Para qué? ¿Para que se piense que puede contigo?'),
(1129,49,1,1, 'Si de verdad quisieras eso, no harías cosas que sabes que duelen.'),
(1130,49,1,1, '(Lo toma. Revisa. Silencio. Luego lo deja sobre la mesa sin decir más.)'),
---E.2
(1131,50,1,null, '(Después de la discusión anterior, la casa permanece en silencio. )'),
(1132,50,1,null, '(David no le dirige la palabra a Bella.)'),
(1133,50,1,1, '(Bella lo observa moverse como si ella no existiera.)'),
(1134,50,1,null, '(Intenta acercarse, romper el hielo, pero solo recibe gestos cortantes, indiferencia.)'),
(1135,50,1,1, '(David no nombra el enfado. Solo la ignora.)'),
(1136,50,1,1, '(La televisión está encendida, pero sin volumen. David se ha sentado en el sofá con el mando en la mano, mirando sin mirar.)'),
(1137,50,1,null, '(Lo mira y no sabe que hacer)'),
(1138,50,1,null, '(No dice nada. Abre la nevera, saca un poco de arroz del día anterior.)'),
(1139,50,1,null, '(Toma su abrigo del respaldo de la silla.)'),
(1140,50,1,null, '(Se acerca al sofá, casi de puntillas.)'),
(1141,50,1,null, '(Saca ingredientes. Prepara el pollo con la receta que a él le gusta.)'),
(1142,50,1,1, '(Se arrodilla junto al sofá, le apoya la mano en el brazo con cuidado.)'),
(1143,50,1,null, '(Lo calienta. Saca un plato, se sienta en la mesa del comedor, en silencio.)'),
(1144,50,1,null, '(Mastica despacio, sin hambre real.)'),
(1145,50,1,null, '(Luego coge un libro. Finge que lee.)'),
(1146,50,1,null, '(Pero no pasa de página. Lo mira de reojo.)'),
(1147,50,1,null, '(Él ni se mueve.)'),
(1148,50,1,null, '(Camina hacia la puerta.)'),
(1149,50,1,null, '(No dice a dónde va.)'),
(1150,50,1,null, '(La cierra detrás de sí sin dar portazo.)'),
(1151,50,1,null, '(El aire frío le quema los ojos. Pero sigue caminando.)'),
(1152,50,1,null, '(Cuando al rato vuelve a casa , todo sigue igual)'),
(1153,50,1,1, '(Todavía sin mirarla.)—¿Te parece que estoy bien?'),
(1154,50,1,1, 'No finjas que te importa ahora. Ya hablaste lo que tenías que hablar antes.'),
(1155,50,1,1, '(Cambia de canal con el mando. El silencio vuelve.)'),
(1156,50,1,null, '(Luego Bella retrocede, casi imperceptiblemente.)'),
(1157,50,1,null, '(Va hacía el cuarto)'),
(1158,50,1,null, '(No dice nada más. Corta, fríe, sirve.)'),
(1159,50,1,null, '(Deja el plato humeante sobre la mesa, con cubiertos y servilleta.)'),
(1160,50,1,null, '(De pie, mirando el plato servido.)'),
(1161,50,1,1, '(Ni una palabra desde el sofá.)'),
(1162,50,1,1, '(Rígido. No se mueve. No la mira.)'),
(1163,50,1,1, 'Déjalo ya.'),
(1164,50,1,null, '(Se incorpora despacio. Camina hacia el cuarto)'),
(1165,51,1,null, '(Cierra la puerta. Se sienta en el suelo.)'),
(1166,51,1,null, '(Se abraza las piernas. Su rostro se hunde entre las rodillas.)'),
---E.3
(1167,51,1,NULL, '(Ha pasado más de una hora)'),
(1168,51,1,NULL, '(El silencio sigue llenando el piso. )'),
(1169,51,1,NULL, '(Se lavó los dientes, apagó las luces del pasillo.)'),
(1170,51,1,NULL, '(Ahora está en el dormitorio, con las sábanas recogidas hasta la cintura)'),
(1171,51,1,1, '(David entra. No habla de inmediato,se acomoda junto a ella sin mirarla ) '),
(1172,51,1,1, '(Después de un largo silencio.—He estado pensando...'),
(1173,51,1,1, 'Si de verdad quieres que te perdone. Si quieres que esto funcione de verdad, Bella... vas a tener que borrarte las redes.'),
(1174,51,1,1, 'No lo digo por castigo, lo digo porque ya no sé en quién confiar. Y esto, así, no puede seguir.'),
(1175,51,1,1, '(La mira fijamente)'),
(1176,51,1,1, 'No se trata de lo que hiciste. Se trata de cómo me siento. Y esto me ayudaría.'),
(1177,51,1,1, 'No quiero que te expongas a cosas que luego nos hagan mal. Es por ti, por nosotros.'),
(1178,51,1,1, 'Es que no quiero que haya más interferencias entre nosotros. Esto es por tu bien también.'),
(1179,51,1,1, 'No tienes que ponerte así. Solo quiero sentirme seguro contigo. ¿Eso está mal?'),
(1180,51,1,1, 'Es lo mínimo que podrías hacer si de verdad te importa esta relación. No lo estoy diciendo por capricho.'),
(1181,51,1,1, '(Bella saca su móvil. Abre la app. Mira la pantalla un momento.)'),
(1182,51,1,1, '(La mira)'),
(1183,51,1,1, '(Sonríe levemente.)—Gracias. En serio. Lo valoro.'),
(1184,51,1,1, 'Es lo mínimo que podrías hacer si de verdad te importa esta relación. No lo estoy diciendo por capricho.'),
(1185,51,1,1, '(La mira)'),
(1186,51,1,1, 'Exacto. No quiero más problemas entre nosotros.'),
(1187,51,1,1, '(Bella se levanta, coge el móvil.)'),
(1188,51,1,1, '(La mira'),
(1189,51,1,1, '¿Ves? Era solo eso. Ahora estamos más tranquilos.'),
(1190,51,1,1, '(La mira)'),
(1191,51,1,1, '(Abre el móvil, con dedos temblorosos. Borra todas sus cuentas. Luego deja el dispositivo boca abajo sobre la mesita. Se sienta a su lado.)'),
(1192,51,1,1, '(Le pasa un brazo por encima de los hombros.)—Así estamos mejor. Ahora sí te siento cerca otra vez.'),
(1193,51,1,1, '(Abre el móvil. En cuestión de segundos, elimina todas las redes. Luego lo deja a un lado.)'),
(1194,51,1,1, '(La mira)'),
(1195,51,1,1, 'Gracias. De verdad. Esto me demuestra que sí quieres que esto funcione.'),
(1196,51,1,NULL, '(Bella se gira hacia el lado opuesto en la cama.) '),
(1197,51,1,NULL, '(Solo hay una sensación persistente de haber entregado otra parte de sí misma, sin saber cómo recuperarla.)'),
(1198,51,1,NULL, '¡Enhorabuena!'),
--CAP8.1
(1199,52,1,NULL, '(Bella está saliendo del baño cuando escucha la voz de David en el salón.)'),
(1200,52,1,NULL, '(Él está hablando por teléfono con un amigo.)'),
(1201,52,1,NULL, '(No se ha dado cuenta de que ella ya puede oírle.)'),
(1202,52,1,NULL, 'David (por teléfono, riéndose):—Tío, ya sabes cómo es… se ahoga en un vaso de agua. Siempre con sus crisis, sus dramas. Le dejo creer que tiene razón y se calma. Es lo que hay.'),
(1203,52,1,NULL, '(Pausa. Escucha. Luego sigue.)'),
(1204,52,1,NULL, 'David: —Sí, claro. Si me pusiera firme de verdad, duraba dos días. Pero bueno, de vez en cuando hay que fingir que cedes para que no explote.'),
(1205,52,1,NULL, 'David: -Si, si , Venga tio , nos vemos (Unos segundos después, cuelga.)'),
(1206,53,1,1, '(Se recuesta en el sofá, ajeno a que Bella ha oído todo.)'),
(1207,53,1,NULL, '(Respira hondo y, tras unos segundos, camina despacio hacia el salón.) '),
(1208,53,1,NULL, '(Lo observa en silencio sin entrar al salon)'),
(1209,53,1,NULL, '(Todavia no se ha dado cuenta de que está ahí)'),
(1210,53,1,1, '(Se gira, molesto.)—¿Perdona? ¿Desde cuándo escuchas detrás de las puertas?'),
(1211,53,1,1, '(Frunce el ceño.)—¿Estabas escuchando?'),
(1212,53,1,1, '(Se encoge de hombros.)—¿Y ahora qué? Era una broma. '),
(1213,53,1,1, '(Bella se sienta cerca de él en el sofá.)'),
(1214,53,1,1, 'Sí, claro. Ahora la culpable soy yo por hacer una broma con un amigo, ¿no?.'),
(1215,53,1,1, 'Esto ya es demasiado, Bella'),
(1216,53,1,NULL, '(Bella se da la vuelta y va hacía el dormitorio.)'),
(1217,53,1,1, 'No deberías meterte en lo que no te llaman. Era una conversación privada.'),
(1218,53,1,1, '¿Y ahora todo lo que digo es ridiculizarte? ¿Ni una broma puedo hacer?'),
(1219,53,1,1, '¿Vas a montarme un drama por eso también?'),
(1220,53,1,1, 'Pues no escuches conversaciones ajenas.'),
(1221,53,1,1, '(Se sorprende por su actitud.)—No pasa nada. Si lo reconoces, entonces todo bien.'),
(1222,53,1,1, 'Sí… solo intento que estemos bien.'),
(1223,53,1,NULL, 'Se queda ahí en el pasillo mirandolo'),
(1224,53,1,NULL, 'La frase sigue repitiéndose en su mente como un eco maldito:"Si le das la razón un rato, se calma."'),
---E.2
(1225,54,1,NULL, '(Después del momento incómodo con la llamada, el resto del día transcurre en una calma artificial.) '),
(1226,54,1,NULL, '(Nadie volvió a mencionar lo ocurrido.)'),
(1227,54,1,NULL, '(Por la noche, están en el sofá viendo algo en la televisión.)'),
(1228,54,1,NULL, '(No hablan mucho, pero David ha estado más cercano: su brazo sobre el respaldo)'),
(1229,54,1,NULL, '(Comentarios sueltos, gestos de cariño )'),
(1230,54,1,NULL, '(Bella buscando recuperar algo de normalidad, comenta con ligereza.)'),
(1231,54,1,NULL, '(La mira)'),
(1232,54,1,1, '(La mira sin girar del todo la cabeza.)—¿Y tú le dijiste que sí? ¿Que estás buscando irte?'),
(1233,54,1,1, 'A veces siento que te da igual lo que tenemos.'),
(1234,54,1,1, 'Yo… yo no podría con eso.Si algún día me dejas… no sé qué haría.'),
(1235,54,1,1, '(David la mira)'),
(1236,54,1,1, 'Era un comentario. No hace falta que lo tomes tan literal.'),
(1237,54,1,1, 'Lo digo porque es verdad. A veces siento que te estás alejando. Y me asusta.'),
(1238,54,1,1, 'Es que últimamente todo me hace ruido. Me siento en segundo plano.'),
(1239,54,1,1, 'Es que si tú me dejas, yo no soy nadie. No tendría sentido nada.'),
(1240,54,1,1, '(Se queda un segundo mirandola)'),
(1241,54,1,1, 'Haz lo que quieras.'),
(1242,55,1,NULL, '(Ya en su habitación, cierra la puerta y saca su cuaderno.)'),
(1243,55,1,NULL, '(Escribe. Luego se queda en silencio, sintiendo el eco de la frase.)'),
(1244,55,1,NULL, '"No sé qué haría sin ti… eso debería preocuparte."'),
(1245,55,1,1, 'Es solo que a veces pareces tan distante… me entra miedo. Pero vale, lo dejo.'),
(1246,55,1,1, 'No sé… a veces no siento que estés del todo aquí.'),
(1247,55,1,NULL, '(Bella mira el reloj y cambia de tema, pero la incomodidad se le queda clavada.) '),
(1248,55,1,1, '(La mira)'),
(1249,55,1,1, 'Pues demuéstralo. A veces siento que soy el único que pone de su parte.'),
(1250,55,1,1, 'Solo quiero que lo recuerdes. Que no se te olvide nunca.'),
(1251,55,1,NULL, '(Bella siente una presión en el pecho. No dice más. La conversación termina con un silencio espeso.)'),
---EP3
(1252,56,1,NULL,'(A la mañana siguiente, la luz entra débil por la ventana.)'),
(1253,56,1,NULL,'(David parece de buen humor: le ofrece café, comenta algo sobre el tráfico con tono casual. Como si nada hubiera pasado.)'),
(1254,56,1,1,'¿Nos vamos ya? Te acerco si quieres. Hoy me viene bien.'),
(1255,56,1,NULL,'(Se encierra en el baño. Se lava los dientes. Mira su reflejo: la expresión tensa. Se recoge el pelo. Suspira.)'),
(1256,56,1,NULL,'(Al salir, va directa a coger su bolso. Busca su móvil en la mesa. Lo desbloquea y, mientras lo mete en el bolso, ve una notificación en la pantalla.)'),
(1257,56,1,NULL,'(Un mensaje de Clara, su amiga: —“No pasa nada. Nos vemos otro día :)”)'),
(1258,56,1,NULL,'(Lee el mensaje anterior, enviado desde su móvil)'),
(1259,56,1,NULL,'("Bella:Hola, mejor lo dejamos para otro día. Estoy con muchas cosas.")'),
(1260,56,1,NULL,'(No lo escribió. Pero está enviado desde su número.)'),
(1261,56,1,NULL,'(Siente el estómago contraerse. Mira hacia el pasillo)'),
(1262,56,1,1,'(David silba mientras se pone la chaqueta.)'),
(1263,56,1,NULL,'(Respira hondo. Cierra la conversación. Se aleja un poco de la vista de David.) '),
(1264,56,1,1,'(Se queda inmóvil.)—¿Qué? ¿Qué dices?'),
(1265,56,1,1,'¿Qué?'),
(1266,56,1,1,'¿Qué más da? Solo estaba ayudando. Es que a veces tú no ves lo que te conviene.'),
(1267,56,1,NULL,'(Deja el móvil donde estaba. Se termina de abrochar la chaqueta. David aparece por el pasillo.)'),
(1268,56,1,NULL,'(Entra a la app de ajustes, pulsa en “Seguridad”. Cambia la contraseña.)'),
(1269,56,1,NULL,'(Se lo guarda en el bolsillo sin decir palabra.)'),
(1270,56,1,1,'¿Todo bien?'),
(1271,56,1,1,'(Suelta una risa seca.)—Te estaba quitando un compromiso que te estresaba. '),
(1272,56,1,1,'Solo quería evitar que te agobiaras. Siempre te quejas de que no tienes tiempo. Pensé que te hacía un favor.'),
(1273,56,1,1,'Ah, claro… ahora no puedo preocuparme por ti. Todo lo que hago es control, ¿no?'),
(1274,56,1,1,'¿Si? Pues vete andando (Luego, coge su chaqueta y sale de casa)'),
(1275,56,1,1,'Ay, Bella. No sabía que eso te molestaría tanto. Era solo para que descansaras, ¿no estabas muy agobiada últimamente?'),
(1276,56,1,1,'Pues denada, venga vamonos '),
(1277,56,1,NULL,'(Luego, sin decir nada, coge su chaqueta y sale de casa detrás de él)'),
(1278,56,1,1,'¿Y por qué te molesta tanto? ¿Qué tienes que ocultar?'),
(1279,56,1,1,'(La mira)'),
(1280,56,1,1,'A veces hay que hacer lo que es mejor para los dos, aunque tú no lo veas en el momento. No te estoy espiando, Bella. Me preocupo por ti.'),
(1281,56,1,1,'(David vuelve a lo suyo como si nada.)'),
(1282,56,1,1,'¿Vamos?'),
(1283,56,1,NULL,'(Bella sale tras él, con los hombros tensos. El móvil, sin contraseña nueva, queda en su bolso.)'),
(1284,56,1,NULL,'¡Enhorabuena!'),
--CAP8.2
(1285,57,1,NULL,'(Es por la mañana.Bella está en casa revisando su calendario y respondiendo algunos correos del trabajo desde su portátil)'),
(1286,57,1,1,'(David está por ahí, con actitud calmada)'),
(1287,57,1,NULL,'(Tras una media hora de concentración, Bella se levanta para ir al baño.)'),
(1288,57,1,NULL,'(Al rato, vuelve al salón) '),
(1289,57,1,1,'(Cuando vuelve, escucha un clic de ratón justo antes de doblar el pasillo. Al entrar al salón, ve a David frente a la pantalla, moviendo el cursor por una conversación abierta.)'),
(1290,57,1,1,'Nada... viendo tu fondo de pantalla. Me llamó la atención la foto esa del mar. Ya sabes que me gusta.'),
(1291,57,1,NULL,'(La pantalla aún muestra una ventana abierta con el correo)'),
(1292,57,1,1,'Te molestas por nada. Ni siquiera vi nada importante.'),
(1293,57,1,1,'Exageras. Era solo curiosidad. ¿Qué tanto escondes que no puedo ver?'),
(1294,57,1,1,'Ay, por favor. Eres demasiado delicada. Solo estaba viendo una pestaña abierta, no te hackeé el ordenador.'),
(1295,57,1,1,'¿Tus cosas? Solo vi el fondo. Me confundí, no sé ni lo que era.'),
(1296,57,1,1,'Ves como sí exageras. No hay que ponerse dramática.'),
(1297,57,1,1,'(Él no responde. Agarra el mando y enciende la televisión. El sonido llena el espacio como un muro invisible.)'),
(1298,57,1,NULL,'(Bella se sienta otra vez delante del portátil)'),
(1299,57,1,NULL,'(Abre el portátil de nuevo. Cambia la contraseña. Activa un bloqueo de inicio.) '),
(1300,57,1,1,'(La mira)'),
(1301,57,1,1,'(Él hace un gesto vago.)'),
(1302,57,1,NULL,'(Bella se sienta de nuevo, obligándose a sonreír.)'),
(1303,57,1,1,'¿Y por qué reaccionas así? ¿Tienes algo que esconder?'),
(1304,57,1,1,'(David se encoge de hombros. Se levanta, camina hacia la cocina.)'),
(1305,57,1,1,'(La mira)'),
(1306,57,1,1,'(David se levanta, le da una palmadita en el hombro como si todo estuviera resuelto, y se va a la cocina.)'),
(1307,57,1,NULL,'(Ese día Bella no toca el ordenador. Siente que su privacidad se ha vuelto inútil.) '),
(1308,57,1,NULL,'(Recogió lentamente sus cosas )'),
(1309,57,1,NULL,'(No dijo nada más.)'),
(1310,57,1,NULL,'(Solo sintió una presión en el pecho)'),
---E.2
(1311,57,1,NULL, '(Ese mismo día más tarde Bella está poniéndose las zapatillas junto a la puerta.)'),
(1312,57,1,NULL,'(Lleva una mochila ligera y una lista de cosas que necesita comprar.)'),
(1313,57,1,NULL,'(También pensaba aprovechar para caminar un poco. Un rato para ella.)'),
(1314,57,1,1,'David está en el sofá, en pijama, con el móvil en la mano. Cuando la ve prepararse, frunce levemente el ceño.'),
(1315,57,1,1,'¿Vas a salir?'),
(1316,57,1,1,'Voy contigo.Me apetece caminar contigo. Hace tiempo que no salimos juntos así.'),
(1317,57,1,1,'Ah, claro... Tú necesitas tu espacio. Yo solo molesto.'),
(1318,57,1,1,'(La mira con el ce´ño fruncido)'),
(1319,57,1,1,'(Resopla, gira el rostro hacia la ventana.)—Haz lo que quieras.'),
(1320,57,1,1,'(La observa)—Como quieras. Yo solo quería pasar tiempo contigo.'),
(1321,57,1,1,'Ya… claro. Necesitas pensar sola. Supongo que a mí no me necesitas para eso.'),
(1322,57,1,1,'No es que me apetezca. Es que me preocupa lo mucho que últimamente quieres ir sola.'),
(1323,57,1,1,'¿Ves? Solo era cuestión de hablarlo. Me molesta cuando me dejas fuera.'),
(1324,57,1,NULL,'(Cuando Bella baja las escaleras, siente que algo en ese momento se queda guardado. No lo olvidará.)'),
(1325,57,1,NULL,'(Abre la puerta. Sale. El aire de la calle la golpea suave, como un alivio inesperado.)'),
(1326,57,1,1,'Claro... necesitas tu espacio. Como si yo fuera el problema.'),
(1327,57,1,1,'Bueno. Haz lo que quieras. Tú verás.'),
(1328,57,1,NULL,' (Bella sale, pero con el corazón acelerado. Mientras camina, repasa la conversación, intentando convencerse de que no ha hecho nada malo.)'),
(1329,57,1,1,'Eso está mejor. Así no tengo que estar pensando con quién estarás.'),
(1330,57,1,1,'Bueno, vamos. Me vendrá bien también tomar un poco de aire.'),
---E.3
(1331,58,1,NULL,'(Una hora después del paseo . Ya en casa David ha preparado algo rápido para cenar.)'),
(1332,58,1,NULL,'(Comen frente a frente en la mesa del comedor. El ambiente es tranquilo, pero Bella aún siente el eco del paseo que no quiso compartir.)'),
(1333,58,1,1,'¿Diseño? Qué curioso... Nunca me habías mencionado eso antes.'),
(1334,58,1,1,'(Pausa breve. Intenta sonar neutral, pero hay una sombra de reproche.)—¿Y eso de repente por qué?'),
(1335,58,1,1,'(Asiente despacio, pero no la mira. Toma un sorbo de agua, dejando que el silencio se estire.)—Claro. Algo para ti.'),
(1336,58,1,1,'Porque supongo que lo que ya tienes no es suficiente.'),
(1337,58,1,1,'¿Y necesitas estar buscando cosas distintas? ¿Qué es lo que te falta? ¿Yo no te doy lo suficiente?'),
(1338,58,1,1,'Siempre se trata de eso. Tú quieres algo tuyo, como si todo esto no fuera también para ti.'),
(1339,58,1,1,'(Pausa breve. Su mirada se endurece.)—Dime, Bella… tú sin mí, ¿qué tienes?'),
(1340,58,1,1,'(Ahora su voz es un susurro cargado de veneno) —Tú sin mí no eres nadie.'),
(1341,58,1,1,'No me hagas enfadar, Bella. No me pongas en la posición de tener que salir por esa puerta. Porque si yo no te quiero… nadie más te va a querer.'),
(1342,58,1,1,'¿Ah, no? ¿Quién más ha estado ahí cuando no eras capaz ni de hablar? ¿Quién te ha aguantado? ¿Quién ha estado cuando ni tú te soportabas?'),
(1343,58,1,1,'Tú no sabes estar sola. Sin mí, no sabrías por dónde empezar.'),
(1344,58,1,1,'¿Miedo? ¿Ahora resulta que me tienes miedo?'),
(1345,58,1,1,'(Camina alrededor de la mesa, despacio, sin dejar de mirarla.)—¿Qué te he hecho yo?'),
(1346,58,1,1,'Tú no tienes ni idea de lo que es tener problemas de verdad, Bella.'),
(1347,58,1,1,'(Señala alrededor con gesto amplio)—Mira esto. ¿Te falta algo? ¿Te ha faltado algo desde que estás conmigo?'),
(1348,58,1,1,'¡No! No empieces. No me vengas ahora con más “sentimientos” y “necesito espacio”.'),
(1349,58,1,1,'Estoy harto de tus quejas disfrazadas de independencia. Tú no sabes lo que es estar sola. Lo que es luchar de verdad.'),
(1350,58,1,1,'(Acerca su cara a la de ella, sin tocarla.)—Y sabes qué... te estás creyendo un cuento que no te pertenece.'),
(1351,58,1,1,'(Se endereza, frío.)—Ya va siendo hora de que empieces a valorar lo que tienes.'),
(1352,58,1,1,'(Se gira, va hacia la cocina, toma un vaso de agua como si nada hubiera pasado. Desde allí, sin mirarla.)—Mañana acuérdate de pasar por la lavandería. Y no llegues tarde.'),
(1353,58,1,1,'(Él vuelve a sentarse, prende el televisor. El sonido del noticiero llena la habitación como un velo incómodo.)'),
(1354,58,1,NULL,'(Abre el grifo. El agua corre. Se queda allí, mirando cómo cae. No lava nada.) '),
(1355,58,1,NULL,'(Sus manos tiemblan. No por lo que él dijo. Sino porque empieza a entender que sí tiene miedo. ) '),
(1356,58,1,null,'¡Enhorabuena!'),
--CAP8.3
(1357,59,1,NULL,'(Bella ha pasado la tarde intentando concentrarse en su portátil. David ha estado dando vueltas, sin decir mucho, con ese tipo de energía que pesa.Bella ha pasado la tarde intentando concentrarse en su portátil. David ha estado dando vueltas, sin decir mucho, con ese tipo de energía que pesa.)'),
(1358,59,1,NULL,'(Horas antes, Bella recibió un mensaje del trabajo confirmándole que el equipo quiere contar con ella para una pequeña presentación la semana siguiente.)'),
(1359,59,1,NULL,'(Lo mencionó de forma casual en la sobremesa, intentando sonar neutra. David apenas respondió.)'),
(1360,59,1,NULL,'(Pero ahora, en el salón, mientras ella recoge unas tazas y se prepara para apagar la luz, él rompe el silencio con un tono filoso, sin levantar la voz… pero sin esconder el veneno.)'),
(1361,59,1,1,'Así que te invitan a hablar en público… Qué rápido se olvidan algunas de lo que costó levantar cabeza, ¿no?'),
(1362,59,1,1,'Nada. Solo que antes llorabas por todo y ahora pareces otra. Como si el trabajo fuera lo único que importa.'),
(1363,59,1,1,'(Camina hacia ella. No grita, pero su tono sube con la rabia contenida.)—Porque parece que ahora todo te da igual.'),
(1364,59,1,1,'¿Y yo cuándo me volví un problema para ti, eh? Mírate… con tu portátil, tus reuniones, tus mensajitos.Antes te importaba lo que yo decía. Ahora apenas te importa si estoy aquí.'),
(1365,59,1,1,'¡Claro! Siempre estás cansada cuando se trata de mí. Pero bien que para tus compañeros sonríes. Bien que tienes energía para quedar bien con todos.'),
(1366,59,1,1,'Ingrata. Yo he estado contigo cuando no podías ni levantarte de la cama, cuando llorabas por todo.Y ahora… ¿me sales con que quieres ir sola a presentaciones, a talleres, a cenas?'),
(1367,59,1,1,'(Niega con la cabeza)—Estás fatal. Siempre tan inestable.'),
(1368,59,1,NULL,'(Bella se queda en silencio. Lo mira brevemente, luego baja la vista. Respira hondo.)'),
(1369,59,1,1,'¿Eso es todo lo que tienes que decir? Qué fácil se te hace ahora escaparte.'),
(1370,59,1,1,'¿Bueno para ti? Claro. Porque lo único que te importa eres tú últimamente.'),
(1371,59,1,1,'Siempre tienes una excusa. Siempre haces lo que quieres y luego vienes con esa vocecita a suavizar todo.'),
(1372,59,1,1,'¿Lo ves? Al menos lo reconoces. Porque a veces pareces olvidarlo.'),
(1373,59,1,1,'Claro, calladita. Como siempre que sabes que tengo razón.'),
(1374,59,1,1,'¿Y ahora qué? ¿También huyes? Muy maduro de tu parte. (Grita a través de la puerta)'),
(1375,59,1,1,'No me hables de límites. Los tuyos cambian según te conviene. No tienes ni idea de lo que es compromiso.'),
(1376,59,1,1,'¿Ah, sí? Pues no lo parece. Cada vez estás más lejos. Y encima me haces sentir como si yo fuera el problema.'),
(1377,59,1,1,'¿Parte de qué? Si ya tienes tu vida montada. Lo que te molesta es que me dé cuenta.'),
(1378,59,1,1,'Pues cuéntame cosas que importen. No tonterías de trabajo que te alejan de lo esencial.'),
---E.2
(1379,60,1,null,'(Desde el dormitorio se escucha la voz de david)'),
(1380,60,1,NULL,'(Golpea la puerta. )—¿De verdad me vas a ignorar ahora?'),
(1381,60,1,NULL,'(Su voz desde el otro lado de la puerta.)—Bella… abre, no quiero discutir. Solo quiero hablar.'),
(1382,60,1,1,'¿Así que ahora me bloqueas en mi propia casa? ¿Esa es la dinámica?'),
(1383,60,1,1,'Y no estoy discutiendo. Solo me parece una falta de respeto.'),
(1384,60,1,1,'Claro. Porque la mártir eres tú, ¿no?'),
(1385,60,1,1,'(De pronto, se da la vuelta, agarra un jarrón de la cómoda y lo lanza con violencia contra la pared. Se rompe en mil pedazos.)'),
(1386,60,1,1,'¡¿Eso querías?! ¡¿Que perdiera el control?! ¡Pues ahí lo tienes!'),
(1387,60,1,1,'(Respira agitado. La mira de arriba abajo.)—¿Y ahora qué? ¿Vas a seguir haciéndote la víctima?'),
(1388,60,1,1,'(Le da una risa amarga.)—¿Ahora te crees madura? ¿Te vas como si fueras la sensata?'),
(1389,60,1,1,'¡No me digas cómo estoy! ¿Tú qué sabes de lo que es aguantar? Solo hablas cuando te conviene.'),
(1390,60,1,1,'¡Lo mínimo! ¿Sabes la rabia que da sentirse ignorado? ¿Como si no contara?'),
(1391,60,1,1,'Claro. Tú siempre callada, siempre en modo mártir. Me haces parecer un monstruo.'),
(1392,60,1,1,'¿Otra vez el silencio como castigo? '),
(1393,60,1,1,'(Se le acerca un poco más. El tono se endurece.) —¡Háblame, joder! ¿No vas a decir nada? ¡Mírame cuando te hablo!'),
(1394,60,1,1,'(Se gira, furioso. Patea la mesita sin volcarla, agarra sus llaves del mueble de entrada.)'),
(1395,60,1,1,'Me voy. Quédate con tu silencio. ¡Disfrútalo!(Sale dando un portazo que retumba en la casa.)'),
(1396,60,1,1,'Claro, paz. ¿Y yo qué? ¿El que grita por gusto? Perfecto. Vete. Haz lo que te dé la gana, como siempre.(Coge sus llaves.)'),
(1397,60,1,1,'Me largo. A ver si así respiras tranquila. (Se marcha, dando un portazo. )'),
(1398,60,1,1,'¿Miedo te doy ahora? Qué fácil es decir eso cuando tú provocas todo esto.(Se dirige a la puerta sin esperar más.)'),
(1399,60,1,1,'Me voy. A ver si el mundo te trata mejor que yo.'),
(1400,60,1,1,'Compartir. Siempre compartes con todos menos conmigo.(La mira un segundo más, frustrado. Toma sus llaves y se va.)'),
(1401,60,1,1,'A la mierda. Me voy. No sé qué hago aquí.(Da un portazo y Bella se queda sola, con los trozos aún en la mano.)'),
(1402,60,1,1,'Y ni siquiera dices lo que piensas. Porque si lo hicieras, sabrías que sin mí no puedes.'),
(1403,60,1,1,'No aguanto esto. No más.(Saca sus llaves del cajón con rabia y se va, cerrando la puerta con un golpe seco.)'),
(1404,60,1,NULL,'(Bella se queda sola , quieta, sin saber que hacer)'),
---E.3
(1405,60,1,NULL,'(El sonido del portazo aún resuena en las paredes, pero la casa ha quedado en un silencio espeso, como un eco mudo de todo lo que no se dijo.)'),
(1406,60,1,NULL,'(Bella sigue sentada en el suelo del dormitorio, con la espalda apoyada contra la puerta, la mirada vacía clavada en la alfombra.)'),
(1407,60,1,NULL,'(No sabe cuánto tiempo ha pasado. Cinco minutos. O una hora.)'),
(1408,60,1,NULL,'(De repente, la puerta se abre lentamente. David ha vuelto. No entra con furia.)'),
(1409,60,1,1,'(No grita. Tiene la mirada baja, los hombros caídos. Cierra la puerta detrás de él con cuidado, como si el golpe anterior no hubiera ocurrido)'),
(1410,60,1,1,'(Se queda de pie, unos pasos dentro del dormitorio. No la mira directamente.)—No quería gritar… No quería llegar a esto. No sé qué me pasa.'),
(1411,60,1,1,'Es como si se me fuera el suelo cuando siento que te alejas. Me desespero.'),
(1412,60,1,1,'Tú eres lo único bueno que tengo. Si tú te vas, yo no soy nadie.'),
(1413,60,1,1,'(Se sienta en el suelo, contra la pared, cubriéndose la cara con las manos.) —No quiero perderte… No sé qué me pasa. Me descontrolo y después me odio por dentro.'),
(1414,60,1,1,'(La mira fijamente)'),
(1415,60,1,1,'No me reconozco cuando exploto. Es como si me desconectara. Pero después… después me odio tanto.'),
(1416,60,1,1,'(La mira fijamente)'),
(1417,60,1,1,'Si tú te vas… yo no lo soporto.'),
(1418,60,1,1,'Ayúdame. No me dejes. Te juro que voy a cambiar. No volverá a pasar.'),
(1419,60,1,1,'Tienes razón. Lo sé. Soy un desastre.'),
(1420,60,1,1,'¡No lo volveré a hacer! Lo juro. Por ti haría lo que fuera. Solo… quédate.'),
(1421,60,1,1,'¿Por qué no me dejas ayudarte a ser mejor? '),
(1422,60,1,1,'(Le toma la mano.)—Solo quédate. Prometo que cambiaré.'),
(1423,60,1,1,'Yo tampoco sé por qué reacciono así. Es como si no pudiera controlarme. '),
(1424,60,1,1,'Gracias por entenderme. Gracias…'),
(1425,60,1,1,'Te juro que no va a volver a pasar. '),
(1426,60,1,NULL,'¡Enhorabuena!'),
--CAP8.4
(1427,61,1,NULL,'(Es temprano. Bella ha dormido poco.)'),
(1428,61,1,NULL,'( Se viste en silencio, recoge su bolso y se dirige a la puerta para salir al trabajo)'),
(1429,61,1,NULL,'(Desde la cocina, David bebe café, observando sus movimientos con la mirada baja pero atenta.)'),
(1430,61,1,NULL,'(Cuando gira la cerradura, siente la resistencia: está pasada con doble vuelta desde dentro.)'),
(1431,61,1,1,'(Con voz suave, sin levantar la vista.)-Sí. Eché la llave esta mañana temprano.'),
(1432,61,1,1,'(Se encoge de hombros, como si fuera lo más normal del mundo.) —Porque creo que deberías tomarte el día libre.'),
(1433,61,1,1,'(La mira por primera vez.) —Estás tensa últimamente. Nerviosa. Malhumorada. No creo que te haga bien salir así.'),
(1434,61,1,1,'(Pone la taza en la encimera, sin dejar de mirarla.)—Estuve mirando tu agenda. Vi que hoy tienes reunión con Marcos.'),
(1435,61,1,1,'Otra vez él, ¿no?'),
(1436,61,1,1,'Dime la verdad, Bella. ¿Crees que me voy a quedar tan tranquilo mientras tú andas por ahí con alguien que no me inspira confianza?'),
(1437,61,1,1,'(La mira)'),
(1438,61,1,1,'¿Derecho? ¿Y tú qué haces cada vez que te callas, que me niegas lo que te pasa?'),
(1439,61,1,1,'"Solo trabajo". ¿Así se llama ahora? Cada vez que mencionas a ese tal Marcos te pones tensa.'),
(1440,61,1,1,'No quiero obligarte. Solo me duele sentir que prefieres estar con cualquiera menos conmigo.'),
(1441,61,1,1,'Pero lo haces. Todo el tiempo. Con tus silencios, tus planes, tus evasivas. ¿Cómo quieres que me sienta?'),
(1442,61,1,1,'(Se cruza de brazos, frunciendo el ceño.)—¿Así de fácil? ¿Ni una conversación puedes darme antes de irte con él?'),
(1443,61,1,1,'(Se encoge de hombros sin mirarla.)—¿Y qué pasa si te digo que no me siento cómodo con que salgas hoy?'),
(1444,61,1,1,'(La mira por fin, con dureza.) —¿Y tú tienes derecho a dejarme aquí con esta sensación? De que me estás escondiendo algo. De que me estás cambiando.'),
(1445,61,1,1,'(Levanta la voz, sin gritar.)—Demasiado es lo que estás haciendo tú. No voy a abrir. '),
(1446,61,1,1,'Estoy tratando de proteger lo que tenemos. Pero parece que te da igual.'),
(1447,61,1,1,'Pues asfíxiate si quieres, pero hoy no vas a salir.'),
(1448,61,1,1,'Claro, todo es inocente contigo. Siempre todo es profesional… menos cuando se trata de ser honesta conmigo.'),
(1449,61,1,1,'Entonces quédate. No será tan grave faltar un día.'),
(1450,61,1,1,'¿Y si trabajar implica acercarte a alguien que no me respeta? ¿Qué hago yo con esa angustia?'),
(1451,61,1,1,'(Suspira, con voz más tierna.)—Quédate. Será mejor para los dos.'),
(1452,61,1,1,'Pues ahora lo sabes. Y si de verdad te importo, te quedarás.'),
(1453,61,1,1,'Así estamos mejor. Tranquilos.'),
(1454,61,1,NULL,'(Bella camina despacio hasta el sofá)'),
(1455,61,1,NULL,'(Se sienta en silencio, con el bolso aún en el regazo.)'),
(1456,61,1,NULL,'(Mira la puerta cerrada.)'),
---
(1457,61,1,NULL, '(David sigue sin abrirla)'),
(1458,61,1,1, 'Ya lo hemos hecho '),
(1459,61,1,1, '(La mira, congelado por un segundo. )'),
(1460,61,1,1, '(Luego gira bruscamente hacia la mesa. Su rostro, en tensión. El gesto parece lento, pero la rabia se acumula como una ola.)'),
(1461,61,1,1, '(Sin previo aviso, agarra un vaso que había sobre la encimera y lo lanza contra la pared. El estruendo del cristal estallando llena la habitación.)'),
(1462,61,1,1, '(La observa en silencio unos segundos, luego golpea la mesa con la palma abierta.)—Haz lo que te dé la gana. ¡Siempre igual!'),
(1463,61,1,null, '(Desde dentro del baño, escucha pasos agitados. Un cajón, las llaves. La puerta principal se abre con brusquedad.)'),
(1464,61,1,1, '(Susurra con rabia contenida.)—No empieces tú también a dramatizar…'),
(1465,61,1,1, '(Le lanza una mirada dura, se pasa la mano por el rostro y resopla.)—¡Siempre la misma historia! Todo lo haces mal, y luego lloras como si eso arreglara algo.'),
(1466,61,1,1, '(Bella se agacha, empieza a barrer los restos del vaso. Le tiembla el cuerpo, pero no lo muestra.)'),
(1467,61,1,null, '(Desde dentro, escucha pasos rápidos. Unas llaves tintinean. La cerradura gira. Luego, un portazo seco, brutal.)'),
(1468,61,1,1, 'Quédate con tus silencios. ¡Haz lo que te dé la gana! (Y luego, un portazo.)'),
(1469,61,1,1, '¡Claro! ¡Ahora también me das lecciones de calma! Qué risa…'),
(1470,61,1,1, '(David cruza el salón con paso brusco, abre un cajón, saca las llaves con rabia.)'),
(1471,61,1,1, '¡¿Sabes qué?! Quédate aqui con tus tonterías. (Abre la puerta ,con las llaves, de golpe.Portazo.)'),
(1472,61,1,1, '(Sin mirarla más, se dirige al mueble del salón, abre un cajón y agarra las llaves con violencia.)'),
(1473,61,1,1, '¡Pues llora tranquila! Te dejo con tus dramas.(Abre la puerta de golpe. El marco vibra. La luz de la mañana entra como un golpe frío.)'),
(1474,61,1,1, '¡Haz lo que te dé la gana!(Portazo. )'),
(1475,61,1,1, '(La observa con una mezcla de desprecio y desprecio.) —Eres un espectáculo.'),
(1476,61,1,1, '(Cruza el salón. Abre un cajón con fuerza, saca las llaves, camina hacia la puerta. La abre de un tirón.) —¡Haz lo que te dé la gana!'),
(1477,61,1,NULL, '(Portazo. El eco resuena en las paredes.)'),
(1478,61,1,NULL, '(Bella se queda ahí sin saber que pensar)'),
---E.3
(1479,61,1,NULL,'(  Una hora ha pasado desde que David salió dando un portazo.)'),
(1480,61,1,NULL,'(Bella no ha llorado. No se ha movido. ) '),
(1481,61,1,NULL,'(El sonido de la cerradura al abrirse la despierta de golpe.)'),
(1482,61,1,1,'(David entra, con los hombros tensos y la mandíbula apretada)'),
(1483,61,1,1,'(No dice nada al principio. Deja las llaves en la mesa con brusquedad.)'),
(1484,61,1,1,'¿Ya se te pasó la rabieta?'),
(1485,61,1,1,'Ah, claro. Ahora tú eres la víctima perfecta. Qué fácil te resulta hacerme quedar como el monstruo.'),
(1486,61,1,1,'¿Y qué vas a hacer? ¿Irte? ¿Contárselo a todos? ¿A Marcos, quizá?'),
(1487,61,1,1,'¡Todo tiene que ver conmigo! Porque si no fuera por mí, tú no estarías ni la mitad de bien que ahora. ¡Lo he dado todo! ¡Y así me lo pagas!'),
(1488,61,1,1,'(Se acerca rápido. La toma por los brazos.) ¡No tendrías que hacer nada si no estuvieras buscando siempre la manera de alejarte! ¡Si no escondieras cosas, si no buscaras excusas para estar con otros!'),
(1489,61,1,1,'(Sin escucharla. La agarra con más fuerza y la empuja con violencia contra la pared.)—¡No me hables como si yo fuera tu enemigo!'),
(1490,61,1,1,'(Bella queda pegada a la pared, respirando con dificultad)'),
(1491,61,1,1,'(Por un segundo, ni uno de los dos se mueve.)'),
(1492,61,1,1,'(Sin decir una palabra, se aleja de él lentamente. Abre la puerta del baño, entra y la cierra con seguro. Se apoya contra la madera, temblando.)'),
(1493,61,1,1,'No… claro que no. Solo… me provocas. Me sacas de quicio cuando actúas como si yo no importara.'),
(1494,61,1,1,'Es que me presionas… no puedo respirar cuando actúas como si yo no contara.'),
(1495,61,1,1,'¿Eso es todo lo que vas a decir?'),
(1496,61,1,null,'(Desde el otro lado de la puerta, golpea con la palma abierta.) —¡Bella! ¡No me dejes así!'),
(1497,61,1,null,'(Le da otro golpe, menos fuerte.)—¡No quise hacerlo! ¡Pero tú me presionas! ¡No me dejes solo ahora!'),
(1498,61,1,1,'Tú eres todo lo que tengo.'),
(1499,61,1,1,'Tú siempre lo llevas todo al límite. Y luego yo soy el que explota…'),
(1500,61,1,1,'No me gusta esto, Bella. Odio sentir que me estás juzgando.'),
(1501,61,1,1,'No quise empujarte… Pero es que tú no entiendes lo que es estar así, tan perdido'),
(1502,61,1,NULL,'La casa queda en completo silencio.'),
(1503,61,1,NULL,'¿Enhorabuena?'),
--CAP9.1
(1504,62,1,NULL,'(Es de madrugada.)'),
(1505,62,1,NULL,'(La casa está en silencio, pero Bella no duerme)'),
(1506,62,1,NULL,'(Hace horas que David se acostó, pero ella sigue despierta, con la luz del móvil reflejándose en su rostro. )'),
(1507,62,1,NULL,'(En su mente, algo ha cambiado. No es una fantasía ni una posibilidad. Es una certeza.)'),
(1508,62,1,NULL,'(Tiene que irse.)'),
(1509,62,1,NULL,'(Mira alrededor con una nueva lucidez: el abrigo colgado detrás de la puerta, el bolso donde guarda sus documentos, la ubicación de su cargador.)'),
(1510,62,1,NULL,'(Todo empieza a tener valor estratégico.)'),
(1511,63,1,NULL,'(El espejo refleja su cansancio.)'),
(1512,63,1,NULL,'(Toma el móvil. Con los dedos temblorosos escribe)'),
(1513,63,1,11,'Mensaje a Eva:"Necesito tu ayuda"'),
(1514,63,1,11,'Bella:“¿Podrías ayudarme a salir de aquí? No quiero que él lo sepa todavía.”'),
(1515,63,1,11,'Respuesta de Eva:“Cuando digas. Estoy contigo.”'),
(1516,63,1,NULL,'(Volvió a la cama)'),
(1517,64,1,NULL,'(No durmió bien.)'),
(1518,65,1,null,'(Al día siguiente temprano en la cocina)'),
(1519,65,1,null,'(La luz entra pálida por la ventana.)'),
(1520,65,1,1,'(David ya está vestido, revisando el móvil.)'),
(1521,65,1,1,'(Levanta la vista lentamente. Cierra la pantalla del móvil.)—¿Sí? ¿Qué pasa ahora?'),
(1522,65,1,1,'(La mira)'),
(1523,65,1,1,'(Frunce el ceño)'),
(1524,65,1,1,'(La mira fijamente)'),
(1525,65,1,1,'(Pausa. Un segundo exacto de silencio absoluto.)'),
(1526,65,1,1,'(Frunce el ceño. Su mandíbula se tensa.) —¿Cómo que dejarlo?'),
(1527,65,1,1,'(Suelta una risa seca. Luego deja la taza con un golpe sordo en la encimera.)—Mira, no tengo tiempo para tus dramatismos esta mañana.'),
(1528,65,1,1,'No vamos a hablar de esto ahora.'),
(1529,65,1,1,'Cuando vuelva, lo hablamos con calma. ¿Vale?'),
(1530,65,1,1,'Ya te calmarás. Siempre haces esto cuando te llenas de ideas.'),
(1531,65,1,1,'Después hablamos.'),
(1532,65,1,NULL,'(Cierra la puerta al salir. El silencio que queda no es alivio. ) '),
(1533,65,1,11,'Bella:“Está fuera. ¿Puedes venir?”'),
(1534,65,1,11,'Clara (Respuesta inmediata):“Voy. En 20.”'),
(1535,65,1,NULL,'(El sonido del timbre hace que Bella se sobresalte.)'),
(1536,66,1,7,'(Entra rápido. No abraza a Bella de inmediato. Le toma el rostro con ambas manos.)—¿Estás bien?'),
(1537,66,1,7,'(La abraza entonces, con fuerza, pero sin brusquedad. Bella se derrumba un instante, en silencio. Luego se separan.)—¿Tienes algo preparado?'),
(1538,66,1,7,'Vale. Lo primero: mochila con lo básico. DNI, tarjeta, móvil, cargador, ropa interior. ¿Tienes algún sitio donde quieras ir?'),
(1539,66,1,7,'Entonces vienes conmigo. Lo resolvemos paso a paso. ¿Sí?'),
(1540,66,1,7,'(Comienzan a moverse. Clara abre cajones, pregunta antes de tocar. Bella responde con la mirada o con gestos breves.)'),
(1541,66,1,NULL,'(Bella saca una mochila. Mete dos pantalones, cuatro camisetas. Mete ropa interior, el neceser.)'),
(1542,66,1,7,'Yo los busco. ¿Dónde están?'),
(1543,66,1,7,'(Clara se mueve con rapidez y cuidado. Encuentra la carpeta azul. )'),
(1544,66,1,7,'(Vuelve con los documentos.)—Aquí está todo. DNI, tarjeta sanitaria, copia del contrato.'),
(1545,66,1,7,'Bella… ¿quieres dejarle algo?'),
(1546,66,1,12,'(Escribe)'),
(1547,66,1,NULL,'(Dobla la hoja. La deja en el centro de la mesa del salón)'),
(1548,66,1,7,'¿Lista?'),
(1549,66,1,NULL,'(Apaga la luz del salón. Ambas caminan hasta la puerta. Clara abre. Bella cruza el umbral, se detiene medio segundo y vuelve a cerrar la puerta detrás de ella. ) '),
(1550,66,1,NULL,'(Con suavidad, gira la llave y escucha el sonido firme del cerrojo.)'),
(1551,66,1,NULL,'( Y por primera vez vez en mucho tiempo , no tuvo miedo)'),
(1552,66,1,NULL,'¡Enhorabuena, has terminado Bella´s Heart!'),
--CAP9.2
(1553,67,1,NULL,'(La televisión está apagada. Las persianas bajadas a medias dejan entrar una luz apagada, casi triste.)'),
(1554,67,1,NULL,'(Bella está sola. David ha salido hace un rato, sin decir a dónde iba. No le avisó, pero ella no preguntó.'),
(1555,67,1,NULL,'(Se sienta frente al portátil. Lo abre con una lentitud automática. Como si no supiera muy bien por qué lo hace.) '),
(1556,67,1,NULL,'(Durante un rato, el cursor parpadea en el buscador.)'),
(1557,67,1,NULL,'(Luego, sin pensarlo demasiado, teclea:“cómo saber si estás en una relación tóxica”)'),
(1558,67,1,NULL,'(“Pareja me controla pero no me pega”)'),
(1559,67,1,NULL,'(“Violencia psicológica señales”)'),
(1560,67,1,NULL,'(Uno a uno, los resultados aparecen)'),
(1561,67,1,NULL,'(Artículos. Foros. Blogs. Testimonios con nombres que no recuerda.Frases que duelen de tan parecidas.)'),
(1562,67,1,NULL,'(En pantalla:“No es que seas débil. Es que estás sobreviviendo.”“El miedo no necesita gritos para instalarse.”“Cuando empiezas a preguntarte si lo que vives es normal… probablemente ya no lo es.”'),
(1563,67,1,NULL,'(Lee en silencio.Sus dedos tiemblan apenas sobre el touchpad. Siente un nudo en la garganta. No llora.)'),
(1564,67,1,NULL,'(“Te aísla sin que te des cuenta.”“Te convence de que todo es por tu bien.”)'),
(1565,67,1,NULL,'Clic.'),
(1566,67,1,NULL,'(La habitación parece la misma, pero no lo es.)'),
(1567,68,1,NULL,'( Es media tarde. El sol entra por las persianas, cortando la sala en líneas de luz y sombra.)'),
(1568,68,1,NULL,'David ha salido a comprar algo. No dijo cuánto tardaría. Bella no lo preguntó.'),
(1569,68,1,11,'En la mesa, el móvil de Bella vibra con un mensaje:“Sabes que estoy aquí para o que necesites. No lo dudes. – Eva”'),
(1570,68,1,NULL,'(Suspira. Siente el latido acelerado. Mira a su alrededor.)'),
(1571,68,1,NULL,'(Es la primera vez en semanas que está sola en casa.Tiene miedo. Pero no está paralizada.)'),
(1572,68,1,NULL,'Guarda lo justo: — Unas mudas, su cepillo de dientes, una carpeta con documentos.— El móvil. El cargador.  — El diario.'),
(1573,68,1,NULL,'(Se detiene. Respira. Escucha el silencio. Aún no se oyen llaves en la puerta.)'),
(1574,68,1,12,'(Va a la mesa del salón.Arranca una hoja de su libreta y escribe con trazos nerviosos'),
(1575,68,1,NULL,'(Dobla el papel. Lo deja sobre la mesa del salón )'),
(1576,68,1,NULL,'(De pronto, pasos en la escalera. La voz que no quería oír.)'),
(1577,68,1,1,'(Se detiene en seco al verla, con la mochila al hombro.) —¿Adónde crees que vas?'),
(1578,68,1,1,'¿Qué? ¿Así nada más? ¿Y todo lo que hemos pasado? ¿Vas a tirarlo todo?'),
(1579,68,1,1,'No puedes hacer esto. Yo te necesito.¡Esto es una locura!'),
(1580,68,1,1,'No te vas a ir. No puedes dejar esto así. No me puedes dejar así.'),
(1581,68,1,1,'¡¿Tú te crees con derecho a hablar de vida ahora?! ¡Después de todo lo que hice por ti!'),
(1582,68,1,1,'Si te vas, no vuelvas. No vas a encontrar a nadie que aguante lo que yo he aguantado de ti.'),
(1583,69,1,NULL,'(El aire es frío, pero no más que la casa que ha dejado atrás. )'),
(1584,69,1,11,'Mira el móvil. Eva le ha hablado: “Ven. Te espero.”'),
(1585,69,1,NULL,'(Por primera vez, el miedo no ha sido más fuerte que su decisión. )'),
(1586,69,1,NULL,'¡Enhorabuena, has terminado Bella´s Heart!'),
--CAP9.3
(1587,70,1,NULL,'(Es de noche. En el salón, la televisión suena de fondo pero nadie la está viendo.)'),
(1588,70,1,NULL,'(Bella ha pasado el día en tensión. David ha estado irritable, evitando hablar.)'),
(1589,70,1,NULL,'(Ahora, están sentados en extremos opuestos del sofá. La distancia entre ellos se siente como un abismo.)'),
(1590,70,1,1,'(La mira)'),
(1591,70,1,1,'¿Cómo que no quieres seguir así?'),
(1592,70,1,1,'(Suelta una carcajada seca. Se pone de pie. Camina unos pasos. Luego se gira, de golpe.)—¿Y justo ahora? ¿Después de todo lo que hice por ti?'),
(1593,70,1,1,'¿Es por ese imbécil del trabajo? ¿Te ha comido la cabeza?'),
(1594,70,1,1,'No hables en plural. Tú eres la que lo está jodiendo todo.(Se lleva las manos al pelo. Empieza a elevar la voz.)'),
(1595,70,1,1,'Primero te haces la víctima, luego me culpas, y encima te vas. ¡Qué fácil, Bella!'),
(1596,70,1,1,'(Se acerca. Demasiado.)—¿Salir?'),
(1597,70,1,1,'(Resopla. Se lleva el puño cerrado al pecho.)—¡Yo te he aguantado más de lo que cualquiera hubiera hecho!'),
(1598,70,1,1,'(Se le tensa el rostro. Habla más fuerte.) —¡Tú no vas a decidir por los dos! ¡Esto no es un juego!'),
(1599,70,1,1,'(La interrumpe con un grito.) —¡Cállate!'),
(1600,70,1,1,'(La mira con los ojos encendidos, respiración agitada.)—¡No me provoques!'),
(1601,70,1,1,'(De pronto, con un movimiento seco y furioso, levanta la mano y le cruza la cara con un golpe. El sonido del impacto se mezcla con el silencio que cae de inmediato.)'),
(1602,70,1,1,'(Respira fuerte. El pecho se le mueve violentamente.)—Mira lo que me haces hacer…'),

(1603,70,1,1,'(Patea una silla.)—¡Mierda, Bella! ¡Mirá lo que me haces hacer!'),
(1604,70,1,NULL,'(Luego, sin mirar atrás, se dirige al pasillo.)'),
(1605,70,1,NULL,'(David se mete en el baño y cierra la puerta, se escucha el agua correr)'),
(1606,70,1,NULL,'(Una idea cruza la mente de Bella)'),
(1607,70,1,NULL,'(Avanza sin ruido)'),
(1608,70,1,NULL,'(No lleva bolso. Solo el móvil)'),
(1609,70,1,NULL,'(Pasa por la entrada, abre la puerta con cuidado, y sale.)'),
(1610,71,1,NULL,'(Corre)'),
(1611,71,1,NULL,'(La calle está fría. No sabe adónde va)'),
(1612,71,1,NULL,'(Mira atrás cada pocos metros.)'),

(1613,71,1,NULL,'Bella está sentada en un banco del parque, el móvil en la mano. No ha llamado a nadie aún. Mira el cielo.'),
(1614,71,1,NULL,'(Le tiemblan los dedos.Abre WhatsApp. Duda.)'),
(1615,71,1,11,'Luego le escribe a su amiga Eva'),
(1616,71,1,11,'Eva: Claro. Ven. Estoy despierta'),
(1617,71,1,NULL,'El viento le pega en la cara. No tiene una maleta. Ni cepillo de dientes. Ni llaves. Solo miedo y decisión.'),
(1618,71,1,NULL,'¡Enhorabuena, has terminado Bella´s Heart!'),
--CAP9.4
(1619,72,1,NULL,'(Es de noche. La casa está en silencio, pero el aire está cargado, casi irrespirable. )'),
(1620,72,1,NULL,'(Bella ha esperado a que termine la cena. Tiene el rostro serio.)'),
(1621,72,1,NULL,'(Lleva días pensando cómo hacerlo. Ya no quiere discutir, solo decirlo.)'),
(1622,72,1,NULL,'(Se sienta frente a David en el salón. Lo mira directo a los ojos. No tiembla.)'),
(1623,72,1,1,'(Deja el móvil en la mesa. La observa con una ceja levantada.)—Dime.'),
(1624,72,1,1,'(La mira)'),
(1625,72,1,1,'(Silencio. David no parpadea. La expresión le cambia lentamente: primero sorpresa, luego ira contenida.)'),
(1626,72,1,1,'(Con la voz baja, pero tensa.)—No.'),
(1627,72,1,1,'(Suelta una risa seca. Se pone de pie bruscamente. Da un paso hacia ella.)—¿Qué estás diciendo? ¿Que después de todo lo que hice por ti… ahora te vas? ¿Así como así?'),
(1628,72,1,1,'¿Tienes a alguien más? ¿Ya tenías esto planeado? ¡Eres una mentirosa!(Golpea la mesa con fuerza.) '),
(1629,72,1,1,'¡Tú sin mí no eres nada! ¡Eres una desagradecida! ¡Una inútil!'),
(1630,72,1,NULL,'(Bella se da la vuelta. Camina.)'),
(1631,72,1,1,' (David va detrás.)'),
(1632,72,1,1,'(Se adelanta y bloquea la entrada del dormitorio.)—No, no vas a encerrarte. No vas a largarte sin más. Aquí no termina nada. Aquí mando yo.'),
(1633,72,1,1,'(Se acerca. Está demasiado cerca. Su rostro, rojo de rabia.)—No te vas. Te lo juro, Bella. Si haces esto, lo vas a lamentar.'),
(1634,72,1,1,'(Se ríe. No es una risa alegre. Es amarga, burlona.)—¿Qué crees? ¿Que eres una víctima? ¿Que puedes irte y dejar todo atrás como si nada?'),
(1635,72,1,1,'(Camina hacia ella. Agitado. Se acerca con el dedo en alto.)—¡Me has empujado a esto! ¡Yo lo doy todo por ti y tú solo piensas en dejarme como un perro!'),
(1636,72,1,1,'¡Tú no vas a decidir eso sola!'),
(1637,72,1,1,'(De pronto, en un estallido de rabia, le lanza una bofetada con la mano. )'),
(1638,72,1,1,'(Silencio absoluto. Solo se oye su respiración agitada.)'),
(1639,72,1,1,'(Patea una silla.)—¡Mierda, Bella! ¡Mirá lo que me haces hacer!'),
(1640,72,1,NULL,'(Luego, sin mirar atrás, se dirige a la puerta de la entada.)'),
(1641,72,1,NULL,'(Portazo) '),
(1642,72,1,NULL,'(Después de unos segundos, se deja caer al suelo del pasillo)'),
(1643,72,1,NULL,'(Respira hondo. Vuelve a tomar el móvil. Abre sus contactos. Sus dedos tiemblan sobre la pantalla. Busca un nombre.)'),
(1644,72,1,NULL,'(La duda la atraviesa. ¿Y si no contesta? ¿Y si no puede hablar?)'),
(1645,72,1,NULL,'(Pero pulsa el botón de llamada.)'),
(1646,72,1,NULL,'(Sonido del móvil marcando. Una, dos, tres veces…)'),
(1647,72,1,11,'Eva: —¿Bella? ¿Todo bien?'),
(1648,72,1,11,'(Alerta inmediata.)—¿Qué ha pasado? ¿Estás bien?'),
(1649,72,1,11,'Quédate ahí. Voy en camino.'),
(1650,72,1,11,'Vale. Escúchame. Quiero que cojas una bolsa. Lo que puedas: documentos, algo de ropa, lo esencial. ¿Me oyes?'),
(1651,72,1,11,'Voy en camino. Solo mantén el teléfono cerca.'),
(1652,72,1,NULL,'(Con un esfuerzo, se pone de pie. Guarda el móvil en el bolsillo. Luego, con pasos cuidadosos, abre la puerta y cruza hacia la habitación.)'),
(1653,73,1,NULL,'(Se mueve con rapidez, intentando hacer poco ruido. )'),
(1654,73,1,NULL,'(Toma una bolsa de tela del armario, comienza a meter ropa, su cargador, documentos…)'),
(1655,73,1,NULL,'(Mientras está guardando las cosas... Se escucha la puerta)'),
(1656,73,1,NULL,'(David ha vuelto.)'),
(1657,73,1,1,'(Desde la puerta, en voz baja pero clara.) —¿Qué haces?'),
(1658,73,1,1,'(Se acerca despacio. No grita.)—Bella, no… no lo hagas así.'),
(1659,73,1,1,'(Se lleva las manos a la cabeza. Respira hondo.) —Yo… Perdón. No quise hacerte daño. No sé qué me pasó. Fue un momento. No soy así.'),
(1660,73,1,1,'Te juro que no va a volver a pasar. Pero tú también me empujas, Bella. Me llevas al límite. No ves cómo me hablas… cómo me ignoras. ¿Qué esperas que haga?'),
(1661,73,1,1,'(Camina hacia ella, lento.) —No. Tú no vas a ningún sitio.'),
(1662,73,1,1,'(Él se lanza hacia la puerta, cierra con fuerza y gira la llave, atrapándola dentro. La tensión en el ambiente se vuelve irrespirable.)'),
(1663,73,1,1,'¿Tú te crees que puedes irte así? ¿Después de todo lo que he hecho por ti?'),
(1664,73,1,1,'(Silencio)'),
(1665,73,1,1,'(Le grita a centímetros del rostro)—¡Claro que no me reconoces! ¡Porque solo ves lo que quieres! ¡Todo lo que hice por ti, y así me lo pagas! ¡Eres una ingrata!'),
(1666,73,1,1,'¡Cállate!'),
(1667,73,1,1,'(La agarra del brazo con fuerza. Bella intenta soltarse. Forcejean. David la empuja. )'),
(1668,73,1,1,'Silencio.'),
(1669,73,1,1,'No vas a irte'),
(1670,73,1,1,'¡¿Me oyes?!'),
(1671,73,1,1,'¡NO VAS A IRTE!'),
(1672,74,1,null,'...'),
(1673,75,1,null,'Última hora. '),
(1674,75,1,null,'Hallan el cuerpo de una mujer sin vida en su vivienda.'),
(1675,75,1,null,'Se investigan las circunstancias del suceso como un posible caso de violencia muchista.'),
(1676,75,1,null,'Según fuentes cercanas a la investigación, el presunto autor sería su pareja sentimental, que ya ha sido detenido'),
(1677,75,1,null,'Las autoridades recuerdan que existen recursos para denunciar y pedir ayuda...'),
(1678,76,1,null,'Has terminado Bella`s Heart');





