(61, 'Ya estoy lista ,¿ nos vamos ?', 0,0, 62, NULL),
(62, '(Sonríe mientras busca su bolso.) —Sí, claro que me acuerdo. Es bonita, pero hoy quiero llevar esto.',0,0,63,NULL),
(63, '(Frunce el ceño ligeramente, sin perder la sonrisa.)—¿Por qué? ¿No te gusta cómo me veo con esto? ',0,0,64,NULL),
(64, '(Ríe suavemente, cediendo.) —Bueno, ya que insistes... Supongo que puedo ponerme la blusa',5,2,65,NULL),
(64, '(Se cruza de brazos, con un tono más curioso.)—Parece que no te gusta que me ponga lo que quiero.',0,0,66, NULL),
(65, '(Sonríe) -Venga me cambio rápido que vamos a llegar tarde',0,0, 69,NULL),
(66, 'Entiendo lo que dices, pero también me gusta ponerme lo que me hace sentir bien. Hoy quiero usar esto.',0,0,67, NULL),
(67, '(Suspira)—No es que no me guste la blusa, David. Me la he puesto varias veces.Hoy prefería otra cosa...', 0,0,68,NULL),
(68, '—Está bien… me pondré la blusa. No quiero que pienses que no me gusta. Ya sabes que me encanta',0,0,69,NULL),
