(73, '(Continuar)',0,0,74,NULL),
(74, '(Sonríe animada.)—¡Sí, es verdad! Ha pasado bastante tiempo. Me alegra mucho verte aquí. ¿Cómo te ha ido?',0,0,75,NULL),
(75, 'Sí, me mudé hace poco con David. Ha sido un gran paso, pero la verdad es que estamos adaptándonos bien.',0,0,76,NULL),
(76,'Sí, está por ahí hablando con algunos amigos. Quería presentarte, pero parece que está entretenido.',0,0,77,NULL),
(77, '(Ríe ligeramente.)—Gracias, Alex. Es lindo escuchar eso.',0,0,NULL,NULL),
(78, '¡Fue una noche genial! Hacía mucho que no veía a todos. Me alegra que hayamos ido. ¿Te divertiste?',0,0,79,NULL),
(79,'(Frunce ligeramente el ceño.)—¿Incómodo? ¿Por qué? ¿Pasó algo?',0,0,80,NULL),
(80, '(Ríe)—¿Alex? Es solo un amigo. Nos conocemos desde hace tiempo. Solo estábamos poniéndonos al día. ',0,0,81,NULL),
(81, '¿Malinterpretar? ¿Por qué alguien haría eso? No creo que haya dado motivos para que piensen algo raro.',0,0,82,null),
(82, 'David, sé cuidarme. No voy a cambiar cómo hablo con la gente solo por miedo a lo que otros puedan pensar.',0,0,83,NULL),
(83, 'David… entiendo que te preocupes asi que tal vez pueda ser un poco más reservada en futuras reuniones',5,2,84,NULL),
(83, 'David, entiendo que te preocupes, pero me siento un poco incómoda con esto.',2,5,85,NULL),
(84, '(Asiente lentamente, con una sonrisa forzada.)—Está bien. Intentaré tener más cuidado. ',0,0,86,NULL),
(85, 'Entiendo lo que dices, pero tampoco quiero cambiar completamente la forma en que soy.',0,0,87,NULL),
(86, '(Suspira internamente)—Espero que podamos manejar estas cosas juntos, sin que se convierta en un problema. ',0,0, 89, NULL),
(87, 'De acuerdo… tal vez pueda ser un poco más cuidadosa. Pero también necesito que confíes en mi. ',0,0,88,NULL),
(88, '(Sonríe, aunque siente una pequeña incomodidad)—Espero que podamos encontrar un equilibrio en esto', 0,0,89,NULL),
(89, 'Sí, me parece bien. De hecho, llevo tiempo queriendo ver esa película que me encanta. ¿Te acuerdas? ',0,0,90,NULL),
