(163, '(Continuar)',0,0,164, null),
(164, 'No sé… estoy bastante agotada. Pensé en quedarnos aquí, pedir algo y ver una peli tranquila.',0,0,165, null),
(165, 'No es eso, David. Solo estoy muy cansada, el día ha sido largo.',0,0,166, null),
