(167,'(Continuar)',0,0,169,null),
(168,'Sé que quieres salir, y me gusta cuando lo propones.Pero hoy… necesito parar. ',0,0,170,null),
(169,'Está bien.',0,0,171,null),
(170,'Y yo te agradezco que lo intentes. Pero también necesito que entiendas que no siempre puedo.',0,0,172,null),
(171,'(Se detiene en la puerta del dormitorio. Lo mira) —Tampoco quiero que se pierda, David. ',0,0,173,null),
(172, '¿Pedimos algo?Puedo poner la peli que te gusta. Me apetece estar contigo, pero tranquila.',0,0,174,null),
