(180,'(Sorprendida.)—Sí. ¿Por qué? ',0,0,181,null),
(181,'Estoy cansada, eso es todo. ',0,0,182,null),
(182,'Últimamente tengo muchas cosas encima. Trabajo, plazos, reuniones...',0,0,183,null),
