(184,'No estás al margen.',0,0,185,null),
(185,'(Lo observa en silencio)—No es que no haga espacio para ti. Es que a veces no queda espacio para nada.',0,0,186,null),
(186,'Las cosas han cambiado. No solo entre nosotros. En general. Hay más responsabilidades. Más presión.',0,0,187,null),
(187,'Tienes razón. Últimamente he estado muy metida en todo lo demás. Pero voy a intentar cambiar eso.',5,1,188,null),
