(189,'Entiendo que lo sientas así. Pero necesito que entiendas que no es por falta de amor. ',0,0,191,null),
(190,'(Sonríe, débilmente.)—Lo sé. Voy a intentar hacer más espacio para nosotros.',0,0,192,null),
