(192,'Me alegra escucharlo.No quiero pelear. Solo quiero estar bien contigo.',0,0,196,null),
(193, '(Lo observa, percibe el cambio.)No quiero que te calles por estar molesto.',0,0,194,null),
(194, 'Estoy tratando de ser honesta contigo... ',0,0,195,null),
(195, '(Asiente lentamente. No dice nada más.)',0,0,197,null),
(196, 'Jugar Escena Extra',0,0,null,null),
