(198, '(Continuar)',0,0,199,null),
(199, '(Continuar)',0,0,200,null),
(200, '(Continuar)',0,0,201,null),
(201, 'He quedado esta noche con las chicas del trabajo. Una cena informal, nada del otro mundo.',0,0,202,null),
(202, 'Salió sobre la marcha esta mañana. Ya sabes cómo son.',0,0,203,null),
(203, 'Laura, Ana, Miriam, creo que Eva también.',0,0,204,null),
(204, 'No me mete ideas raras. Tiene su forma de ver las cosas, como tú tienes la tuya... ',0,0,205,null),
(205, 'No tengo ni idea. Supongo que un par de horas, depende.',0,0,206,null),
(206, '(Frunce el ceño apenas un segundo.)—¿A qué te refieres?',0,0,207,null),
(207, '(Suspira y le sonríe con suavidad.)—No te preocupes. Me iré pronto. Te mando un mensaje cuando llegue.',5,1,208,null),
(207, 'David, no pasa nada. No necesito que me digas con quién tengo que tener cuidado. Sé cuidar de mí. ',-1,5,209,null),
(208, '(Su sonrisa se mantiene.)—Claro. Lo entiendo.',0,0,210,null),
(209, '(Se cruza de brazos, sin levantar la voz.)—Confía en mí. No pasa nada. Solo voy a cenar con amigas. ',0,0,211,null),
(210,'Lo tendré en cuenta.',0,0,212,null),
(211,'Lo tengo. Siempre lo tengo.',0,0,213,null),
(212,'Lo haré. ',0,0,215,null),
(213,'Lo sé. Y yo valoro que te preocupes.',0,0,214,null),
(214,'Lo tendré en cuenta.',0,0,215,null),
(215,'Gracias.',0,0,null,null),
(216,'(Continuar)',0,0,217,null),
(217,'(Continuar)',0,0,218,null),
(218,'(Continuar)',0,0,219,null),
(219,'(Continuar)',0,0,220,null),
(220,'(Sonríe ligeramente, buscando las palabras.)—Muy bien. Normal',0,0,221,null),
(221,'Sí… es que ya sabéis, después de un tiempo todo se vuelve más tranquilo.Rutina, trabajo, poco tiempo… eso.',0,0,222,null),
(222,'Sí. Después de un tiempo todo baja el ritmo.Nos vemos menos, hablamos más rápido… Pero está bien.',0,0,223,null),
(223,'(Pausa breve. Mira su copa. Luego responde.)—Acostumbrada, supongo.',0,0,224,null),
(224,'Bueno, también hay que elegir las batallas, ¿no? Si sabes cómo evitar que algo se complique, lo haces.',0,0,225,null),
(225,'David no es malo. Él a veces necesita más atención y si eso lo ayuda a estar tranquilo, yo lo entiendo. ',5,1,226,null),
(225,'No es que me agobie cada día. Pero sí me doy cuenta de que hay cosas que evito para que no se incomode.',-1,5,227,null),
(226,'No es sostenerla. Es… acompañarlo.Si sé que algo le va a incomodar, prefiero evitarlo. No me cuesta tanto.',0,0,228,null),
(227,'Depende. Si estoy cansada o el día ya ha sido complicado, prefiero no añadirle más cosas.',0,0,229,null),
(228,'Es que si nos queremos,también toca entender al otro.Pero no me controla ni me grita ni nada por el estilo',0,0,230,null),
(229,'No lo sé. Tal vez sí. Pero si lo nota, no dice nada.',0,0,231,null),
(230,'(Continuar)',0,0,232,null),
(231,'Normal. Solo… desconectada a ratos. Como si tuviera que ir con cuidado.Pero tampoco quiero exagerar.',0,0,233,null),
(232,'Vale, quizás me estoy explicando mal. Solo digo que él es así. Que lo entiendo. ',0,0,234,null),
(233,'(Sonríe.Se esfuerza por mantener el tono relajado.)—Puede ser.Pero de momento lo llevo.No hay nada roto.',0,0,235,null),
(234,'(Asiente. Bebe un poco de vino. La conversación se desvía hacia otro tema, pero la tensión queda)',0,0,236,null),
(235,'Gracias. De verdad.No estoy mal, solo… un poco cansada, por el trabajo.',0,0,236,null),
(236,'(Continuar)',0,0,237,null),
(237,'(Continuar)',0,0,238,null),
(238,'(Ahora después le respondo)',0,0,239,null),
(239,'(Continuar)',0,0,240,null),
(240,'"Todo bien ❤️” (Lo deja de nuevo boca abajo)',0,0,241,null),
(241,'(Continuar)',0,0,242,null),
(242,' “Sí, está, pero todo tranquilo” ',0,0,243,null),
(243,'(Contestar los mensajes de inmediato)',5,1, 245,null),
(243,'(Dejar de contestar por un tiempo para disfrutar de la reunión)',-1,5,244,null),
(244,'(Continuar)',0,0,246,null),
(245,'“David, estoy bien. De verdad.Solo estoy charlando con las chicas. Nada raro. Solo cena y conversación.❤️”',0,0,247,null),
(246,'(Se gira hacia sus amigas, sonríe y vuelve a la conversación)',0,0,248,null),
(247,'“Seguimos en el mismo sitio. Estamos pidiendo postre.”',0,0,249,null),
(248, '(Continuar)',0,0,250,null),
(249,' “Nada de locuras. Solo cena tranquila. No te preocupes, no me voy a quedar muy tarde.” ', 0,0,251,null),
(250,'(Continuar leyendo)',0,0,252,null),
(251,'(Continuar)', 0,0,253,null),
(252,'(Continuar leyendo)',0,0,254,null),
(253,'(Continuar)',0,0,255,null),
(254,'(Continuar leyendo)',0,0,256,null),
(255,'“Sí, claro. En un rato.”',0,0,262,null),
(256,'(Continuar leyendo)',0,0,257,null),
(257,'(Continuar leyendo)',0,0,258,null),
(258,'(Suspira. Mira a sus amigas un segundo, luego se gira y desliza para atender.)—¿Sí?',0,0,259,null),
(259, '(Mezcla de calma y tensión.)—Estaba con las chicas, David. Te dije que era algo tranquilo.',0,0,260,null),
(260, 'No te estoy ignorando. Solo necesito poder estar presente cuando estoy con otras personas también.',0,0,261,null),
(261, 'Vale. Nos vemos luego.(Cuelga)', 0,0,262,null),
(262,'(Continuar)',0,0,263,null),
(263,'(Su voz es suave, honesta.)—Sí. Gracias',0,0,264,null),
(264, '(Continuar)',0,0,265,null),
(265, '(Continuar)',0,0,266,null),
(266, '(Continuar)',0,0,267,null),
(267, '(Mira su bolso. Su móvil vibra de nuevo. No lo saca.)',0,0,268,null),
(268, '(Sonríe con discreción, pero hay algo contenido en sus ojos.) —Mejor no. Creo que voy a irme a ca',0,0,269,null),
(269, 'Sí. Se me ha hecho tarde ya. Además… mejor así. ',0,0,270,null),
(270,'(Abraza a Laura. Se despide una por una.) ',0,0,271,null),
(271, '(Continuar)',0,0,272,null),
(272, '"Ya estoy en el taxi"',0,0,null,null),
(273, 'Hola',0,0,274,null),
(274, '(Suelta el bolso, se quita la chaqueta.)—Sí. Acabábamos de terminar. Me vine directo.',0,0,275,null),
(275, 'Sí. Ha sido una noche tranquila.Al final ellas querían ir a otro bar, pero… no me apetecía quedarme.',0,0,276,null),
(276, 'No. Solo les apetecía seguir. Yo decidí volver.',0,0,277,null),
(277, 'Se quedaron un poco chafadas. Ya sabes cómo son…',0,0,278,null),
(278, 'No lo había pensado así…',5,1,279,null),
(278, 'No estoy de acuerdo.',-1,5,280,null),
(279,'A veces siento que, si no hago lo que esperan, el ambiente cambia.No lo dicen, pero se nota.',0,0,281,null),
(280,'Con lo que has dicho. Que ellas no me aprecian.Ellas solo querían que me lo pasara bien. ',0,0,282,null),
(281,'(Suspira. Se sienta en el sofá. Mira un punto fijo.)',0,0,283,null),
(282,'Me apetecía.No estaba del todo cómoda. Pero eso no tiene que ver con ellas. Tiene que ver conmigo.',0,0,284,null),
(283,'(Baja la mirada. Se queda unos segundos en silencio.)—Tal vez tienes razón...',0,0,285,null),
(284,'(Lo mira en silencio.)',0,0,286,null),
