(291,'(Termina de cortar las verduras y al rato, se seca las manos con el paño y va a buscar su móvil.)',0,0,null,null),
(292, '¿Estás mirando mi móvil?',0,0,293,null),
(293,'(Da un par de pasos hacia él)—¿Urgente para quién?',0,0,294,null),
(294, '¿Por qué lo abriste?',0,0,295,null),
(295, 'David, no abras mis mensajes. No es tu móvil, no es tu conversación. ',-1,5,296,null),
(295, 'Vale',5,1,297,null),
(296, 'Sí. Porque no me gusta. ',0,0,298,null),
(297, 'Sí. Está bien. No pasa nada. ',0,0,299,null),
(298, 'No se trata del contenido.', 0,0,300,null),
(299, 'Sí, bueno, a veces. Aún no hay nada claro. Solo preguntó si estaba disponible para unas fechas.',0,0,301,null),
(300, 'No importa de quién sea el mensaje. Estaba en mi teléfono.Si es importante, me lo dices.Pero no lo abres.',0,0,302,null),
(301, 'No sé. Se me pasó. No estaba confirmado. Supuse que si salía algo, te lo contaría. ',0,0,303,null),
(302, 'No he dicho eso.', 0,0,304,null),
(303, '(Continuar)', 0,0,305,null),
(304, 'No te estoy atacando, David.',0,0,306,null),
(305, '(Bella lo observa alejarse. Luego se queda un momento de pie, sin moverse, con el móvil aún en la mano.)',0,0,309,null),
(306, 'No hace falta que te pongas así.',0,0,307,null),
(307, '(Bella se queda quieta unos segundos, con el móvil en la mano.)',0,0,308,null),
(308, '(Continuar)',0,0,309,null),
(309, '(Continuar)',0,0,null,null),
(310, '(Continuar)',0,0,311,null),
(311, '(Continuar)',0,0,312,null),
(312, '¿Qué es todo esto?', 0,0,313,null),
(313, 'No tenías que…',0,0,314,null),
(314, ' (Bella duda un segundo. Luego se sienta. David se sienta frente a ella.)',0,0,315,null),
(315, '(Continuar)', 0,0,316,null),
(316, '(Lo observa en silencio.)',0,0,317,null),
(317, '(Aprieta los labios. Baja un poco la mirada.)', 0,0,318,null),
(318, '(Respira hondo. Tono suave.)—David… ',0,0,319,null),
(319, 'No tienes que tener miedo. No estoy yéndome a ningún lado.',5,1,320,null),
(319, 'No quiero que estemos mal.Tampoco me gusta discutir contigo por cosas que podríamos hablar con calma.',-1,5,321,null),
(320, 'No digas eso.(Le acaricia suavemente la mano.)',0,0,322,null),
(321, 'No es eso. Solo… hay momentos en los que me siento un poco saturada.',0,0,323,null),
(322, 'Eso no va a pasar. Yo te quiero, David. No hay nadie más en mi cabeza, ni en mi vida. ',0,0,324,null),
(323, 'Pero te quiero. Tú y yo podemos con esto. Pero tienes que confiar más en mí. ',0,0,325,null),
(324, 'Yo no necesito a alguien más. Te necesito a ti. Y si tienes dudas, aquí estoy para recordartelo',0,0,326,null),
(325, 'Entonces me lo dices. Me lo hablas. Y yo haré lo mismo.',0,0,327,null),
(326, 'No tienes que pedir perdón por sentir cosas. Yo también me equivoco.',0,0,328,null),
(327, '(Le sonríe apenas, con un poco de cansancio en la expresión.)—A veces con eso ya es suficiente.',0,0,328,null),
(328,'Sí',0,0,329,null),
(329,'(Continuar)',0,0,330,null),
(330,'(Continuar)',0,0,null,null),
(331,'(Continuar)',0,0,332,null),
(332, '(Levanta la vista.)—¿Qué viaje? ',0,0,333,null),
(333, 'Sí. Marco lo confirmó esta tarde.Es solo un par de días. ',0,0,334,null),
(334, 'Sí. Soy parte del equipo de ese proyecto. Y ya está aprobado por dirección. ',0,0,335,null),
(335, '(Se queda callada. Luego responde con calma.)—No. Es parte de mi trabajo.',0,0,336,null),
(336, 'Sí. Va él, Laura y dos más de oficina técnica.',0,0,337,null),
(337, '(Lo observa, midiendo el momento. Decide no decir nada.)',0,0,338,null),
(338, '(Traga saliva. Baja el móvil. Lo apaga. Lo deja a un lado.) —David…',0,0,339,null),
(339, 'No, David.No voy a decir que no al viaje',-1,5,340,null),
(339, 'Solo es un par de días.No va a pasar nada. Estaré ocupada todo el tiempo.',5,1,342,null),
(340, 'No. Pero no puedo tomar decisiones laborales según cómo te sientas tú. ',0,0,341,null),
(341, 'David, sé que esto te remueve cosas. Y entiendo que te sientas incómodo. Pero voy a ir al viaje.',0,0,343,null),
(342, 'Podremos hablar cuando haga falta… no quiero que esto sea un problema.',0,0,344,null),
(343, 'Ya me lo pensé. Y decidí que quiero ir',0,0,346,null),
(344, 'No lo haces.Es solo… no quiero que esto nos complique más. ',0,0,345,null),
(345, 'Ya lo sé. Y no quiero que sientas eso. Si no ir significa evitar esta tensión, me lo pensaré.',0,0,347,null),
(346, 'David...',0,0,349,null),
(347, 'Tú sí encajas. Solo que… Todo va muy deprisa a veces. Y no quiero que eso nos arrastre.',0,0,348,null ),
