(1027,'(Se detiene. La tensión en la habitación es inmediata. Ella ya conoce ese tono.) ',0,0,1028,null),
(1028,'Era una pausa con el equipo. Nada más.',-1,1,1029,null),
(1028,'Era una salida con mis compañeros. Del trabajo. ',-2,5,1030,'STABLE'),
(1028,'No… no es lo que piensas. Fue solo una charla rápida. No me quedé mucho.',2,3,1031,'SLIGHTLY_ANXIOUS'),
(1028,'Perdón.Estábamos saliendo del edificio y los del equipo propusieron parar a tomar algo. Fue solo eso.',3,2,1032,'ANXIOUS'),
(1028,'No sabía que te molestaría. Perdón. ',4,1,1033,'DISTRESSED'),
(1029,'No es eso. Pero no tengo energías para convertir cada conversación en una discusión.',0,0,1034,null),
(1034,'No es que no puedas preguntar. Es que esto no es una conversación, David. Es una acusación.',0,0,1035,null),
(1035,'(No responde.)',0,0,1044,null),
(1030,'¿En serio estás haciendo una escena por esto?(Se cruza de brazos.)',0,0,1036,null),
(1036,'Era una salida con mis compañeros. Del trabajo.',0,0,1034,null),
(1031,'Pensé que no era tan importante… que no hacía falta. De verdad, David, fue espontáneo. Nadie lo planeó. ',0,0,1037,null),
(1037,'(No sabe qué contestar.)',0,0,1038,null),
(1038,'(Baja la mirada, avergonzada de su propio argumento. La conversación se enfría)',0,0,1044,null),
(1032,'Te escribí después. Solo tardé un poco. No lo hice con mala intención. Es que me distraje',0,0,1039,null),
(1039,'No, fue idea de todos. Pero no estuve ni una hora. No fue nada raro, te lo juro ',0,0,1040,null),
(1040,'Lo siento si te hizo sentir mal. No pensé que se vería así. Sé que debería habértelo dicho.',0,0,1041,null),
(1041,'No fue así… solo no pensé que fuera para tanto. ',0,0,1044,null),
(1033,'No era una cita, ni una salida especial. Solo… pasó. Yo no quería que pensaras mal. ',0,0,1042,null),
(1042,'No quería fallarte. Prometo avisarte antes la próxima vez. Lo juro.',0,0,1043,null),
(1043,'(Se queda inmóvil. Luego se sienta al borde de la cama)',0,0,1044,null),
(1044,'(Continuar)',0,0,1045,null),
