(1048,'(Continuar)',0,0,1049,null),
(1049,'(Continuar)',0,0,1050,null),
(1050,'¿Quieres algo de cenar? ',0,0,1051,null),
(1051,'(Va a la cocina. Mientras calienta algo, respira hondo.)',0,0,1052,null),
(1052,'(Continuar)',0,0,1053,null),
(1053,'( Prueba bocado, luego lo intenta.)',0,0,1054,null),
(1054,'¿Sabes? Hoy tuve una reunión complicada con el equipo. Uno de los clientes…',0,0,1055,null),
(1055,'¿Qué pasa?',0,0,1056,null),
(1056,'(Cambiar de tema)',-1,1,1057,null),
(1056,'(Confrontarlo con serenidad)',-2,5,1058,'STABLE'),
(1056,'No, sí… tienes razón. Olvídalo. No era nada.',2,3,1060,'SLIGHTLY_ANXIOUS'),
(1056,'Perdona… no quería sonar egoísta. Solo fue un momento raro en la reunión. Pero no importa.',3,2,1061,'ANXIOUS'),
(1056,'Lo sé. Perdón. No estoy siendo justa contigo.',4,1,1062,'DISTRESSED'),
(1057,'Está bien.',0,0,1062,null),
(1062,'Voy a acostarme pronto, estoy cansada.',0,0,1063,null),
(1063,'(Continuar)',0,0,1077,null),
(1058,'Siento que cuando intento compartir algo, terminas hablando de ti.Me gustaría que me escucharas también.',0,0,1064,null),
(1064,'No estoy atacándote. Te estoy diciendo cómo me siento. ',0,0,1065,null),
(1065,'Quiero poder hablar contigo de las cosas',0,0,1066,null),
(1066,'(Continuar)',0,0,1077,null),
(1059,'Es solo que… hoy pasó algo que me dejó un poco mal. En el trabajo…',0,0,1067,null),
(1067,'(Continuar)',0,0,1068,null),
(1068,'Claro… sí. Perdón. No era nada importante.',0,0,1069,null),
(1069,'(Continuar)',0,0,1077,null),
(1060,'Cuéntame tú, ¿cómo estás? ',0,0,1070,null),
(1070,'Ya… perdona si he estado rara. De verdad quiero que estés bien.',0,0,1071,null),
(1071,'(Continuar)',0,0,1072,null),
(1072,'(Continuar)',0,0,1077,null),
(1061,'Yo debería estar más atenta. Dejar de pensar tanto en mí.',0,0,1073,null),
(1073,'Sí… tienes razón.',0,0,1074,null),
(1074,'(Continuar)',0,0,1075,null),
(1075,'Perdona. ¿Quieres que te prepare un té?',0,0,1076,null),
(1076,'(Continuar)',0,0,1077,null),
