(1082,'(Continuar)',0,0,1083,null),
(1083,'(Se gira, algo confundida por el tono.)—Fui a por un par de cosas.',0,0,1084,null),
(1084,'(Suspira, intenta mantener la calma.)—Porque estaba caminando, David. Y pensé que estaba bien',0,0,1085,null),
(1085,'(Se queda paralizada.)',0,0,1086,null),
(1086,'(Intentar calmarlo)',-1,1,1087,null),
(1086,'(Intentar defenderse)',-2,5,1088,'STABLE'),
(1086,'(Intentar explicarse)',2,3,1089,'SLIGHTLY_ANXIOUS'),
(1086,'Por favor, no te pongas así…',3,2,1090,'ANXIOUS'),
(1086,'(No responder)',4,1,1091,'DISTRESSED'),
(1087,'(Con voz suave, evitando elevar el tono.)—David… por favor. Solo salí un momento. ',0,0,1092,null),
(1092,'No pasó nada raro. Estoy aquí, contigo. Podemos hablarlo con calma',0,0,1093,null),
(1093,'Sé que te molestó. Pero no estoy haciendo nada malo.',0,0,1094,null),
(1094,'Estoy aquí. Te lo estoy diciendo ahora. No quiero pelear. ',0,0,1095,null),
(1095,'(Continuar)',0,0,1096,null),
(1096,'(Continuar)',0,0,1097,null),
(1097,'(Continuar)',0,0,1105,null),
(1088,'No te estoy escondiendo nada. No te estoy mintiendo.',0,0,1098,null),
(1098,'(No sabe que responder) ',0,0,1099,null),
(1099,'Sé que te molestó. Pero no estoy haciendo nada malo',0,0,1094,null),
(1089,'No… no fue para tanto. Solo salí a caminar.No es como piensas…(Sus palabras se amontonan, torpes.)',0,0,1100,null),
(1100,'No quería molestarte… creí que no pasaba nada. Iba a decirte, pero no cogí el móvil. Fue solo un rato',0,0,1101,null),
(1101,'(Asiente)',0,0,1095,null),
(1090,'Por favor, no te pongas así… No quería esto. Fue mi culpa. Lo siento. Te juro que no fue a propósito.',0,0,1102,null),
(1102,'(Se lleva las manos a la cara. Las lágrimas caen.) ',0,0,1103,null),
(1103,'Lo siento. Voy a estar más atenta, lo prometo. No quise hacerte sentir así. ',0,0,1095,null),
(1091,'(Baja la mirada. No contesta. Siente las lágrimas quemándole los ojos. ) ',0,0,1104,null),
