(1112,'(Se detiene. El aire parece congelarse. Se limpia las manos con un paño)',0,0,1113,NULL),
(1113,'¿Desde cuándo te fijas en mis reacciones? No hice nada malo. ',-1,1,1114,NULL),
(1113,'No tengo nada que ocultar',-2,5,1115,'STABLE'),
(1113,'Es solo una reacción, David. Es compañero, nada más.',2,3,1116,'SLIGHTLY_ANXIOUS'),
(1113,'Ya lo borro todo si te molesta, de verdad. No quiero problemas. ',3,2,1117,'ANXIOUS'),
(1113,'Toma, revisa el móvil si quieres… no tengo nada que esconder',4,1,1118,'DISTRESSED'),
(1114,'No quiero demostrar nada. No hice nada malo.',0,0,1119,NULL),
(1119,'(Continuar)',0,0,1120,NULL),
(1120,'De verdad que no quiero discutir por esto.',0,0,1121,NULL),
