(1122,'(Apoya la espalda en la pared ) ',0,0,1123,NULL),
(1123,'(Continuar)',0,0,NULL,NULL),
(1115,'David, estás montando una historia de la nada. Es una red social, una reacción. Nada más.',0,0,1124,NULL),
(1124,'No he hecho nada malo.',0,0,1125,NULL),
(1125,'No. ',0,0,1120,NULL),
(1116,'Es solo una reacción, David. Ni lo pensé. Fue automático, como con cualquier otro del equipo.',0,0,1126,NULL),
(1126,'No… o sea, sí, a veces charlamos. Pero en grupo. Nunca solos. Es mi compañero, nada más.',0,0,1127,NULL),
(1127,'Es que no pensé que fuera relevante. Pero te lo cuento ahora…',0,0,1120,NULL),
(1117,'No, no, no. No quiero que esto sea una pelea. Mira, lo borro. Ya está.',0,0,1128,NULL),
(1128,'Tienes razón. No lo voy a seguir más. Y borro todo.',0,0,1129,NULL),
(1129,'Solo quiero que estemos bien. No quiero discutir más.',0,0,1121,NULL),
(1118,'Toma. Míralo todo. No tengo nada que esconder.',0,0,1130,NULL),
