(1229,'(Continuar)',0,0,1230,NULL),
(1230,'(Continuar)',0,0,1231,NULL),
(1231,'¿Sabes que Clara me escribió hoy? Me habló de una vacante en su oficina.Me dijo que encajaría bien.',0,0,1232,NULL),
(1232,'No, no dije nada. Solo… me pareció bonito que pensara en mí.',0,0,1233,NULL),
(1233,'(Continuar)',0,0,1234,NULL),
